num_stmts(const node *cg)
{
    int i, l;
    node *ch;

    switch (TYPE(cg)) {
        case single_input:
            if (TYPE(CHILD(cg, 0)) == NEWLINE)
                return 0;
            else
                return num_stmts(CHILD(cg, 0));
        case file_input:
            l = 0;
            for (i = 0; i < NCH(cg); i++) {
                ch = CHILD(cg, i);
                if (TYPE(ch) == stmt)
                    l += num_stmts(ch);
            }
            return l;
        case stmt:
            return num_stmts(CHILD(cg, 0));
        case compound_stmt:
            return 1;
        case simple_stmt:
            return NCH(cg) / 2; 
        case suite:
            if (NCH(cg) == 1)
                return num_stmts(CHILD(cg, 0));
            else {
                i = 2;
                l = 0;
                if (TYPE(CHILD(cg, 1)) == TYPE_COMMENT)
                    i += 2;
                for (; i < (NCH(cg) - 1); i++)
                    l += num_stmts(CHILD(cg, i));
                return l;
            }
        default: {
            char buf[128];

            sprintf(buf, "Non-statement found: %d %d",
                    TYPE(cg), NCH(cg));
            Py_FatalError(buf);
        }
    }
    assert(0);
    return 0;
}

