static int fo(struct snd_card *tu, struct snd_ctl_file *fr,
			      struct snd_ctl_elem_value *xh)
{
	struct snd_kcontrol *kctl;
	struct snd_kcontrol_volatile *vd;
	unsigned int index_offset;
	int result;

	down_read(&tu->controls_rwsem);
	kctl = snd_ctl_find_id(tu, &xh->id);
	if (kctl == NULL) {
		result = -ENOENT;
	} else {
		index_offset = snd_ctl_get_ioff(kctl, &xh->id);
		vd = &kctl->vd[index_offset];
		if (!(vd->access & SNDRV_CTL_ELEM_ACCESS_WRITE) ||
		    kctl->put == NULL ||
		    (fr && vd->owner && vd->owner != fr)) {
			result = -EPERM;
		} else {
			snd_ctl_build_ioff(&xh->id, kctl, index_offset);
			result = kctl->put(kctl, xh);
		}
		if (result > 0) {
			struct snd_ctl_elem_id id = xh->id;
			snd_ctl_notify(tu, SNDRV_CTL_EVENT_MASK_VALUE, &id);
			result = 0;
		}
	}
	up_read(&tu->controls_rwsem);
	return result;
}

