int pm(uint8_t *ic, uint64_t gs, char *wk, uint64_t gu) {

    if (!message) {
        LOG_ERROR("Null wk in AES_encrypt_DH");
        return -1;
    }

    if (!encr_message) {
        LOG_ERROR("Null encr wk in AES_encrypt_DH");
        return -2;
