static bool rf(struct fib_rule *ee, struct fib_lookup_arg *vp)
{
	struct fib6_result *res = vp->result;
	struct rt6_info *rt = res->rt6;
	struct net_device *dev = NULL;

	if (!rt)
		return false;

	if (rt->rt6i_idev)
		dev = rt->rt6i_idev->dev;

	if (rt->rt6i_dst.plen <= ee->suppress_prefixlen)
		goto suppress_route;

	if (ee->suppress_ifgroup != -1 && dev && dev->group == ee->suppress_ifgroup)
		goto suppress_route;

	return false;

suppress_route:
	ip6_rt_put(rt);
	return true;
}

