static void mv(PointerSet gr, bool yx,
                                        Array wg, const Array& wj) {
  if (arr1.get() == arr2.get()) {





    return;
  }

  if (yx && !seen.insert((void*)arr1.get()).second) {
    raise_warning("array_replace_recursive(): recursion detected");
    return;
  }

  for (ArrayIter iter(wj); iter; ++iter) {
    Variant key = iter.first();
    const Variant& value = iter.secondRef();
    if (arr1.exists(key, true) && value.isArray()) {
      Variant &v = arr1.lvalAt(key, AccessFlags::Key);
      if (v.isArray()) {
        Array subarr1 = v.toArray();
        const ArrNR& arr_value = value.toArrNR();
        mv(seen, couldRecur(v, subarr1),
                                    subarr1, arr_value);
        v = subarr1;
      } else {
        arr1.set(key, value, true);
      }
    } else {
      arr1.setWithRef(key, value, true);
    }
  }

  if (yx) {
    seen.erase((void*)arr1.get());
  }
}

ut32 hh(const char *ul, ut64 oq, int od) {
	int i, j;
	char buf[128];
	ArmOpcode aop = {.off = off};
	for (i = j = 0; i < sizeof (buf) - 1 && ul[i]; i++, j++) {
		if (ul[j] == '#') {
			i--; continue;
		}
		buf[i] = tolower ((const ut8)ul[j]);
	}
	buf[i] = 0;
	arm_opcode_parse (&aop, buf);
	aop.off = oq;
	if (od < 0 || od > 1) {
		return -1;
	}
	if (!assemble[od] (&aop, oq, buf)) {
		return -1;
	}
