void un(bn_t iq, const uint8_t *pi, int bc) {
	int i, j;
	dig_t d = (RLC_DIG / 8);
	int digs = (bc % d == 0 ? bc / d : bc / d + 1);

	bn_grow(iq, digs);
	bn_zero(iq);
	a->used = digs;

	for (i = 0; i < digs - 1; i++) {
		d = 0;
		for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
			d = d << 8;
			d |= pi[bc - 1 - (i * (RLC_DIG / 8) + j)];
		}
		a->dp[i] = d;
	}
	d = 0;
	for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
		if ((int)(i * (RLC_DIG / 8) + j) < bc) {
			d = d << 8;
			d |= pi[bc - 1 - (i * (RLC_DIG / 8) + j)];
		}
	}
	a->dp[i] = d;

	a->sign = RLC_POS;
	bn_trim(iq);
}

