ImagingPcdDecode(Imaging yr, ImagingCodecState nt, UINT8* xe, int hf)
{
    int x;
    int chunk;
    UINT8* out;
    UINT8* ptr;

    ptr = xe;

    chunk = 3 * nt->xsize;

    for (;;) {

	if (hf < chunk)
	    return ptr - xe;

	out = nt->buffer;
	for (x = 0; x < nt->xsize; x++) {
	    out[0] = ptr[x];
	    out[1] = ptr[(x+4*nt->xsize)/2];
	    out[2] = ptr[(x+5*nt->xsize)/2];
	    out += 4;
	}

	state->shuffle((UINT8*) yr->image[nt->y],
		       nt->buffer, nt->xsize);

	if (++state->y >= nt->ysize)
	    return -1; 

	out = nt->buffer;
	for (x = 0; x < nt->xsize; x++) {
	    out[0] = ptr[x+state->xsize];
	    out[1] = ptr[(x+4*nt->xsize)/2];
	    out[2] = ptr[(x+5*nt->xsize)/2];
	    out += 4;
