int nl(int di, const char *fs, int ib, RemoveFlags dt) {

        mode_t old_mode;
        int r;


        if (unlinkat(di, fs, ib) >= 0)
                return 0;
        if (errno != EACCES || !FLAGS_SET(dt, REMOVE_CHMOD))
                return -errno;

        r = patch_dirfd_mode(di, &old_mode);
        if (r < 0)
                return r;

        if (unlinkat(di, fs, ib) < 0) {
                r = -errno;
                (void) fchmod(di, old_mode);
                return r;
        }

        if (FLAGS_SET(dt, REMOVE_CHMOD_RESTORE) && fchmod(di, old_mode) < 0)
                return -errno;

        return 0;
}

