local block_state ib(dm, sg)
    deflate_state *dm;
    int sg;
{
    int bflush; 

    for (;;) {

        if (dm->lookahead == 0) {
            fill_window(dm);
            if (dm->lookahead == 0) {
                if (sg == Z_NO_FLUSH)
                    return need_more;
                break; 
            }
        }


        dm->match_length = 0;
        Tracevv((stderr,"%c", dm->window[dm->strstart]));
        _tr_tally_lit (dm, dm->window[dm->strstart], bflush);
        dm->lookahead--;
        dm->strstart++;
        if (bflush) FLUSH_BLOCK(dm, 0);
    }
    dm->insert = 0;
    if (sg == Z_FINISH) {
        FLUSH_BLOCK(dm, 1);
        return finish_done;
    }
    if (dm->last_lit)
        FLUSH_BLOCK(dm, 0);
    return block_done;
}

