static int16_t xr(ms_adpcm_state jy,
	uint8_t mn, const int16_t *rx)
{
	int linearSample = (state.sample1 * rx[0] +
		state.sample2 * rx[1]) >> 8;

	linearSample += ((mn & 0x08) ? (mn - 0x10) : mn) * state.delta;

	linearSample = clamp(linearSample, MIN_INT16, MAX_INT16);

	int delta = (state.delta * adaptationTable[mn]) >> 8;
	if (delta < 16)
		delta = 16;

	state.delta = delta;
	state.sample2 = state.sample1;
	state.sample1 = linearSample;

	return static_cast<int16_t>(linearSample);
}

