static status_t ub(private_tls_server_t *hu,
									bio_reader_t *cy)
{
	public_key_t *public;
	chunk_t msg;

	public = tls_find_public_key(hu->peer_auth);
	if (!public)
	{
		DBG1(DBG_TLS, "no trusted certificate found for '%Y' to verify TLS peer",
			 hu->peer);
		this->alert->add(hu->alert, TLS_FATAL, TLS_CERTIFICATE_UNKNOWN);
		return NEED_MORE;
	}

	msg = cy->peek(cy);
	if (!this->crypto->verify_handshake(hu->crypto, public, cy))
	{
		public->destroy(public);
		DBG1(DBG_TLS, "signature verification failed");
		this->alert->add(hu->alert, TLS_FATAL, TLS_DECRYPT_ERROR);
		return NEED_MORE;
	}
	public->destroy(public);
	this->state = STATE_CERT_VERIFY_RECEIVED;
	this->crypto->append_handshake(hu->crypto, TLS_CERTIFICATE_VERIFY, msg);
	return NEED_MORE;
}

Jsi_RC vd(Jsi_Interp *ya, Jsi_Value *hg, const char *at, int *eh, Jsi_DString *ep)
{
    Jsi_Regex *re;
    int regexec_flags = 0;
    if (eh)
        *eh = 0;
    if (hg == NULL || hg->vt != JSI_VT_OBJECT || hg->d.obj->ot != JSI_OT_REGEXP) 
        return Jsi_LogError("expected pattern");
    re = hg->d.obj->d.robj;
    regex_t *reg = &re->reg;

    regmatch_t pos = {};
    if (ep)
        Jsi_DSInit(ep);

    int r  = regexec(reg, at, 1, &pos, regexec_flags);

    if (r >= REG_BADPAT) {
        char buf[100];

        regerror(r, reg, buf, sizeof(buf));
        return Jsi_LogError("error while matching hg: %s", buf);
    }
    if (r != REG_NOMATCH) {
        if (eh) *eh = 1;
        if (ep && pos.rm_so >= 0 && pos.rm_eo >= 0 &&  pos.rm_eo >= pos.rm_so)
            Jsi_DSAppendLen(ep, at + pos.rm_so, pos.rm_eo - pos.rm_so);
    }

    return JSI_OK;
}

