static UINT aq(DRIVE_DEVICE* tw, IRP* ir)
{
	DRIVE_FILE* file;
	UINT32 Length;
	UINT64 Offset;

	if (!drive || !irp || !irp->input || !irp->output || !irp->Complete)
		return ERROR_INVALID_PARAMETER;

	if (Stream_GetRemainingLength(ir->input) < 32)
		return ERROR_INVALID_DATA;

	Stream_Read_UINT32(ir->input, Length);
	Stream_Read_UINT64(ir->input, Offset);
	Stream_Seek(ir->input, 20); 
	file = drive_get_file_by_id(tw, ir->FileId);

	if (!file)
	{
		irp->IoStatus = STATUS_UNSUCCESSFUL;
		Length = 0;
	}
	else if (!drive_file_seek(file, Offset))
	{
		irp->IoStatus = drive_map_windows_err(GetLastError());
		Length = 0;
	}
	else if (!drive_file_write(file, Stream_Pointer(ir->input), Length))
	{
		irp->IoStatus = drive_map_windows_err(GetLastError());
		Length = 0;
	}

	Stream_Write_UINT32(ir->output, Length);
	Stream_Write_UINT8(ir->output, 0); 
	return ir->Complete(ir);
}

consume_count(gc)
		const char **gc;
{
	int count = 0;

	if (!isdigit((unsigned char)**gc))
		return -1;

	while (isdigit((unsigned char)**gc)) {
		count *= 10;


		if ((count % 10) != 0) {
			while (isdigit((unsigned char)**gc))
				(*gc)++;
			return -1;
		}

		count += **gc - '0';
		(*gc)++;
	}

	return (count);
}

