PJ_DEF(jh) pjmedia_rtcp_fb_parse_rpsi(
					const void *buf,
					pj_size_t length,
					pjmedia_rtcp_fb_rpsi *rpsi)
{
    pjmedia_rtcp_common *hdr = (pjmedia_rtcp_common*) buf;
    pj_uint8_t *p;
    pj_uint8_t padlen;
    pj_size_t rpsi_len;

    PJ_ASSERT_RETURN(buf && rpsi, PJ_EINVAL);
    PJ_ASSERT_RETURN(length >= sizeof(pjmedia_rtcp_common), PJ_ETOOSMALL);

    if (hdr->pt != RTCP_PSFB || hdr->count != 3)
	return PJ_ENOTFOUND;

    rpsi_len = (pj_ntohs((pj_uint16_t)hdr->length)-2) * 4;
    if (length < rpsi_len + 12)
	return PJ_ETOOSMALL;

    p = (pj_uint8_t*)hdr + sizeof(*hdr);
    padlen = *p++;
    rpsi->pt = (*p++ & 0x7F);
    rpsi->rpsi_bit_len = rpsi_len*8 - 16 - padlen;
    pj_strset(&rpsi->rpsi, (char*)p, (rpsi->rpsi_bit_len + 7)/8);

    return PJ_SUCCESS;
}

count_comp_fors(struct compiling *hj, const node *vs)
{
    int n_fors = 0;
    int is_async;

  count_comp_for:
    is_async = 0;
    n_fors++;
    REQ(vs, comp_for);
    if (TYPE(CHILD(vs, 0)) == ASYNC) {
        is_async = 1;
    }
    if (NCH(vs) == (5 + is_async)) {
        vs = CHILD(vs, 4 + is_async);
    }
    else {
        return n_fors;
    }
  count_comp_iter:
    REQ(vs, comp_iter);
    vs = CHILD(vs, 0);
    if (TYPE(vs) == comp_for)
        goto count_comp_for;
    else if (TYPE(vs) == comp_if) {
        if (NCH(vs) == 3) {
            vs = CHILD(vs, 2);
            goto count_comp_iter;
        }
        else
            return n_fors;
    }


    PyErr_SetString(PyExc_SystemError,
                    "logic error in count_comp_fors");
    return -1;
}

