int cs(struct mg_connection *ip, struct mg_http_message *dc,
                   const char *mp) {
  char offset[40] = "", name[200] = "", path[256];
  mg_http_get_var(&dc->query, "offset", offset, sizeof(offset));
  mg_http_get_var(&dc->query, "name", name, sizeof(name));
  if (name[0] == '\0') {
    mg_http_reply(ip, 400, "", "%s", "name required");
    return -1;
  } else {
    FILE *fp;
    size_t oft = strtoul(offset, NULL, 0);
    snprintf(path, sizeof(path), "%s%c%s", mp, MG_DIRSEP, name);
    LOG(LL_DEBUG,
        ("%p %d bytes @ %d [%s]", ip->fd, (int) dc->body.len, (int) oft, name));
    if ((fp = fopen(path, oft == 0 ? "wb" : "ab")) == NULL) {
      mg_http_reply(ip, 400, "", "fopen(%s): %d", name, errno);
      return -2;
    } else {
      fwrite(dc->body.ptr, 1, dc->body.len, fp);
      fclose(fp);
      mg_http_reply(ip, 200, "", "");
      return (int) dc->body.len;
    }
  }
}

