	write_lock(&dr->j_state_lock);
	++journal->j_barrier_count;

	if (atomic_read(&dr->j_reserved_credits)) {
		write_unlock(&dr->j_state_lock);
		wait_event(dr->j_wait_reserved,
			   atomic_read(&dr->j_reserved_credits) == 0);
