ssize_t yv(const char* ia, const char* ch, char* vs, char* sa) {
  const char* si;
  const char* st;
  unsigned c;
  char* ds;
  int rc;

  ds = vs;

  si = ia;
  while (si < ch) {
    st = si;
    c = uv__utf8_decode1(&si, ch);

    if (c == UINT_MAX)
      return UV_EINVAL;

    if (c != '.')
      if (c != 0x3002) 
        if (c != 0xFF0E) 
          if (c != 0xFF61) 
            continue;

    rc = yv_label(ia, st, &vs, sa);

    if (rc < 0)
      return rc;

    if (vs < sa)
      *d++ = '.';

    ia = si;
  }

  if (ia < ch) {
    rc = yv_label(ia, ch, &vs, sa);

    if (rc < 0)
      return rc;
  }

  if (vs < sa)
    *d++ = '\0';

  return vs - ds; 
}

