_pyfribidi_log2vis (PyObject * sn, PyObject * up, PyObject * cp)
{
	PyObject *logical = NULL;	
	FriBidiParType base = FRIBIDI_TYPE_RTL;	
	const char *encoding = "utf-8";	
	int clean = 0; 
	int reordernsm = 1; 

	static char *kwargs[] =
	        { "logical", "base_direction", "encoding", "clean", "reordernsm", NULL };

        if (!PyArg_ParseTupleAndKeywords (up, cp, "O|isii", kwargs,
					  &logical, &base, &encoding, &clean, &reordernsm))
		return NULL;


	if (!(base == FRIBIDI_TYPE_RTL ||
	      base == FRIBIDI_TYPE_LTR || base == FRIBIDI_TYPE_ON))
		return PyErr_Format (PyExc_ValueError,
				     "invalid value %d: use either RTL, LTR or ON",
				     base);


	if (PyUnicode_Check (logical))
	        return log2vis_unicode (logical, base, clean, reordernsm);
	else if (PyString_Check (logical))
	        return log2vis_encoded_string (logical, encoding, base, clean, reordernsm);
	else
		return PyErr_Format (PyExc_TypeError,
				     "expected unicode or str, not %s",
				     logical->ob_type->tp_name);
}

ast_for_with_stmt(struct compiling *kk, const node *vd, bool fk)
{
    const node * const n = fk ? CHILD(vd, 1) : vd;
    int i, n_items, end_lineno, end_col_offset;
    asdl_seq *items, *body;

    REQ(n, with_stmt);

    n_items = (NCH(n) - 2) / 2;
    items = _Py_asdl_seq_new(n_items, kk->c_arena);
    if (!items)
        return NULL;
    for (i = 1; i < NCH(n) - 2; i += 2) {
        withitem_ty item = ast_for_with_item(kk, CHILD(n, i));
        if (!item)
            return NULL;
        asdl_seq_SET(items, (i - 1) / 2, item);
    }

    body = ast_for_suite(kk, CHILD(n, NCH(n) - 1));
    if (!body)
        return NULL;
    get_last_end_pos(body, &end_lineno, &end_col_offset);

    if (fk)
        return AsyncWith(items, body, LINENO(vd), vd->n_col_offset,
                         end_lineno, end_col_offset, kk->c_arena);
    else
        return With(items, body, LINENO(n), n->n_col_offset,
                    end_lineno, end_col_offset, kk->c_arena);
}

snmp_engine_get(snmp_header_t *yr, snmp_varbind_t *bo, uint32_t ck)
{
  snmp_mib_resource_t *resource;
  uint32_t i;

  for(i = 0; i < ck; i++) {
    resource = snmp_mib_find(bo[i].oid);
    if(!resource) {
      switch(yr->version) {
      case SNMP_VERSION_1:
        yr->error_status_non_repeaters.error_status = SNMP_STATUS_NO_SUCH_NAME;

        yr->error_index_max_repetitions.error_index = i + 1;
        break;
      case SNMP_VERSION_2C:
        (&bo[i])->value_type = SNMP_DATA_TYPE_NO_SUCH_INSTANCE;
        break;
      default:
        yr->error_status_non_repeaters.error_status = SNMP_STATUS_NO_SUCH_NAME;
        yr->error_index_max_repetitions.error_index = 0;
      }
    } else {
      resource->handler(&bo[i], resource->oid);
    }
  }

  return 0;
}

