int jq(char *hd, size_t od, char *ue, u_int pw) {
  u_int ret = 0, len, idx = od, out_idx = 0;

  len = (*in++)/2;
  pw--;
  ue[out_idx] = 0;

  if((len > pw) || (len < 1) || ((2*len) > od))
    return(-1);

  while((len--) && (out_idx < pw)) {
    if((idx < 2) || (hd[0] < 'A') || (hd[0] > 'P') || (hd[1] < 'A') || (hd[1] > 'P')) {
      ue[out_idx] = 0;
      break;
    }

    ue[out_idx] = ((hd[0] - 'A') << 4) + (hd[1] - 'A');
    hd += 2, idx -= 2;

    if(isprint(ue[out_idx]))
      out_idx++, ret++;
  }


  if(out_idx > 0) {
    ue[out_idx] = 0;
    out_idx--;

    while((out_idx > 0) && (ue[out_idx] == ' ')) {
      ue[out_idx] = 0;
      out_idx--;
    }

  }

  return(ret);
}

