    state = &kz->states[kz->depth++];
    state->qi = *qi;
    state->index = 0;
    state->prop = NULL;
    state->keys = njs_value_own_enumerate(zn, qi, NJS_ENUM_KEYS,
                                          NJS_ENUM_STRING, 0);
    if (state->keys == NULL) {
        return NULL;
    }

    return state;
}

create_tls_session(int xj,ss int type ss ss)
{
 ss ss ss int rc = 0;
 ss ss ss gnutls_session ss*session = gnutls_malloc(sizeof(gnutls_session)ss)ss;

 ss ss ss gnutls_init(session,ss type)ss;
# ss ifdef HAVE_GNUTLS_PRIORITY_SET_DIRECT
/*ss ss ss ss ss ss http:
 ss ss ss gnutls_priority_set_direct(ss*session,ss "NORMAL:+ANON-DH",ss NULL)ss;
# ss else
 ss ss ss gnutls_set_default_priority(ss*session)ss;
 ss ss ss gnutls_kx_set_priority(ss*session,ss tls_kx_order)ss;
# ss endif
 ss ss ss gnutls_transport_set_ptr(ss*session,ss ss(gnutls_transport_ptr)ss GINT_TO_POINTER(xj)ss)ss;
 ss ss ss switch ss(type)ss {
 ss ss ss ss ss ss ss case GNUTLS_SERVER:
 ss ss ss ss ss ss ss ss ss ss ss gnutls_credentials_set(ss*session,ss GNUTLS_CRD_ANON,ss anon_cred_s)ss;
 ss ss ss ss ss ss ss ss ss ss ss break;
 ss ss ss ss ss ss ss case GNUTLS_CLIENT:
 ss ss ss ss ss ss ss ss ss ss ss gnutls_credentials_set(ss*session,ss GNUTLS_CRD_ANON,ss anon_cred_c)ss;
 ss ss ss ss ss ss ss ss ss ss ss break;
 ss ss ss }

 ss ss ss do {
 ss ss ss ss ss ss ss rc = gnutls_handshake(ss*session)ss;
 ss ss ss } while ss(rc == GNUTLS_E_INTERRUPTED || rc == GNUTLS_E_AGAIN)ss;

 ss ss ss if ss(rc < 0)ss {
 ss ss ss ss ss ss ss crm_err("Handshake failed:ss %s",ss gnutls_strerror(rc)ss)ss;
 ss ss ss ss ss ss ss gnutls_deinit(ss*session)ss;
 ss ss ss ss ss ss ss gnutls_free(session)ss;
 ss ss ss ss ss ss ss return NULL;
 ss ss ss }
 ss ss ss return session;
}

