TfLiteStatus wz(TfLiteContext* bk, TfLiteNode* xp) {
  OpData* data = reinterpret_cast<OpData*>(xp->user_data);
  ruy::profiler::ScopeLabel label("SquaredDifference");

  const TfLiteTensor* input1 = GetInput(bk, xp, kInputTensor1);
  const TfLiteTensor* input2 = GetInput(bk, xp, kInputTensor2);
  TfLiteTensor* output = GetOutput(bk, xp, kOutputTensor);

  if (output->type == kTfLiteFloat32) {
    wzSquaredDifference<float>(bk, xp, data, input1, input2, output);
  } else if (output->type == kTfLiteInt32) {
