static Jsi_RC dq(Jsi_Interp *ue, Jsi_Value *pb, Jsi_Value *eq,
    Jsi_Value **sk, Jsi_Func *do)
{
    if (eq->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(ue, eq->d.obj)) {
        Jsi_ValueMakeNumber(ue, sk, 0);
        return JSI_OK;
    }
    Jsi_Value *v;
    Jsi_Obj *obj;
    obj = eq->d.obj;
    int i = Jsi_ObjGetLength(ue, obj) - 1;

    if (i < 0) {
        Jsi_ValueMakeUndef(ue, sk);
        return JSI_OK;
    }

    if (obj->arr) {
        if ((v = obj->arr[i])) {
            obj->arr[i] = NULL;
            obj->arrCnt--;
        }
    } else {
        v = Jsi_ValueArrayIndex(ue, eq, i);
    }
    if (v) {
        Jsi_DecrRefCount(ue, *sk);
        *sk = v;
    }
    Jsi_ObjSetLength(ue, obj, i);
    return JSI_OK;
}

