smb2_flush(smb_request_t *sv)
{
	smb_ofile_t *of = NULL;
	uint16_t StructSize;
	uint16_t reserved1;
	uint32_t reserved2;
	smb2fid_t smb2fid;
	uint32_t status;
	int rc = 0;

	rc = smb_mbc_decodef(
	    &sv->smb_data, "wwlqq",
	    &StructSize,		
	    &reserved1,			
	    &reserved2,			
	    &smb2fid.persistent,	
	    &smb2fid.temporal);		
	if (rc)
		return (SDRC_ERROR);
	if (StructSize != 24)
		return (SDRC_ERROR);

	status = smb2sr_lookup_fid(sv, &smb2fid);
	if (status) {
		smb2sr_put_error(sv, status);
		return (SDRC_SUCCESS);
	}
	of = sv->fid_ofile;

	if ((of->f_node->flags & NODE_FLAGS_WRITE_THROUGH) == 0)
		(void) smb_fsop_commit(sv, of->f_cr, of->f_node);

	(void) smb_mbc_encodef(
	    &sv->reply, "wwl",
	    4,	
	    0); 

	return (SDRC_SUCCESS);
}

void mt(bn_t ff, int ct) {
	while (1) {
		do {
			bn_rand(ff, RLC_POS, ct);
		} while (bn_bits(ff) != ct);

		bn_sub_dig(ff, ff, 1);
		bn_rsh(ff, ff, 1);
		if (bn_is_prime(ff)) {

			bn_lsh(ff, ff, 1);
			bn_add_dig(ff, ff, 1);
			if (bn_is_prime(ff)) {

				return;
			}
		}
	}
}

