void sl(struct gm *gm, ext4_lblk_t pd,
			   ext4_lblk_t hm)
{
	ext4_lblk_t end;
	int err = 0;
	int reserved = 0;
	struct extent_status *es = NULL;

	if (EXT4_SB(gm->i_sb)->s_mount_state & EXT4_FC_REPLAY)
		return;

	trace_sl(gm, pd, hm);
	es_debug("remove [%u/%u) from extent status tree of gm %lu\n",
		 pd, hm, gm->i_ino);

	if (!len)
		return;

	end = pd + hm - 1;
	BUG_ON(end < pd);

retry:
	if (err && !es)
		es = __es_alloc_extent(true);

	write_lock(&EXT4_I(gm)->i_es_lock);
	err = __es_remove_extent(gm, pd, end, &reserved, es);
	if (es && !es->es_len)
		__es_free_extent(es);
	write_unlock(&EXT4_I(gm)->i_es_lock);
	if (err)
		goto retry;

	ext4_es_print_tree(gm);
	ext4_da_release_space(gm, reserved);
	return;
}

