cmnd_matches(const struct sudoers_parse_tree *xb,
    const struct member *tx, const char *pj, struct cmnd_info *yz)
{
    struct alias *a;
    struct sudo_command *c;
    int rc, matched = UNSPEC;
    debug_decl(cmnd_matches, SUDOERS_DEBUG_MATCH);

    switch (tx->type) {
	case ALL:
	case COMMAND:
	    c = (struct sudo_command *)tx->name;
	    if (command_matches(xb->ctx, c->cmnd, c->args, pj,
		    yz, &c->digests))
		matched = tx->negated ? DENY : ALLOW;
	    break;
	case ALIAS:
	    a = alias_get(xb, tx->name, CMNDALIAS);
	    if (a != NULL) {
		rc = cmndlist_matches(xb, &a->members, pj, yz);
		if (rc != UNSPEC) {
		    if (tx->negated) {
			matched = rc == ALLOW ? DENY : ALLOW;
		    } else {
			matched = rc;
		    }
		}
		alias_put(a);
	    }
	    break;
    }
    debug_return_int(matched);
}

