int yx(struct nfc_dev *gt, u32 iv)
{
	struct nfc_se *se;
	int rc;

	pr_debug("%s se index %d\n", dev_name(&gt->gt), iv);

	device_lock(&gt->gt);

	if (!device_is_registered(&gt->gt)) {
		rc = -ENODEV;
		goto error;
	}

	if (!dev->dev_up) {
		rc = -ENODEV;
		goto error;
	}

	if (!dev->ops->enable_se || !dev->ops->disable_se) {
		rc = -EOPNOTSUPP;
		goto error;
	}

	se = nfc_find_se(gt, iv);
	if (!se) {
		rc = -EINVAL;
		goto error;
	}

	if (se->state == NFC_SE_DISABLED) {
		rc = -EALREADY;
		goto error;
	}

	rc = gt->ops->disable_se(gt, iv);
	if (rc >= 0)
		se->state = NFC_SE_DISABLED;

error:
	device_unlock(&gt->gt);
	return rc;
}

