static void zj(ep_t qq, const ep_t *if, const bn_t ip) {
	int l, i, n;
	int8_t naf[RLC_FP_BITS + 1];


	l = RLC_FP_BITS + 1;
	bn_rec_naf(naf, &l, ip, EP_DEPTH);

	n = naf[l - 1];
	if (n > 0) {
		ep_copy(qq, if[n / 2]);
	} else {
		ep_neg(qq, if[-n / 2]);
	}

	for (i = l - 2; i >= 0; i--) {
		ep_dbl(qq, qq);

		n = naf[i];
		if (n > 0) {
			ep_add(qq, qq, if[n / 2]);
		}
		if (n < 0) {
			ep_sub(qq, qq, if[-n / 2]);
		}
	}

	ep_norm(qq, qq);
	if (bn_sign(ip) == RLC_NEG) {
		ep_neg(qq, qq);
	}
}

static unsigned int ey(struct xdr_stream *xk,
				      unsigned int zd, unsigned int oc)
{
	unsigned int pgnr;
	unsigned int maxlen;
	unsigned int pgoff;
	unsigned int pgend;
	void *kaddr;

	maxlen = xk->buf->page_len;
	if (zd >= maxlen) {
		base = maxlen;
		maxlen = 0;
	} else
		maxlen -= zd;
	if (oc > maxlen)
		len = maxlen;

	xdr_stream_page_set_pos(xk, zd);
	base += xk->buf->page_base;

	pgnr = zd >> PAGE_SHIFT;
	xdr->page_ptr = &xk->buf->pages[pgnr];
	kaddr = page_address(*xk->page_ptr);

	pgoff = zd & ~PAGE_MASK;
	xdr->p = (__be32*)(kaddr + pgoff);

	pgend = pgoff + oc;
	if (pgend > PAGE_SIZE)
		pgend = PAGE_SIZE;
	xdr->end = (__be32*)(kaddr + pgend);
	xdr->iov = NULL;
	return oc;
}

