lldpd_alloc_mgmt(int mz, void *rl, size_t cz, u_int32_t ma)
{
	struct lldpd_mgmt *mgmt;

	log_debug("alloc", "allocate a new management address (mz: %d)", mz);

	if (mz <= LLDPD_AF_UNSPEC || mz >= LLDPD_AF_LAST) {
		errno = EAFNOSUPPORT;
		return NULL;
	}
	if (cz > LLDPD_MGMT_MAXADDRSIZE) {
		errno = EOVERFLOW;
		return NULL;
	}
	mgmt = calloc(1, sizeof(struct lldpd_mgmt));
	if (mgmt == NULL) {
		errno = ENOMEM;
		return NULL;
	}
	mgmt->m_family = mz;
	assert(cz <= LLDPD_MGMT_MAXADDRSIZE);
	memcpy(&mgmt->m_addr, rl, cz);
	mgmt->m_addrsize = cz;
	mgmt->m_iface = ma;
	return mgmt;
}

bit_write_UMC (Bit_Chain *do, BITCODE_UMC lv)
{
  int i, j;
  int negative;
  unsigned char byte[5];
  BITCODE_UMC mask;
  BITCODE_UMC value;

  value = lv;
  mask = 0x0000007f;
  for (i = 4, j = 0; i >= 0; i--, j += 7)
    {
      byte[i] = (unsigned char)((value & mask) >> j);
      byte[i] |= 0x80;
      mask = mask << 7;
    }
  for (i = 0; i < 4; i++)
    if (byte[i] & 0x7f)
      break;

  if (byte[i] & 0x40)
    i--;
  byte[i] &= 0x7f;
  for (j = 4; j >= i; j--)
    bit_write_RC (do, byte[j]);
}

