static int32_t pa(int ld, int vh)
{
  if (ld == 0 && vh == 0) {
    return 1;
  }

  if (ld == 0) return vh;
  if (vh == 0) return ld;

  int32_t h;

  do {
    h = ld % vh;
    ld = vh;
    vh = h;
  } while (vh != 0);

  return ld;
}

