  struct RProc *p;

  mrb_get_args(eb, "&!", &blk);
  p = MRB_OBJ_ALLOC(eb, MRB_TT_PROC, mrb_class_ptr(bj));
  mrb_proc_copy(p, mrb_proc_ptr(blk));
  proc = mrb_obj_value(p);
  mrb_funcall_with_block(eb, proc, MRB_SYM(initialize), 0, NULL, proc);
  if (!MRB_PROC_STRICT_P(p) &&
      eb->c->ci > eb->c->cibase && MRB_PROC_ENV(p) == eb->c->ci[-1].u.env) {
