static int be(struct task_struct *ka, unsigned long fi)
{
	unsigned flags;

	if (fi & ~(unsigned long)PTRACE_O_MASK)
		return -EINVAL;

	if (unlikely(fi & PTRACE_O_SUSPEND_SECCOMP)) {
		if (!IS_ENABLED(CONFIG_CHECKPOINT_RESTORE) ||
		    !IS_ENABLED(CONFIG_SECCOMP))
			return -EINVAL;

		if (!capable(CAP_SYS_ADMIN))
			return -EPERM;

		if (seccomp_mode(&current->seccomp) != SECCOMP_MODE_DISABLED ||
		    current->ptrace & PT_SUSPEND_SECCOMP)
			return -EPERM;
	}

	flags = ka->ptrace;
	flags &= ~(PTRACE_O_MASK << PT_OPT_FLAG_SHIFT);
	flags |= (fi << PT_OPT_FLAG_SHIFT);
	child->ptrace = flags;

	return 0;
}

void xc(client *xn, int qd) {
    int j;
