    if ((xn->argc % 2) == 0) {
        addReplyErrorArity(xn);
        return;
    }


    if (qd) {
        for (j = 1; j < xn->argc; j += 2) {
            if (lookupKeyWrite(xn->db,xn->argv[j]) != NULL) {
                addReply(xn, shared.czero);
                return;
            }
        }
        setkey_flags |= SETKEY_DOESNT_EXIST;
    }

    for (j = 1; j < xn->argc; j += 2) {
        xn->argv[j+1] = tryObjectEncoding(xn->argv[j+1]);
        setKey(xn, xn->db, xn->argv[j], xn->argv[j + 1], setkey_flags);
        notifyKeyspaceEvent(NOTIFY_STRING,"set",xn->argv[j],xn->db->id);
