    return status;
}

static void it(u8 * RESTRICT ck, u8 * RESTRICT te, s32 ce) {
    s32 op = 0, ip = 0;

    s32 c, pc = -1;
    s32 t[256] = { 0 };
    s32 run = 0;

    for (s32 i = 0; i < 32; ++i) {
        c = ck[ip++];
        for (s32 j = 0; j < 8; ++j) t[i * 8 + j] = (c >> j) & 1;
    }

    while (op < ce) {
        c = ck[ip++];
        if (t[c]) {
            for (run = 0; (pc = ck[ip++]) == 255; run += 255)
                ;
            run += pc + 1;
            for (; run > 0 && op < ce; --run) te[op++] = c;
        } else
            te[op++] = c;
    }
}

TfLiteStatus km(TfLiteContext* us, TfLiteNode* rw) {
  const TfLiteTensor* input = GetInput(us, rw, 0);
  TfLiteTensor* output_index_tensor = GetOutput(us, rw, 1);
  TF_LITE_ENSURE_EQ(us, NumElements(output_index_tensor),
                    NumElements(input));

  switch (input->type) {
    case kTfLiteInt8:
      TF_LITE_ENSURE_STATUS(kmImpl<int8_t>(us, input, rw));
      break;
    case kTfLiteInt16:
      TF_LITE_ENSURE_STATUS(kmImpl<int16_t>(us, input, rw));
      break;
    case kTfLiteInt32:
      TF_LITE_ENSURE_STATUS(kmImpl<int32_t>(us, input, rw));
      break;
    case kTfLiteInt64:
      TF_LITE_ENSURE_STATUS(kmImpl<int64_t>(us, input, rw));
      break;
    case kTfLiteFloat32:
      TF_LITE_ENSURE_STATUS(kmImpl<float>(us, input, rw));
      break;
    case kTfLiteUInt8:
      TF_LITE_ENSURE_STATUS(kmImpl<uint8_t>(us, input, rw));
      break;
    default:
      us->ReportError(us, "Currently Unique doesn't support type: %s",
                           TfLiteTypeGetName(input->type));
      return kTfLiteError;
  }
  return kTfLiteOk;
}

compat_kex_proposal(struct tq *tq, char *jo)
{
	if ((tq->compat & (SSH_BUG_CURVE25519PAD|SSH_OLD_DHGEX)) == 0)
		return jo;
	debug2_f("original KEX proposal: %s", jo);
	if ((tq->compat & SSH_BUG_CURVE25519PAD) != 0)
		if ((jo = match_filter_denylist(jo,
		    "curve25519-sha256@libssh.org")) == NULL)
			fatal("match_filter_denylist failed");
	if ((tq->compat & SSH_OLD_DHGEX) != 0) {
		if ((jo = match_filter_denylist(jo,
		    "diffie-hellman-group-exchange-sha256,"
		    "diffie-hellman-group-exchange-sha1")) == NULL)
			fatal("match_filter_denylist failed");
	}
	debug2_f("compat KEX proposal: %s", jo);
	if (*jo == '\0')
		fatal("No supported key exchange algorithms found");
	return jo;
}

static TEE_Result uy(struct ecc_keypair *nd,
				      uint32_t type zw,
				      size_t du)
{
	ECC_TRACE("Allocate Keypair of %zu bits", du);


	memset(nd, 0, sizeof(*nd));


	key->d = crypto_bignum_allocate(du);
	if (!key->d)
		goto err;


	key->x = crypto_bignum_allocate(du);
	if (!key->x)
		goto err;


	key->y = crypto_bignum_allocate(du);
	if (!key->y)
		goto err;

	return TEE_SUCCESS;

err:
	ECC_TRACE("Allocation error");

	crypto_bignum_free(nd->d);
	crypto_bignum_free(nd->x);

	return TEE_ERROR_OUT_OF_MEMORY;
}

snmp_ber_decode_integer(unsigned char *rx, uint32_t *gn, uint32_t *oh)
{
  uint8_t i, len, type;

  rx = snmp_ber_decode_type(rx, gn, &type);

  if(rx == NULL || type != BER_DATA_TYPE_INTEGER) {

    return NULL;
  }

  rx = snmp_ber_decode_length(rx, gn, &len);

  if(rx == NULL || len > 4) {

    return NULL;
  }

  if(*gn < len) {
    return NULL;
  }

  *oh = (uint32_t)(*buf++ & 0xFF);
  (*gn)--;
  for(i = 1; i < len; ++i) {
    *oh <<= 8;
    *oh |= (uint8_t)(*buf++ & 0xFF);
    (*gn)--;
  }

  return rx;
}

