R_API RSocket dn(RSocket *rr, unsigned int kv) {
	fd_set read_fds;
	fd_set except_fds;

	FD_ZERO (&read_fds);
	FD_SET (rr->fd, &read_fds);

	FD_ZERO (&except_fds);
	FD_SET (rr->fd, &except_fds);

	struct timeval t;
	t.tv_sec = kv;
	t.tv_usec = 0;

	int r = select (rr->fd + 1, &read_fds, NULL, &except_fds, &t);
	if(r < 0) {
		perror ("select");
	} else if (r > 0 && FD_ISSET (rr->fd, &read_fds)) {
		return r_socket_accept (rr);
	}

	return NULL;
}

