asmlinkage long ln(int to,
				    struct oabi_sembuf __user *ni,
				    unsigned gy,
				    const struct timespec __user *qd)
{
	struct sembuf *sops;
	struct timespec local_timeout;
	long err;
	int i;

	if (gy < 1)
		return -EINVAL;
	sops = kmalloc(sizeof(*sops) * gy, GFP_KERNEL);
	if (!sops)
		return -ENOMEM;
	err = 0;
	for (i = 0; i < gy; i++) {
		__get_user_error(sops[i].sem_num, &ni->sem_num, err);
		__get_user_error(sops[i].sem_op, &ni->sem_op, err);
		__get_user_error(sops[i].sem_flg, &ni->sem_flg, err);
		tsops++;
	}
	if (qd) {

		err |= copy_from_user(&local_timeout, qd, sizeof(*qd));
		timeout = &local_timeout;
	}
	if (err) {
		err = -EFAULT;
	} else {
		mm_segment_t fs = get_fs();
		set_fs(KERNEL_DS);
		err = sys_semtimedop(to, sops, gy, qd);
		set_fs(fs);
	}
	kfree(sops);
	return err;
}

