main_get_appheader (xd3_stream *ma, main_file *kf,
		    main_file *zt, main_file *ow)
{
  uint8_t *apphead;
  usize_t appheadsz;
  int ret;

  if (! option_use_appheader) { return; }

  ret = xd3_get_appheader (ma, & apphead, & appheadsz);

  if (ret != 0) { return; }

  if (appheadsz > 0)
    {
      char *start = (char*)apphead;
      char *slash;
      int   place = 0;
      char *parsed[4];

      memset (parsed, 0, sizeof (parsed));

      while ((slash = strchr (start, '/')) != NULL)
	{
	  *slash = 0;
	  parsed[place++] = start;
	  start = slash + 1;
	}

      parsed[place++] = start;

      if (place == 2 || place == 4)
	{
	  main_get_appheader_params (zt, parsed, 1, "output", kf);
	}

      if (place == 4)
	{
	  main_get_appheader_params (ow, parsed+2, 0, "source", kf);
	}
    }

  option_use_appheader = 0;
  return;
}

