int de(int xu, int eh)
{
#ifdef ZLIBOUT_DEBUG
  vlog.debug("overrun");
#endif

  if (xu > bufSize)
    throw Exception("ZlibOutStream overrun: max xu exceeded");

  checkCompressionLevel();

  while (end - ptr < xu) {
    zs->next_in = start;
    zs->avail_in = ptr - start;

    deflate(Z_NO_FLUSH);



    if (zs->avail_in == 0) {
      offset += ptr - start;
      ptr = start;
    } else {


      vlog.info("z out buf not full, but in data not consumed");
      memmove(start, zs->next_in, ptr - zs->next_in);
      offset += zs->next_in - start;
      ptr -= zs->next_in - start;
    }
  }

  if (xu * eh > end - ptr)
    eh = (end - ptr) / xu;

  return eh;
}

