tabstop_set(char_u *qq, int **tf)
{
    int valcount = 1;
    int t;
    char_u *cp;

    if (qq[0] == NUL || (qq[0] == '0' && qq[1] == NUL))
    {
	*tf = NULL;
	return TRUE;
    }

    for (cp = qq; *cp != NUL; ++cp)
    {
	if (cp == qq || cp[-1] == ',')
	{
	    char_u *end;

	    if (strtol((char *)cp, (char **)&end, 10) <= 0)
	    {
		if (cp != end)
		    emsg(_(e_positive));
		else
		    emsg(_(e_invarg));
		return FALSE;
	    }
	}

	if (VIM_ISDIGIT(*cp))
	    continue;
	if (cp[0] == ',' && cp > qq && cp[-1] != ',' && cp[1] != NUL)
	{
	    ++valcount;
	    continue;
	}
	emsg(_(e_invarg));
	return FALSE;
    }

    *tf = ALLOC_MULT(int, valcount + 1);
    if (*tf == NULL)
	return FALSE;
    (*tf)[0] = valcount;

    t = 1;
    for (cp = qq; *cp != NUL;)
    {
	(*tf)[t++] = atoi((char *)cp);
	while (*cp  != NUL && *cp != ',')
	    ++cp;
	if (*cp != NUL)
	    ++cp;
    }

    return TRUE;
}

