void xq(fp12_t jz, const fp12_t dq, dig_t yr) {
	bn_t _b;
	fp12_t t, v;
	int8_t u, naf[RLC_DIG + 1];
	int l;

	if (yr == 0) {
		fp12_set_dig(jz, 1);
		return;
	}

	bn_null(_b);
	fp12_null(t);
	fp12_null(v);

	RLC_TRY {
		bn_new(_b);
		fp12_new(t);
		fp12_new(v);

		fp12_copy(t, dq);

		if (fp12_test_cyc(dq)) {
			fp12_inv_cyc(v, dq);
			bn_set_dig(_b, yr);

			l = RLC_DIG + 1;
			bn_rec_naf(naf, &l, _b, 2);

			for (int i = bn_bits(_b) - 2; i >= 0; i--) {
				fp12_sqr_cyc(t, t);

				u = naf[i];
				if (u > 0) {
					fp12_mul(t, t, dq);
				} else if (u < 0) {
					fp12_mul(t, t, v);
				}
			}
		} else {
			for (int i = util_bits_dig(yr) - 2; i >= 0; i--) {
				fp12_sqr(t, t);
				if (yr & ((dig_t)1 << i)) {
					fp12_mul(t, t, dq);
				}
			}
		}

		fp12_copy(jz, t);
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(_b);
		fp12_free(t);
		fp12_free(v);
	}
}

