TfLiteStatus lh(TfLiteContext* lh, TfLiteNode* mc) {
  TF_LITE_ENSURE_EQ(lh, NumInputs(mc), 1);
  TF_LITE_ENSURE_EQ(lh, NumOutputs(mc), 1);
  const TfLiteTensor* input = GetInput(lh, mc, kInputTensor);
  TfLiteIntArray* input_dims = input->dims;
  int input_dims_size = input_dims->size;
  TF_LITE_ENSURE(lh, input_dims_size >= 1);

  TfLiteTensor* output = GetOutput(lh, mc, kOutputTensor);

  TfLiteIntArray* output_shape = TfLiteIntArrayCreate(input_dims_size + 1);
  for (int i = 0; i < input_dims_size; i++) {
    output_shape->data[i] = input_dims->data[i];
  }


  output_shape->data[input_dims_size] = input_dims->data[input_dims_size - 1];
  output->type = input->type;
  TF_LITE_ENSURE_OK(lh,
                    lh->ResizeTensor(lh, output, output_shape));

  return kTfLiteOk;
}

