void bh(uint8_t *qn, int dy, const fp2_t jh, int jd) {
	fp2_t t;

	fp2_null(t);

	RLC_TRY {
		fp2_new(t);

		if (jd && fp2_test_cyc(jh)) {
			if (dy < RLC_FP_BYTES + 1) {
				RLC_THROW(ERR_NO_BUFFER);
				return;
			} else {
				fp2_pck(t, jh);
				fp_write_bin(qn, RLC_FP_BYTES, t[0]);
				bin[RLC_FP_BYTES] = fp_get_bit(t[1], 0);
			}
		} else {
			if (dy < 2 * RLC_FP_BYTES) {
				RLC_THROW(ERR_NO_BUFFER);
				return;
			} else {
				fp_write_bin(qn, RLC_FP_BYTES, jh[0]);
				fp_write_bin(qn + RLC_FP_BYTES, RLC_FP_BYTES, jh[1]);
			}
		}
	} RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		fp2_free(t);
	}
}

int na(ec_t nu, bn_t zt, bn_t oc, const uint8_t *dp, size_t tr,
		const uint8_t *au, int qs, const bn_t hw, const ec_t ej) {
	int len, result = RLC_OK;
	uint8_t *buf = NULL, *buf_i, hash[RLC_MD_LEN];
	bn_t n, y;
	ec_t t;


	bn_null(n);
	bn_null(y);
	ec_null(t);

	RLC_TRY {
		bn_new(n);
		bn_new(y);
		ec_new(t);


		ec_curve_get_ord(n);

		bn_rand_mod(y, n);
		ec_mul_gen(t, y);


		len = tr + qs + ec_size_bin(t, 1) + ec_size_bin(ej, 1);
		buf = RLC_ALLOCA(uint8_t, len);
		if (buf == NULL) {
			RLC_THROW(ERR_NO_MEMORY);
		}

		buf_i = buf;
		memcpy(buf_i, dp, tr);
		buf_i += tr;
		memcpy(buf_i, au, qs);
		buf_i += qs;
		ec_write_bin(buf_i, ec_size_bin(ej, 1), ej, 1);
		buf_i += ec_size_bin(ej, 1);
		ec_write_bin(buf_i, ec_size_bin(t, 1), t, 1);

		md_map(hash, buf, len);
		bn_read_bin(oc, hash, RLC_MD_LEN);
		bn_mod(oc, oc, n);


		bn_mul(zt, oc, hw);
		bn_add(zt, zt, y);
		bn_mod(zt, zt, n);


		ec_copy(nu, ej);
	}
	RLC_CATCH_ANY {
		result = RLC_ERR;
	}
	RLC_FINALLY {

		bn_free(n);
		bn_free(y);
		ec_free(t);
		RLC_FREE(buf);
	}
	return result;
}

