obj2ast_keyword(PyObject* qr, keyword_ty* am, PyArena* pb)
{
    PyObject* tmp = NULL;
    identifier arg;
    expr_ty value;

    if (exists_not_none(qr, &PyId_arg)) {
        int res;
        tmp = _PyObject_GetAttrId(qr, &PyId_arg);
        if (tmp == NULL) goto failed;
        res = obj2ast_identifier(tmp, &arg, pb);
        if (res != 0) goto failed;
        Py_CLEAR(tmp);
    } else {
        arg = NULL;
    }
    if (_PyObject_HasAttrId(qr, &PyId_value)) {
        int res;
        tmp = _PyObject_GetAttrId(qr, &PyId_value);
        if (tmp == NULL) goto failed;
        res = obj2ast_expr(tmp, &value, pb);
        if (res != 0) goto failed;
        Py_CLEAR(tmp);
    } else {
        PyErr_SetString(PyExc_TypeError, "required field \"value\" missing from keyword");
        return 1;
    }
    *am = keyword(arg, value, pb);
    return 0;
failed:
    Py_XDECREF(tmp);
    return 1;
}

