_PyMemoTable_Lookup(PyMemoTable *ug, PyObject *jl)
{
    size_t i;
    size_t perturb;
    size_t mask = (size_t)ug->mt_mask;
    PyMemoEntry *table = ug->mt_table;
    PyMemoEntry *entry;
    Py_hash_t hash = (Py_hash_t)jl >> 3;

    i = hash & mask;
    entry = &table[i];
    if (entry->me_key == NULL || entry->me_key == jl)
        return entry;

    for (perturb = hash; ; perturb >>= PERTURB_SHIFT) {
        i = (i << 2) + i + perturb + 1;
        entry = &table[i & mask];
        if (entry->me_key == NULL || entry->me_key == jl)
            return entry;
    }
    Py_UNREACHABLE();
}

