static Jsi_RC kd(Jsi_Interp *xn, Jsi_Obj* cn, Jsi_Value *tf, int rj) {

    int i, n = 0, len = Jsi_ObjGetLength(xn, tf->d.obj);
    if (len <= 0) return JSI_OK;
    Jsi_RC rc = JSI_OK;
    int clen = Jsi_ObjGetLength(xn, cn);
    for (i = 0; i < len && rc == JSI_OK; i++) {
        Jsi_Value *t = Jsi_ValueArrayIndex(xn, tf, i);
        if (t && rj>0 && Jsi_ValueIsArray(xn, t))
            rc = kd(xn, cn, t , rj-1);
        else if (!Jsi_ValueIsUndef(xn, t))
            Jsi_ObjArrayAdd(xn, cn, t);
        if ((++n + clen)>xn->maxArrayList)
            return Jsi_LogError("array size exceeded");
    }
    return rc;
}

