TfLiteStatus cc(TfLiteContext* al, TfLiteNode* rs,
                                 const TfLiteTensor* lo,
                                 const TfLiteTensor* zr, int et) {
  int axis_value = GetTensorData<int>(lo)[0];
  if (axis_value < 0) {
    axis_value += NumDimensions(zr);
  }

  TF_LITE_ENSURE(al, axis_value >= 0);
  TF_LITE_ENSURE(al, axis_value < NumDimensions(zr));

  const int input_size = SizeOfDimension(zr, axis_value);
  TF_LITE_ENSURE_MSG(al, input_size % et == 0,
                     "Not an even split");
  const int slice_size = input_size / et;

  for (int i = 0; i < NumOutputs(rs); ++i) {
    TfLiteIntArray* output_dims = TfLiteIntArrayCopy(zr->dims);
    output_dims->data[axis_value] = slice_size;
    TfLiteTensor* output = GetOutput(al, rs, i);
    TF_LITE_ENSURE_STATUS(al->ResizeTensor(al, output, output_dims));
  }

  return kTfLiteOk;
}

