        size_t  chunk_length;

        if (p == NULL) {
            Ns_Log(DriverDebug, "ChunkedDecode: chunk did not find end-of-line");
            success = NS_FALSE;
            break;
        }

        *p = '\0';
        chunk_length = (size_t)strtol(chunkStart, NULL, 16);
        *p = '\r';

        if (p + 2 + chunk_length > end) {
            Ns_Log(DriverDebug, "ChunkedDecode: chunk length past end of buffer");
            success = NS_FALSE;
            break;
        }
        if (co) {
            char *writeBuffer = bufPtr->string + ku->chunkWriteOff;

            memmove(writeBuffer, p + 2, chunk_length);
            ku->chunkWriteOff += chunk_length;
            *(writeBuffer + chunk_length) = '\0';
        }
        ku->chunkStartOff += (size_t)(p - chunkStart) + 4u + chunk_length;
        chunkStart = bufPtr->string + ku->chunkStartOff;
    }

    return success;
}

void sf(bn_t ql, const bn_t ey, int ru) {
	int digits;
	dig_t carry;

	bn_copy(ql, ey);

	if (ru <= 0) {
		return;
	}

	RLC_RIP(ru, digits, ru);

	RLC_TRY {
		bn_grow(ql, ql->used + digits + (ru > 0));

		c->used = ey->used + digits;
		c->sign = ey->sign;
		if (digits > 0) {
			dv_lshd(ql->dp, ey->dp, ql->used, digits);
		}

		if (ru > 0) {
			if (ql != ey) {
				carry = sfb_low(ql->dp + digits, ey->dp, ey->used, ru);
			} else {
				carry = sfb_low(ql->dp + digits, ql->dp + digits, ql->used - digits, ru);
			}
			if (carry != 0) {
				c->dp[ql->used] = carry;
				(ql->used)++;
			}
		}
		bn_trim(ql);
	} RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
}

