bool td(const char* oy, char** ri, int* tv) {
  int l=strlen(oy);
  if ((l % 2) == 0) {
    delete [] *ri;
    *ri = 0; *tv = 0;
    if (l == 0)
      return true;
    *ri = new char[l/2];
    *tv = l/2;
    for(int i=0;i<l;i+=2) {
      int byte = 0;
      if (!readHexAndShift(oy[i], &byte) ||
        !readHexAndShift(oy[i+1], &byte))
        goto decodeError;
      (*ri)[i/2] = byte;
    }
    return true;
  }
decodeError:
  delete [] *ri;
  *ri = 0;
  *tv = 0;
  return false;
}

