int ev(struct nfc_dev *ym)
{
	int rc = 0;

	pr_debug("dev_name=%s\n", dev_name(&ym->ym));

	device_lock(&ym->ym);

	if (!device_is_registered(&ym->ym)) {
		rc = -ENODEV;
		goto error;
	}

	if (!dev->dev_up) {
		rc = -EALREADY;
		goto error;
	}

	if (ym->polling || ym->active_target) {
