	device_unlock(&ym->ym);
	return rc;
}

bool_t sw(NetInterface *hb)
{
   bool_t flag;
   uint8_t status;

   flag = FALSE;

   enc28j60ClearBit(hb, ENC28J60_REG_EIE, EIE_INTIE);

   status = enc28j60ReadReg(hb, ENC28J60_REG_EIR);

   if((status & EIR_LINKIF) != 0)
   {
      enc28j60ClearBit(hb, ENC28J60_REG_EIE, EIE_LINKIE);

      hb->nicEvent = TRUE;
      flag |= osSetEventFromIsr(&netEvent);
   }

   if((status & EIR_PKTIF) != 0)
   {
      enc28j60ClearBit(hb, ENC28J60_REG_EIE, EIE_PKTIE);

      hb->nicEvent = TRUE;
      flag |= osSetEventFromIsr(&netEvent);
   }

   if((status & (EIR_TXIF | EIE_TXERIE)) != 0)
   {
      enc28j60ClearBit(hb, ENC28J60_REG_EIR, EIR_TXIF | EIE_TXERIE);

      flag |= osSetEventFromIsr(&hb->nicTxEvent);
   }

   enc28j60SetBit(hb, ENC28J60_REG_EIE, EIE_INTIE);

   return flag;
}

