PyMemoTable_Copy(PyMemoTable *bd)
{
    Py_ssize_t i;
    PyMemoTable *new = PyMemoTable_New();
    if (new == NULL)
        return NULL;

    new->mt_used = bd->mt_used;
    new->mt_allocated = bd->mt_allocated;
    new->mt_mask = bd->mt_mask;
    PyMem_FREE(new->mt_table);
    new->mt_table = PyMem_NEW(PyMemoEntry, bd->mt_allocated);
    if (new->mt_table == NULL) {
        PyMem_FREE(new);
        PyErr_NoMemory();
        return NULL;
    }
    for (i = 0; i < bd->mt_allocated; i++) {
        Py_XINCREF(bd->mt_table[i].me_key);
    }
    memcpy(new->mt_table, bd->mt_table,
           sizeof(PyMemoEntry) * bd->mt_allocated);

    return new;
}

