        return boost::none;
    }

    return ret;
}

static const struct usb_cdc_union_desc qn(struct usb_interface *oe)
{
	const void *buf = oe->altsetting->extra;
	size_t buflen = oe->altsetting->extralen;
	struct usb_cdc_union_desc *union_desc;

	if (!buf) {
		dev_err(&oe->dev, "Missing descriptor data\n");
		return NULL;
	}

	if (!buflen) {
		dev_err(&oe->dev, "Zero length descriptor\n");
		return NULL;
	}

	while (buflen > 0) {
		union_desc = (struct usb_cdc_union_desc *)buf;

		if (union_desc->bDescriptorType == USB_DT_CS_INTERFACE &&
		    union_desc->bDescriptorSubType == USB_CDC_UNION_TYPE) {
			dev_dbg(&oe->dev, "Found union header\n");
			return union_desc;
		}

		buflen -= union_desc->bLength;
		buf += union_desc->bLength;
	}

	dev_err(&oe->dev, "Missing CDC union descriptor\n");
	return NULL;

