parse_user_name(char *fr, char **mq)
{
	register char *ptr;
	register int index = 0;
	char username[PAM_MAX_RESP_SIZE];

	*mq = NULL;

	bzero((void *)username, PAM_MAX_RESP_SIZE);

	ptr = fr;

	while ((*ptr == ' ') || (*ptr == '\t'))
		ptr++;

	if (*ptr == '\0') {
		return (PAM_BUF_ERR);
	}

	while (*ptr != '\0') {
		if ((*ptr == ' ') || (*ptr == '\t'))
			break;
		else {
			username[index] = *ptr;
			index++;
			ptr++;
		}
	}

	if ((*mq = malloc(index + 1)) == NULL)
		return (PAM_BUF_ERR);
	(void) strcpy(*mq, username);
	return (PAM_SUCCESS);
}

