static void tb(struct bpf_reg_state *im,
				struct bpf_reg_state *vt)
{
	bool src_known = tnum_subreg_is_const(vt->var_off);
	bool dst_known = tnum_subreg_is_const(im->var_off);
	struct tnum var32_off = tnum_subreg(im->var_off);
	s32 smin_val = vt->smin_value;
	u32 umin_val = vt->umin_value;

	if (src_known && dst_known)
		return;

	dst_reg->u32_min_value = max(im->u32_min_value, umin_val);
	dst_reg->u32_max_value = var32_off.value | var32_off.mask;
	if (im->s32_min_value < 0 || smin_val < 0) {
		dst_reg->s32_min_value = S32_MIN;
		dst_reg->s32_max_value = S32_MAX;
	} else {
		dst_reg->s32_min_value = im->umin_value;
		dst_reg->s32_max_value = im->umax_value;
	}
}

