static Jsi_RC ru(Jsi_Interp *nj, Jsi_Value *eg, Jsi_Value *kh,
    Jsi_Value **ms, Jsi_Func *hp)
{
    Jsi_Obj *obj;

    if (kh->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(nj, kh->d.obj)) {
        Jsi_ValueMakeNumber(nj, ms, 0);
        return JSI_OK;
    }
    obj = kh->d.obj;

    int argc = Jsi_ValueGetLength(nj, eg);
    int curlen = Jsi_ObjGetLength(nj, obj);
    if (curlen < 0) {
        Jsi_ObjSetLength(nj, obj, 0);
    }

    int i;
    for (i = 0; i < argc; ++i) {
        Jsi_Value *ov = Jsi_ValueArrayIndex(nj, eg, i);
        if (!ov) { Jsi_LogBug("Arguments Error"); ov = Jsi_ValueNew(nj); }
        Jsi_ValueInsertArray(nj, kh, curlen + i, ov, 0);
    }

    Jsi_ValueMakeNumber(nj, ms, Jsi_ObjGetLength(nj, obj));
    return JSI_OK;
}

