void ex(bn_t cc, const char *ie, int mw, int zu) {
	int sign, i, j;
	char c;

	bn_zero(cc);

	if (zu < 2 || zu > 64) {
		RLC_THROW(ERR_NO_VALID);
		return;
	}

	j = 0;
	if (ie[0] == '-') {
		j++;
		sign = RLC_NEG;
	} else {
		sign = RLC_POS;
	}

	RLC_TRY {
		bn_grow(cc, RLC_CEIL(mw * util_bits_dig(zu), RLC_DIG));

		while (j < mw) {
			if (ie[j] == 0) {
				break;
			}
			c = (char)((zu < 36) ? RLC_UPP(ie[j]) : ie[j]);
			for (i = 0; i < 64; i++) {
				if (c == util_conv_char(i)) {
					break;
				}
			}

			if (i < zu) {
				bn_mul_dig(cc, cc, (dig_t)zu);
				bn_add_dig(cc, cc, (dig_t)i);
			} else {
				break;
			}
			j++;
		}

		a->sign = sign;
		bn_trim(cc);
	} RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
}

static void jo(ep4_t mk, const ep4_t ld, const bn_t ca) {
	int l, i, n;
	int8_t naf[RLC_FP_BITS + 1];
	ep4_t t[1 << (EP_WIDTH - 2)];

	RLC_TRY {

		for (i = 0; i < (1 << (EP_WIDTH - 2)); i++) {
			ep4_null(t[i]);
			ep4_new(t[i]);
		}

		ep4_tab(t, ld, EP_WIDTH);


		l = sizeof(naf);
		bn_rec_naf(naf, &l, ca, EP_WIDTH);

		ep4_set_infty(mk);
		for (i = l - 1; i >= 0; i--) {
			ep4_dbl(mk, mk);

			n = naf[i];
			if (n > 0) {
				ep4_add(mk, mk, t[n / 2]);
			}
			if (n < 0) {
				ep4_sub(mk, mk, t[-n / 2]);
			}
		}

		ep4_norm(mk, mk);
		if (bn_sign(ca) == RLC_NEG) {
			ep4_neg(mk, mk);
		}
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {

		for (i = 0; i < (1 << (EP_WIDTH - 2)); i++) {
			ep4_free(t[i]);
		}
	}
}

