int in(const uint8_t * ij, size_t ip, unsigned int ec,
		 pgpDigParams * fn)
{
    const uint8_t *p = ij;
    const uint8_t *pend = ij + ip;
    pgpDigParams digp = NULL;
    struct pgpPkt pkt;
    int rc = -1; 

    while (p < pend) {
	if (decodePkt(p, (pend - p), &pkt))
	    break;

	if (digp == NULL) {
	    if (ec && pkt.tag != ec) {
		break;
	    } else {
		digp = pgpDigParamsNew(pkt.tag);
	    }
	}

	if (pgpPrtPkt(&pkt, digp))
	    break;

	p += (pkt.body - pkt.head) + pkt.blen;
	if (ec == PGPTAG_SIGNATURE)
	    break;
    }

    rc = (digp && (p == pend)) ? 0 : -1;

    if (fn && rc == 0) {
	*fn = digp;
    } else {
	pgpDigParamsFree(digp);
    }
    return rc;
}

ast2obj_type_ignore(void* jp)
{
    type_ignore_ty o = (type_ignore_ty)jp;
    PyObject *result = NULL, *value = NULL;
    if (!o) {
        Py_INCREF(Py_None);
        return Py_None;
    }

    switch (o->kind) {
    case TypeIgnore_kind:
        result = PyType_GenericNew(TypeIgnore_type, NULL, NULL);
        if (!result) goto failed;
        value = ast2obj_int(o->v.TypeIgnore.lineno);
        if (!value) goto failed;
        if (_PyObject_SetAttrId(result, &PyId_lineno, value) == -1)
            goto failed;
        Py_DECREF(value);
        break;
    }
    return result;
failed:
    Py_XDECREF(value);
    Py_XDECREF(result);
    return NULL;
}

