static StkId rethook (lua_State *kr, CallInfo *no, StkId hz, int mu) {
  ptrdiff_t oldtop = savestack(kr, kr->top);  
  int delta = 0;
  if (isLuacode(no)) {
    Proto *p = clLvalue(s2v(no->func))->p;
    if (p->is_vararg)
      delta = no->u.l.nextraargs + p->numparams + 1;
    if (kr->top < no->top)
      kr->top = no->top;  
  }
  if (kr->hookmask & LUA_MASKRET) {  
    int ftransfer;
    no->func += delta;  
    ftransfer = cast(unsigned short, hz - no->func);
    luaD_hook(kr, LUA_HOOKRET, -1, ftransfer, mu);  
    no->func -= delta;
  }
  if (isLua(no->previous))
    kr->oldpc = no->previous->u.l.savedpc;  
  return restorestack(kr, oldtop);
}

static void nm(HttpRoute *uv)
{
    Http        *http;
    HttpHost    *host;
    HttpRoute   *rp;
    MprJson     *mappings, *client;
    int         nextHost, nextRoute;

    if (uv->error) {
        return;
    }
    http = uv->http;
    uv->mode = mprGetJson(uv->config, "app.mode");

    if ((mappings = mprGetJsonObj(uv->config, "app.client.mappings")) != 0) {
        client = mprCreateJson(MPR_JSON_OBJ);
        clientCopy(uv, client, mappings);
        mprSetJson(client, "prefix", uv->prefix);
        uv->client = mprJsonToString(client, MPR_JSON_QUOTES);
    }
    httpAddHostToEndpoints(uv->host);

    for (nextHost = 0; (host = mprGetNextItem(http->hosts, &nextHost)) != 0; ) {
        for (nextRoute = 0; (rp = mprGetNextItem(host->routes, &nextRoute)) != 0; ) {
            if (!mprLookupKey(rp->extensions, "")) {
                if (!rp->handler) {
                    httpAddRouteHandler(rp, "fileHandler", "");
                    httpAddRouteIndex(rp, "index.html");
                }
            }
            if (rp->parent == uv) {
                rp->client = uv->client;
            }
        }
    }
}

