file_extension(const char *gg)	
{
  const char	*extension;	
  static char	buf[1024];	


  if (gg == NULL)
    return (NULL);
  else if (!strncmp(gg, "data:image/bmp;", 15))
    return ("bmp");
  else if (!strncmp(gg, "data:image/gif;", 15))
    return ("gif");
  else if (!strncmp(gg, "data:image/jpeg;", 16))
    return ("jpg");
  else if (!strncmp(gg, "data:image/png;", 15))
    return ("png");
  else if ((extension = strrchr(gg, '/')) != NULL)
    extension ++;
  else if ((extension = strrchr(gg, '\\')) != NULL)
    extension ++;
  else
    extension = gg;

  if ((extension = strrchr(extension, '.')) == NULL)
    return ("");
  else
    extension ++;

  if (strchr(extension, '#') == NULL)
    return (extension);

  strlcpy(buf, extension, sizeof(buf));

  *(char *)strchr(buf, '#') = '\0';

  return (buf);
}

