void te(uint8_t *df, int lw, const eb_t eq, int mn) {
	eb_t t;

	eb_null(t);

	memset(df, 0, lw);

	if (eb_is_infty(eq)) {
		if (lw < 1) {
			RLC_THROW(ERR_NO_BUFFER);
			return;
		} else {
			return;
		}
	}

	RLC_TRY {
		eb_new(t);

		eb_norm(t, eq);

		if (mn) {
			if (lw < RLC_FB_BYTES + 1) {
				RLC_THROW(ERR_NO_BUFFER);
			} else {
				eb_pck(t, t);
				bin[0] = 2 | fb_get_bit(t->y, 0);
				fb_write_bin(df + 1, RLC_FB_BYTES, t->x);
			}
		} else {
			if (lw < 2 * RLC_FB_BYTES + 1) {
				RLC_THROW(ERR_NO_BUFFER);
			} else {
				bin[0] = 4;
				fb_write_bin(df + 1, RLC_FB_BYTES, t->x);
				fb_write_bin(df + RLC_FB_BYTES + 1, RLC_FB_BYTES, t->y);
			}
		}
	} RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		eb_free(t);
	}
}

