		bn_new(_k);

		for (i = 0; i < (1 << (EP_WIDTH - 2)); i++) {
			ep_null(t[i]);
			ep_new(t[i]);
		}

		ep_curve_get_ord(n);
		bn_mod(_k, oc, n);


		ep_tab(t, nm, EP_WIDTH);


		l = RLC_FP_BITS + 2;
		bn_rec_naf(naf, &l, _k, EP_WIDTH);

		ep_set_infty(iu);
		for (i = l - 1; i >= 0; i--) {
			ep_dbl(iu, iu);

			u = naf[i];
			if (u > 0) {
				ep_add(iu, iu, t[u / 2]);
			} else if (u < 0) {
				ep_sub(iu, iu, t[-u / 2]);
			}
		}

		ep_norm(iu, iu);
		if (bn_sign(_k) == RLC_NEG) {
			ep_neg(iu, iu);
		}
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(n);
		bn_free(_k);

		for (i = 0; i < (1 << (EP_WIDTH - 2)); i++) {
			ep_free(t[i]);
		}
	}
}

void wl(fp_t yc, const fp_t mq, const bn_t xi) {
	int i, l;
	fp_t r;

	fp_null(r);

	if (bn_is_zero(xi)) {
		fp_set_dig(yc, 1);
		return;
	}

	RLC_TRY {
		fp_new(r);

		l = bn_bits(xi);

		fp_copy(r, mq);

		for (i = l - 2; i >= 0; i--) {
			fp_sqr(r, r);
			if (bn_get_bit(xi, i)) {
				fp_mul(r, r, mq);
			}
		}

		if (bn_sign(xi) == RLC_NEG) {
			fp_inv(yc, r);
		} else {
			fp_copy(yc, r);
		}
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		fp_free(r);
	}
}

