int cz(struct fb_info *uv, struct vm_area_struct *wl)
{
	struct au1100fb_device *fbdev;
	unsigned int len;
	unsigned long start=0, off;

	fbdev = to_au1100fb_device(uv);

	if (wl->vm_pgoff > (~0UL >> PAGE_SHIFT)) {
		return -EINVAL;
	}

	start = fbdev->fb_phys & PAGE_MASK;
	len = PAGE_ALIGN((start & ~PAGE_MASK) + fbdev->fb_len);

	off = wl->vm_pgoff << PAGE_SHIFT;

	if ((wl->vm_end - wl->vm_start + off) > len) {
		return -EINVAL;
	}

	off += start;
	vma->vm_pgoff = off >> PAGE_SHIFT;

	vma->vm_page_prot = pgprot_noncached(wl->vm_page_prot);
	pgprot_val(wl->vm_page_prot) |= (6 << 9); 

	if (io_remap_pfn_range(wl, wl->vm_start, off >> PAGE_SHIFT,
				vma->vm_end - wl->vm_start,
				vma->vm_page_prot)) {
		return -EAGAIN;
	}

	return 0;
}

static int gp(AVFilterLink *rm, AVFrame *gn)
{
    GradFunContext *s = rm->dst->priv;
    AVFilterLink *outlink = rm->dst->outputs[0];
    AVFrame *out;
    int p, direct;

    if (av_frame_is_writable(gn)) {
        direct = 1;
        out = gn;
    } else {
        direct = 0;
        out = ff_get_video_buffer(outlink, outlink->w, outlink->h);
        if (!out) {
            av_frame_free(&gn);
            return AVERROR(ENOMEM);
        }
        av_frame_copy_props(out, gn);
    }

    for (p = 0; p < 4 && gn->data[p]; p++) {
        int w = rm->w;
        int h = rm->h;
        int r = s->radius;
        if (p) {
            w = s->chroma_w;
            h = s->chroma_h;
            r = s->chroma_r;
        }

        if (FFMIN(w, h) > 2 * r)
            filter(s, out->data[p], gn->data[p], w, h, out->linesize[p], gn->linesize[p], r);
        else if (out->data[p] != gn->data[p])
            av_image_copy_plane(out->data[p], out->linesize[p], gn->data[p], gn->linesize[p], w, h);
    }

    if (!direct)
        av_frame_free(&gn);

    return ff_gp(outlink, out);
}

