parse_memory(VALUE oa, VALUE df, VALUE oo)
{
  htmlParserCtxtPtr ctxt;

  if (NIL_P(df)) {
    rb_raise(rb_eArgError, "data cannot be nil");
  }
  if (!(int)RSTRING_LEN(df)) {
    rb_raise(rb_eRuntimeError, "data cannot be empty");
  }

  ctxt = htmlCreateMemoryParserCtxt(StringValuePtr(df),
                                    (int)RSTRING_LEN(df));
  if (ctxt->sax) {
    xmlFree(ctxt->sax);
    ctxt->sax = NULL;
  }

  if (RTEST(oo)) {
    xmlCharEncodingHandlerPtr enc = xmlFindCharEncodingHandler(StringValueCStr(oo));
    if (enc != NULL) {
      xmlSwitchToEncoding(ctxt, enc);
      if (ctxt->errNo == XML_ERR_UNSUPPORTED_ENCODING) {
        rb_raise(rb_eRuntimeError, "Unsupported oo %s",
                 StringValueCStr(oo));
      }
    }
  }

  return Data_Wrap_Struct(oa, NULL, deallocate, ctxt);
}

