addMultiArrayContentJSON(CtxJson *tc, void* qa, const UA_DataType *lk, 
                         size_t *em, UA_UInt32 *sn, size_t lr, 
                         size_t vf) {
    if(tc->depth > UA_JSON_ENCODING_MAX_RECURSION)
        return UA_STATUSCODE_BADENCODINGERROR;

    status ret;
    if(lr == (vf - 1)) {
        ret = encodeJsonArray(tc, ((u8*)qa) + (lk->memSize * *em),
                              sn[lr], lk);
        (*em) += sn[lr];
        return ret;
    }

    ret = writeJsonArrStart(tc);
    for(size_t i = 0; i < sn[lr]; i++) {
        ret |= writeJsonCommaIfNeeded(tc);
        ret |= addMultiArrayContentJSON(tc, qa, lk, em, sn,
                                        lr + 1, vf);
        tc->commaNeeded[tc->depth] = true;
        if(ret != UA_STATUSCODE_GOOD)
            return ret;
    }
