static void hb(struct bpf_prog *uc, u32 jw, u32 nx)
{
	struct bpf_insn *insn = uc->insnsi;
	u32 i, insn_cnt = uc->len;
	bool pseudo_call;
	u8 code;
	int off;

	for (i = 0; i < insn_cnt; i++, insn++) {
		code = insn->code;
		if (BPF_CLASS(code) != BPF_JMP)
			continue;
		if (BPF_OP(code) == BPF_EXIT)
			continue;
		if (BPF_OP(code) == BPF_CALL) {
			if (insn->src_reg == BPF_PSEUDO_CALL)
				pseudo_call = true;
			else
				continue;
		} else {
			pseudo_call = false;
		}
		off = pseudo_call ? insn->imm : insn->off;

		if (i < jw && i + off + 1 > jw)
			off += nx;
		else if (i > jw + nx && i + off + 1 <= jw + nx)
			off -= nx;

		if (pseudo_call)
			insn->imm = off;
		else
			insn->off = off;
	}
}

