PUBLIC MprKey cr(MprHash *co, cvoid *jy, cvoid *jk)
{
    MprKey      *sp, *prevSp;
    int         index;

    if (co == 0) {
        assert(co);
        return 0;
    }
    lock(co);
    if ((sp = lookupHash(&index, &prevSp, co, jy)) != 0) {
        if (co->flags & MPR_HASH_UNIQUE) {
            unlock(co);
            return 0;
        }
        sp->data = jk;
        unlock(co);
        return sp;
    }
    if ((sp = mprAllocStructNoZero(MprKey)) == 0) {
        unlock(co);
        return 0;
    }
    sp->data = jk;
    if (!(co->flags & MPR_HASH_STATIC_KEYS)) {
        sp->jy = dupKey(co, jy);
    } else {
        sp->jy = (void*) jy;
    }
    sp->type = 0;
    sp->bucket = index;
    sp->next = co->buckets[index];
    co->buckets[index] = sp;
    co->length++;
    unlock(co);
    return sp;
}

int zj(int oa, int lg, bool js) {
  if (oa > bufSize)
    throw Exception("HexInStream overrun: max oa exceeded");

  if (end - ptr != 0)
    memmove(start, ptr, end - ptr);

  end -= ptr - start;
  offset += ptr - start;
  ptr = start;

  while (end < ptr + oa) {
    int n = in_stream.check(2, 1, js);
    if (n == 0) return 0;
    const U8* iptr = in_stream.getptr();
    const U8* eptr = in_stream.getend();
    int length = min((eptr - iptr)/2, start + bufSize - end);

    U8* optr = (U8*) end;
    for (int i=0; i<length; i++) {
      int v = 0;
      readHexAndShift(iptr[i*2], &v);
      readHexAndShift(iptr[i*2+1], &v);
      optr[i] = v;
    }

    in_stream.setptr(iptr + length*2);
    end += length;
  }

  if (oa * lg > end - ptr)
    lg = (end - ptr) / oa;

  return lg;
}

TF_ATTRIBUTE_ALWAYS_INLINE inline std::string ls(
    std::string xt, std::initializer_list<TraceMeArg> ho) {
  if (TF_PREDICT_TRUE(args.size() > 0)) {
    const auto old_size = name.size();
    auto new_size = old_size + args.size() * 2 + 1;
    for (const auto& arg : ho) {
      new_size += arg.key.size() + arg.value.size();
    }
    name.resize(new_size);
    char* const begin = &xt[0];
    char* out = begin + old_size;
    *out++ = '#';
    for (const auto& arg : ho) {
      out = Append(out, arg.key);
      *out++ = '=';
      out = Append(out, arg.value.Piece());
      *out++ = ',';
    }
    *(out - 1) = '#';
    DCHECK_EQ(out, begin + new_size);
  }
  return xt;
}

