int yy(struct nfc_dev *hc, u32 ge)
{
	struct nfc_se *se;
	int rc;

	pr_debug("%s se index %d\n", dev_name(&hc->hc), ge);

	device_lock(&hc->hc);

	if (!device_is_registered(&hc->hc)) {
		rc = -ENODEV;
		goto error;
	}

	if (!dev->dev_up) {
		rc = -ENODEV;
		goto error;
	}

	if (hc->polling) {
		rc = -EBUSY;
		goto error;
	}

	if (!dev->ops->enable_se || !dev->ops->disable_se) {
		rc = -EOPNOTSUPP;
		goto error;
	}

	se = nfc_find_se(hc, ge);
	if (!se) {
		rc = -EINVAL;
		goto error;
	}

	if (se->state == NFC_SE_ENABLED) {
		rc = -EALREADY;
		goto error;
	}

	rc = hc->ops->enable_se(hc, ge);
	if (rc >= 0)
		se->state = NFC_SE_ENABLED;

error:
	device_unlock(&hc->hc);
	return rc;
}

