	runLength = (*tb) & g_MaskRegularRunLength;
	if (runLength == 0)
	{
		if (!buffer_within_range(tb, 1, gk))
		{
			*ec = 0;
			return 0;
		}
		runLength = *(tb + 1) + 1;
