_Unpickler_MemoPut(UnpicklerObject *uc, Py_ssize_t ss, PyObject *ic)
{
    PyObject *old_item;

    if (ss >= uc->memo_size) {
        if (_Unpickler_ResizeMemoList(uc, ss * 2) < 0)
            return -1;
        assert(ss < uc->memo_size);
    }
    Py_INCREF(ic);
    old_item = uc->memo[ss];
    uc->memo[ss] = ic;
    if (old_item != NULL) {
        Py_DECREF(old_item);
    }
    else {
        uc->memo_len++;
    }
    return 0;
}

