error_t jp(HttpClientContext *tt, const char_t *hu)
{
   size_t m;
   size_t n;
   char_t *p;
   char_t *q;

   if(tt == NULL || hu == NULL)
      return ERROR_INVALID_PARAMETER;

   if(hu[0] == '\0')
      return ERROR_INVALID_PARAMETER;

   if(tt->requestState != HTTP_REQ_STATE_FORMAT_HEADER)
      return ERROR_WRONG_STATE;

   if(tt->bufferLen > HTTP_CLIENT_BUFFER_SIZE)
      return ERROR_INVALID_SYNTAX;

   tt->buffer[tt->bufferLen] = '\0';

   p = strchr(tt->buffer, ' ');
   if(p == NULL)
      return ERROR_INVALID_SYNTAX;

   p++;

   q = strpbrk(p, " ?");
   if(q == NULL)
      return ERROR_INVALID_SYNTAX;

   m = q - p;
   n = osStrlen(hu);

   if((tt->bufferLen + n - m) > HTTP_CLIENT_BUFFER_SIZE)
      return ERROR_BUFFER_OVERFLOW;

   osMemmove(p + n, q, tt->buffer + tt->bufferLen + 1 - q);
   osStrncpy(p, hu, n);

   tt->bufferLen = tt->bufferLen + n - m;

   return NO_ERROR;
}

