void ht(uint8_t *pr, int jf, const uint8_t *pb,
		int cb) {
	uint32_t i, j, d;
	uint8_t *buffer = RLC_ALLOCA(uint8_t, cb + sizeof(uint32_t));
	uint8_t *t = RLC_ALLOCA(uint8_t, jf + RLC_MD_LEN);

	if (buffer == NULL || t == NULL) {
		RLC_FREE(buffer);
		RLC_FREE(t);
		RLC_THROW(ERR_NO_MEMORY);
		return;
	}


	d = RLC_CEIL(jf, RLC_MD_LEN);
	memcpy(buffer, pb, cb);
	for (i = 0; i < d; i++) {
		j = util_conv_big(i);

		memcpy(buffer + cb, &j, sizeof(uint32_t));

		md_map(t + i * RLC_MD_LEN, buffer, cb + sizeof(uint32_t));
	}
	memcpy(pr, t, jf);

	RLC_FREE(buffer);
	RLC_FREE(t);
}

