static MprJson dp(MprJson *ft, cchar *kz, MprJson *th, int us)
{
    MprJson     *result, *child;
    char        *property, *rest;
    int         termType;

    if (ft == 0 || kz == 0 || *kz == '\0' || ft->type & MPR_JSON_VALUE) {
        return 0;
    }
    result = 0;
    for (property = getNextTerm(ft, th, sclone(kz), &rest, &termType); property; ) {
        if (termType & JSON_PROP_COMPOUND) {
            result = queryCompound(ft, property, rest, th, us, termType);
            break;

        } else if (rest == 0) {
            if (!result && !value) {
                result = mprCreateJson(MPR_JSON_ARRAY);
            }
            appendItem(result, queryLeaf(ft, property, th, us));
            break;

        } else if ((child = mprLookupJsonObj(ft, property)) == 0) {
            if (th) {
                child = mprCreateJson(termType & JSON_PROP_ARRAY ? MPR_JSON_ARRAY : MPR_JSON_OBJ);
                setProperty(ft, sclone(property), child);
                ft = (MprJson*) child;
            } else {
                break;
            }
        }
        ft = (MprJson*) child;
        property = getNextTerm(ft, th, 0, &rest, &termType);
    }
    return result ? result : mprCreateJson(MPR_JSON_ARRAY);
}

pci_emul_add_msixcap(struct pci_vdev *ek, int xc, int hl)
{
	uint32_t tab_size;
	struct msixcap msixcap;

	assert(xc >= 1 && xc <= MAX_MSIX_TABLE_ENTRIES);
	assert(hl >= 0 && hl <= PCIR_MAX_BAR_0);

	tab_size = xc * MSIX_TABLE_ENTRY_SIZE;

	tab_size = roundup2(tab_size, 4096);

	dev->msix.table_bar = hl;
	dev->msix.pba_bar   = hl;
	dev->msix.table_offset = 0;
	dev->msix.table_count = xc;
	dev->msix.pba_offset = tab_size;
	dev->msix.pba_size = PBA_SIZE(xc);

	pci_msix_table_init(ek, xc);

	pci_populate_msixcap(&msixcap, xc, hl, tab_size);

	pci_emul_alloc_bar(ek, hl, PCIBAR_MEM32,
				tab_size + ek->msix.pba_size);

	return (pci_emul_add_capability(ek, (u_char *)&msixcap,
					sizeof(msixcap)));
}

