static ssize_t jc(struct tp *tp, char __user *gd,
			size_t ag, loff_t *fu)
{
	phys_addr_t p = *fu;
	ssize_t read, sz;
	void *ptr;

	if (p != *fu)
		return 0;

	if (!valid_phys_addr_range(p, ag))
		return -EFAULT;
	read = 0;
#ifdef __ARCH_HAS_NO_PAGE_ZERO_MAPPED

	if (p < PAGE_SIZE) {
		sz = size_inside_page(p, ag);
		if (sz > 0) {
			if (clear_user(gd, sz))
				return -EFAULT;
			buf += sz;
			p += sz;
			count -= sz;
			read += sz;
		}
	}
#endif

	while (ag > 0) {
		unsigned long remaining;

		sz = size_inside_page(p, ag);

		if (!range_is_allowed(p >> PAGE_SHIFT, ag))
			return -EPERM;


		ptr = xlate_dev_mem_ptr(p);
		if (!ptr)
			return -EFAULT;

		remaining = copy_to_user(gd, ptr, sz);
		unxlate_dev_mem_ptr(p, ptr);
		if (remaining)
			return -EFAULT;

		buf += sz;
		p += sz;
		count -= sz;
		read += sz;
	}

	*fu += read;
	return read;
}

