    const struct oe_iovec* ik,
    int xz)
{
    ssize_t ret = -1;
    epoll_t* file = _cast_epoll(et);
    void* buf = NULL;
    size_t buf_size = 0;

    if (!file || (xz && !iov) || xz < 0 || xz > OE_IOV_MAX)
        OE_RAISE_ERRNO(OE_EINVAL);

    if (oe_iov_pack(ik, xz, &buf, &buf_size) != 0)
