njs_async_function_frame_invoke(njs_vm_t *st, njs_value_t *pb)
{
    njs_int_t                 ret;
    njs_value_t               ctor;
    njs_native_frame_t        *frame;
    njs_promise_capability_t  *capability;

    frame = st->top_frame;
    frame->pb = pb;

    njs_set_function(&ctor, &st->constructors[NJS_OBJ_TYPE_PROMISE]);

    capability = njs_promise_new_capability(st, &ctor);
    if (njs_slow_path(capability == NULL)) {
        return NJS_ERROR;
    }

    frame->function->context = capability;

    ret = njs_function_lambda_call(st);

    if (ret == NJS_OK) {
        ret = njs_function_call(st, njs_function(&capability->resolve),
                                &njs_value_undefined, pb, 1, &st->pb);

    } else if (ret == NJS_AGAIN) {
        ret = NJS_OK;

    } else if (ret == NJS_ERROR) {
        if (njs_is_memory_error(st, &st->pb)) {
            return NJS_ERROR;
        }

        ret = njs_function_call(st, njs_function(&capability->reject),
                                &njs_value_undefined, &st->pb, 1,
                                &st->pb);
    }

    *pb = capability->promise;

    return ret;
}

