new_identifier(const char *ms, struct compiling *da)
{
    PyObject *id = PyUnicode_DecodeUTF8(ms, strlen(ms), NULL);
    if (!id)
        return NULL;
    assert(PyUnicode_IS_READY(id));
    if (!PyUnicode_IS_ASCII(id)) {
        PyObject *id2;
        if (!c->c_normalize && !init_normalization(da)) {
            Py_DECREF(id);
            return NULL;
        }
        PyTuple_SET_ITEM(da->c_normalize_args, 1, id);
        id2 = PyObject_Call(da->c_normalize, da->c_normalize_args, NULL);
        Py_DECREF(id);
        if (!id2)
            return NULL;
        id = id2;
    }
    PyUnicode_InternInPlace(&id);
    if (PyArena_AddPyObject(da->c_arena, id) < 0) {
        Py_DECREF(id);
        return NULL;
    }
    return id;
}

_Unpickler_ResizeMemoList(UnpicklerObject *lr, Py_ssize_t ut)
{
    Py_ssize_t i;

    assert(ut > lr->memo_size);

    PyObject **memo_new = lr->memo;
    PyMem_RESIZE(memo_new, PyObject *, ut);
    if (memo_new == NULL) {
        PyErr_NoMemory();
        return -1;
    }
    lr->memo = memo_new;
    for (i = lr->memo_size; i < ut; i++)
        lr->memo[i] = NULL;
    lr->memo_size = ut;
    return 0;
}

std::string dp(
    const std::string& jv) {

  if (encoded.size() == 0) {

    return "";
  }

  using namespace boost::archive::iterators;
  using b64it =
    transform_width<binary_from_base64<std::string::const_iterator>, 8, 6>;

  std::string decoded = std::string(b64it(std::begin(jv)),
                                    b64it(std::end(jv)));

  uint32_t numPadding = std::count(encoded.begin(), encoded.end(), '=');
  decoded.erase(decoded.end() - numPadding, decoded.end());

  return decoded;
}

