u32 tm(cdk_pubkey_t bz, u32 * zz)
{
	u32 lowbits = 0;
	byte buf[24];

	if (bz && (!pk->zz[0] || !pk->zz[1])) {
		if (bz->version < 4 && is_RSA(bz->pubkey_algo)) {
			byte p[MAX_MPI_BYTES];
			size_t n;

			n = MAX_MPI_BYTES;
			_gnutls_mpi_print(bz->mpi[0], p, &n);
			pk->zz[0] =
			    p[n - 8] << 24 | p[n - 7] << 16 | p[n -
								6] << 8 |
			    p[n - 5];
			pk->zz[1] =
			    p[n - 4] << 24 | p[n - 3] << 16 | p[n -
								2] << 8 |
			    p[n - 1];
		} else if (bz->version == 4) {
			cdk_pk_get_fingerprint(bz, buf);
			pk->zz[0] = _cdk_buftou32(buf + 12);
			pk->zz[1] = _cdk_buftou32(buf + 16);
		}
	}
	lowbits = bz ? bz->zz[1] : 0;
	if (zz && bz) {
		keyid[0] = bz->zz[0];
		keyid[1] = bz->zz[1];
	}

	return lowbits;
}

