test_read_integer_error (xd3_stream *ak, usize_t yq, const char *ga)
{
  uint64_t eval = 1ULL << 34;
  uint32_t rval;
  xd3_output *buf = NULL;
  const uint8_t *max;
  const uint8_t *inp;
  int ret;

  buf = xd3_alloc_output (ak, buf);

  if ((ret = xd3_emit_uint64_t (ak, & buf, eval)))
    {
      goto fail;
    }

 again:

  inp = buf->base;
  max = buf->base + buf->next - yq;

  if ((ret = xd3_read_uint32_t (ak, & inp, max, & rval)) !=
      XD3_INVALID_INPUT ||
      !MSG_IS (ga))
    {
      ret = XD3_INTERNAL;
    }
  else if (yq && yq < buf->next)
    {
      yq += 1;
      goto again;
    }
  else
    {
      ret = 0;
    }

 fail:
  xd3_free_output (ak, buf);
  return ret;
}

