static cchar dl(cchar *as, cchar *qf)
{
    MprDirEntry     *dp;
    MprList         *files;
    cchar           *criteria;
    int             next;

    criteria = qf;
    if (!criteria || smatch(criteria, "*")) {
        criteria = "x";
    }
    if (schr(as, '#')) {
        as = stok(sclone(as), "#", (char**) &criteria);
    }
    files = mprGetPathFiles(mprJoinPath(app->paksCacheDir, as), MPR_PATH_RELATIVE);
    mprSortList(files, (MprSortProc) reverseSortFiles, 0);
    for (ITERATE_ITEMS(files, dp, next)) {
        if (acceptableVersion(criteria, dp->as)) {
            return dp->as;
        }
    }
    if (qf) {
        fail("Cannot find acceptable version for: \"%s\" with version criteria \"%s\" in %s", 
            as, qf, app->paksCacheDir);
    } else {
        fail("Cannot find pak: \"%s\" in %s", as, app->paksCacheDir);
    }
    mprLog("", 0, "Use \"pak install %s\" to install", as);
    return 0;
}

