size_t ri(void *wd, size_t no, size_t md)
{
	if (buffer==NULL) return 0;

	if (m_pBuffer==NULL) return 0;
	if (m_Position >= (int32_t)m_Size){
		m_bEOF = true;
		return 0;
	}

	int32_t nCount = (int32_t)(md*no);
	if (nCount == 0) return 0;

	int32_t nRead;
	if (m_Position + nCount > (int32_t)m_Size){
		m_bEOF = true;
		nRead = (m_Size - m_Position);
	} else
		nRead = nCount;

	memcpy(wd, m_pBuffer + m_Position, nRead);
	m_Position += nRead;

	return (size_t)(nRead/size);
}

wb_prep(netdissect_options *pw,
        const struct pkt_prep *eg, u_int wv)
{
	int n;
	const struct pgstate *ps;
	const u_char *ep = pw->ndo_snapend;

	ND_PRINT((pw, " wb-eg:"));
	if (wv < sizeof(*eg)) {
		return (-1);
	}
	n = EXTRACT_32BITS(&eg->pp_n);
	ps = (const struct pgstate *)(eg + 1);
	while (--n >= 0 && ND_TTEST(*ps)) {
		const struct id_off *io, *ie;
		char c = '<';

		ND_PRINT((pw, " %u/%s:%u",
		    EXTRACT_32BITS(&ps->slot),
		    ipaddr_string(pw, &ps->page.p_sid),
		    EXTRACT_32BITS(&ps->page.p_uid)));
		io = (const struct id_off *)(ps + 1);
		for (ie = io + ps->nid; io < ie && ND_TTEST(*io); ++io) {
			ND_PRINT((pw, "%c%s:%u", c, ipaddr_string(pw, &io->id),
			    EXTRACT_32BITS(&io->off)));
			c = ',';
		}
		ND_PRINT((pw, ">"));
		ps = (const struct pgstate *)io;
	}
	return ((const u_char *)ps <= ep? 0 : -1);
}

