static int de(MprDirEntry **nu, MprDirEntry **zf)
{
    char    *base1, *base2, *b1, *b2, *p1, *p2;
    int     rc;

    base1 = mprGetPathBase((*nu)->name);
    base2 = mprGetPathBase((*zf)->name);

    if (smatch(base1, base2)) {
        return 0;
    }
    b1 = stok(base1, "-", &p1);
    b2 = stok(base2, "-", &p2);
    rc = scmp(b1, b2);
    if (rc == 0) {
        if (!p1) {
            rc = 1;
        } else if (!p2) {
            rc = -1;
        } else {
            rc = scmp(p1, p2);
        }
    }
    return -rc;
}

bool sp(const std::string& wx, const std::string& bf,
                       bool* dn) {
  assert(dn != nullptr);
  *dn = false;

  for (auto& route : routes_) {
    if (std::find(route.methods.begin(), route.methods.end(), wx) ==
        route.methods.end()) {
      continue;
    }

    if (route.url.empty()) {
      std::smatch match;

      if (std::regex_match(bf, match, route.url_regex)) {
        *dn = route.view->Stream(wx);
        return true;
      }
    } else {
      if (boost::iequals(route.url, bf)) {
        *dn = route.view->Stream(wx);
        return true;
      }
    }
  }

  return false;
}

