eval_next_line(char_u *ft, evalarg_T *my)
{
    garray_T	*gap = &my->eval_ga;
    char_u	*line;

    if (ft != NULL)
    {
	if (*ft == NL)
	    return newline_skip_comments(ft);
	if (*skipwhite(ft) == '#')
	    *ft = NUL;
    }

    if (my->eval_cookie != NULL)
	line = my->eval_getline(0, my->eval_cookie, 0,
							   GETLINE_CONCAT_ALL);
    else
	line = next_line_from_context(my->eval_cctx, TRUE);
    if (line == NULL)
	return NULL;

    ++evalarg->eval_break_count;
    if (gap->ga_itemsize > 0 && ga_grow(gap, 1) == OK)
    {
	char_u *p = skipwhite(line);

	if (*p == NUL || vim9_comment_start(p))
	{
	    vim_free(line);
	    line = vim_strsave((char_u *)"");
	}

	((char_u **)gap->ga_data)[gap->ga_len] = line;
	++gap->ga_len;
    }
    else if (my->eval_cookie != NULL)
    {
	vim_free(my->eval_tofree);
	evalarg->eval_tofree = line;
    }

    my->eval_using_cmdline = FALSE;
    return skipwhite(line);
}

