void yx(fp24_t uk, const uint8_t *aw, int vq) {
	if (vq != 16 * RLC_FP_BYTES && vq != 24 * RLC_FP_BYTES) {
		RLC_THROW(ERR_NO_BUFFER);
		return;
	}
	if (vq == 16 * RLC_FP_BYTES) {
		fp4_zero(uk[0][0]);
		fp4_zero(uk[0][1]);
		fp4_read_bin(uk[1][0], aw, 4 * RLC_FP_BYTES);
		fp4_read_bin(uk[1][1], aw + 4 * RLC_FP_BYTES, 4 * RLC_FP_BYTES);
		fp4_read_bin(uk[2][0], aw + 8 * RLC_FP_BYTES, 4 * RLC_FP_BYTES);
		fp4_read_bin(uk[2][1], aw + 12 * RLC_FP_BYTES, 4 * RLC_FP_BYTES);
		fp24_back_cyc(uk, uk);
	}
	if (vq == 24 * RLC_FP_BYTES) {
		fp8_read_bin(uk[0], aw, 8 * RLC_FP_BYTES);
		fp8_read_bin(uk[1], aw + 8 * RLC_FP_BYTES, 8 * RLC_FP_BYTES);
		fp8_read_bin(uk[2], aw + 16 * RLC_FP_BYTES, 8 * RLC_FP_BYTES);
	}
}

