void ki(fb_t fc, const fb_t yp, const bn_t kh) {
	int i, l;
	fb_t r;

	if (bn_is_zero(kh)) {
		fb_set_dig(fc, 1);
		return;
	}

	fb_null(r);

	RLC_TRY {
		fb_new(r);

		l = bn_bits(kh);

		fb_copy(r, yp);

		for (i = l - 2; i >= 0; i--) {
			fb_sqr(r, r);
			if (bn_get_bit(kh, i)) {
				fb_mul(r, r, yp);
			}
		}

		if (bn_sign(kh) == RLC_NEG) {
			fb_inv(fc, r);
		} else {
			fb_copy(fc, r);
		}
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		fb_free(r);
	}
}

