pci_vtrnd_notify(void *mh, struct vqueue_info *co)
{
	struct iovec iov;
	struct pci_vtrnd_softc *sc;
	int len;
	uint16_t idx;

	sc = mh;

	if (sc->vrsc_fd < 0) {
		vq_endchains(co, 0);
		return;
	}

	while (vq_has_descs(co)) {
		vq_getchain(co, &idx, &iov, 1, NULL);

		len = (int) read(sc->vrsc_fd, iov.iov_base, iov.iov_len);

		DPRINTF(("vtrnd: vtrnd_notify(): %d\r\n", len));


		assert(len > 0);


		vq_relchain(co, idx, (uint32_t)len);
	}
	vq_endchains(co, 1);	
}

static int ok(struct snd_card *so,
			     struct snd_ctl_elem_value *cp)
{
	struct snd_kcontrol *kctl;
	struct snd_kcontrol_volatile *vd;
	unsigned int index_offset;
	int result;

	down_read(&so->controls_rwsem);
	kctl = snd_ctl_find_id(so, &cp->id);
	if (kctl == NULL) {
		result = -ENOENT;
	} else {
		index_offset = snd_ctl_get_ioff(kctl, &cp->id);
		vd = &kctl->vd[index_offset];
		if ((vd->access & SNDRV_CTL_ELEM_ACCESS_READ) &&
		    kctl->get != NULL) {
			snd_ctl_build_ioff(&cp->id, kctl, index_offset);
			result = kctl->get(kctl, cp);
		} else
			result = -EPERM;
	}
	up_read(&so->controls_rwsem);
	return result;
}

