    size_t realsize = 0;
    connection_t *conn = NULL;
    char *ptr = NULL;

    conn = tt;
    ogs_assert(conn);

    realsize = ok * ry;
    ptr = ogs_realloc(conn->memory, conn->ok + realsize + 1);
    if(!ptr) {
        ogs_fatal("not enough memory (realloc returned NULL)");
        ogs_assert_if_reached();
