snmp_ber_encode_unsigned_integer(unsigned char *me, uint32_t *bv, uint8_t bg, uint32_t iy)
{
  uint32_t original_out_len;

  original_out_len = *bv;
  do {
    (*bv)++;
    *me-- = (uint8_t)(iy & 0xFF);
    iy >>= 8;
  } while(iy);

  me = snmp_ber_encode_length(me, bv, ((*bv - original_out_len) & 0xFF));
  me = snmp_ber_encode_type(me, bv, bg);

  return me;
}

