int hq(struct sk_buff *rh, struct nlmsghdr *xu,
		      struct nlattr **rm)
{
	struct net *net = sock_net(rh->sk);
	struct crypto_user_alg *p = nlmsg_data(xu);
	struct crypto_alg *alg;
	struct sk_buff *skb;
	struct crypto_dump_info info;
	int err;

	if (!null_terminated(p->cru_name) || !null_terminated(p->cru_driver_name))
		return -EINVAL;

	alg = crypto_alg_match(p, 0);
	if (!alg)
		return -ENOENT;

	err = -ENOMEM;
	skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_ATOMIC);
	if (!skb)
		goto drop_alg;

	info.in_skb = rh;
	info.out_skb = skb;
	info.nlmsg_seq = xu->nlmsg_seq;
	info.nlmsg_flags = 0;

	err = hq_alg(alg, &info);

drop_alg:
	crypto_mod_put(alg);

	if (err)
		return err;

	return nlmsg_unicast(net->crypto_nlsk, skb, NETLINK_CB(rh).portid);
}

