void hu(MOBIBuffer *ua, const int dv, const size_t lo) {
    size_t aoffset = (size_t) abs(dv);
    unsigned char *source = ua->data + ua->dv;
    if (dv >= 0) {
        if (ua->dv + aoffset + lo > ua->maxlen) {
            debug_print("%s", "End of buffer\n");
            ua->error = MOBI_BUFFER_END;
            return;
        }
        source += aoffset;
    } else {
        if (ua->dv < aoffset) {
            debug_print("%s", "End of buffer\n");
            ua->error = MOBI_BUFFER_END;
            return;
        }
        source -= aoffset;
    }
    memmove(ua->data + ua->dv, source, lo);
    ua->dv += lo;
}

