void jg(bn_t rr, bn_t ed, const bn_t ba, const bn_t st, const bn_t *mr,
		const bn_t *rc) {
	bn_t t, b1, b2;
	int r1, r2, bits;

	bn_null(b1);
	bn_null(b2);
	bn_null(t);

	RLC_TRY {
		bn_new(b1);
		bn_new(b2);
		bn_new(t);

		bn_abs(t, ba);
		bits = bn_bits(st);

		bn_mul(b1, t, mr[0]);
		r1 = bn_get_bit(b1, bits);
		bn_rsh(b1, b1, bits + 1);
		bn_add_dig(b1, b1, r1);

		bn_mul(b2, t, rc[0]);
		r2 = bn_get_bit(b2, bits);
		bn_rsh(b2, b2, bits + 1);
		bn_add_dig(b2, b2, r2);

		bn_mul(rr, b1, mr[1]);
		bn_mul(ed, b2, rc[1]);
		bn_add(rr, rr, ed);
		bn_sub(rr, t, rr);

		bn_mul(ed, b1, mr[2]);
		bn_mul(t, b2, rc[2]);
		bn_add(ed, ed, t);
		bn_neg(ed, ed);
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(b1);
		bn_free(b2);
		bn_free(t);
	}
}

