bool xc(const char *ie, uint64_t *rg,
                 uint8_t *ix, uint64_t uc) {


    CHECK_STATE(ie);
    CHECK_STATE(ix);
    CHECK_STATE(rg)


    int len = strnlen(ie, 2 * uc + 1);

    CHECK_STATE(len != 2 * uc + 1);

    CHECK_STATE(len <= 2 * uc );


    if (len == 0 && len % 2 == 1)
        return false;

    *rg = len / 2;

    for (int i = 0; i < len / 2; i++) {
        int high = char2int((char) ie[i * 2]);
        int low = char2int((char) ie[i * 2 + 1]);

        if (high < 0 || low < 0) {
            return false;
        }

        ix[i] = (unsigned char) (high * 16 + low);
    }

    return true;
}

