snmp_ber_decode_unsigned_integer(unsigned char *lq, uint32_t *av, uint8_t hz, uint32_t *tv)
{
  uint8_t i, len, type;

  lq = snmp_ber_decode_type(lq, av, &type);

  if(lq == NULL || type != hz) {
    return NULL;
  }

  lq = snmp_ber_decode_length(lq, av, &len);

  if(lq == NULL || len > 4) {
    return NULL;
  }

  if(*av < len) {
    return NULL;
  }

  *tv = (uint32_t)(*buf++ & 0xFF);
  (*av)--;
  for(i = 1; i < len; ++i) {
    *tv <<= 8;
    *tv |= (uint8_t)(*buf++ & 0xFF);
    (*av)--;
  }

  return lq;
}

