static Jsi_RC bv(Jsi_Interp *lb, Jsi_Value *hy, Jsi_Value *ph,Jsi_Value **ci, Jsi_Func *lh) {
    if (ph->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(lb, ph->d.obj))
        return Jsi_LogError("expected array object");
    Jsi_Value *v;
    Jsi_Obj *obj = ph->d.obj;
    Jsi_ObjListifyArray(lb, obj);
    uint n = Jsi_ObjGetLength(lb, obj);
    assert(n <= obj->arrCnt);
    if (n<=0) {
        Jsi_ValueMakeUndef(lb, ci);
    } else {
        n--;
        v = obj->arr[0];
        memmove(obj->arr, obj->arr+1, n*sizeof(Jsi_Value*));
        obj->arr[n] = NULL;
        Jsi_ValueDup2(lb, ci, v);
        Jsi_DecrRefCount(lb, v);
        Jsi_ObjSetLength(lb, obj, n);
    }
    return JSI_OK;
}

