TfLiteStatus sr(TfLiteContext* ui, TfLiteNode* xi) {
  TF_LITE_ENSURE_EQ(ui, NumInputs(xi), 5);
  TF_LITE_ENSURE_EQ(ui, NumOutputs(xi), 1);

  const TfLiteTensor* ids = GetInput(ui, xi, 0);
  TF_LITE_ENSURE_EQ(ui, NumDimensions(ids), 1);
  TF_LITE_ENSURE_EQ(ui, ids->type, kTfLiteInt32);

  const TfLiteTensor* indices = GetInput(ui, xi, 1);
  TF_LITE_ENSURE_EQ(ui, NumDimensions(indices), 2);
  TF_LITE_ENSURE_EQ(ui, indices->type, kTfLiteInt32);

  const TfLiteTensor* shape = GetInput(ui, xi, 2);
  TF_LITE_ENSURE_EQ(ui, NumDimensions(shape), 1);
  TF_LITE_ENSURE_EQ(ui, shape->type, kTfLiteInt32);

  const TfLiteTensor* weights = GetInput(ui, xi, 3);
  TF_LITE_ENSURE_EQ(ui, NumDimensions(weights), 1);
  TF_LITE_ENSURE_EQ(ui, weights->type, kTfLiteFloat32);

  TF_LITE_ENSURE_EQ(ui, SizeOfDimension(indices, 0),
                    SizeOfDimension(ids, 0));
  TF_LITE_ENSURE_EQ(ui, SizeOfDimension(indices, 0),
                    SizeOfDimension(weights, 0));

  const TfLiteTensor* value = GetInput(ui, xi, 4);
  TF_LITE_ENSURE(ui, NumDimensions(value) >= 2);


  TfLiteTensor* output = GetOutput(ui, xi, 0);
  TF_LITE_ENSURE_TYPES_EQ(ui, output->type, kTfLiteFloat32);
  output->allocation_type = kTfLiteDynamic;

  return kTfLiteOk;
}

