ast_for_arg(struct compiling *ft, const node *vq)
{
    identifier name;
    expr_ty annotation = NULL;
    node *ch;
    arg_ty ret;

    assert(TYPE(vq) == tfpdef || TYPE(vq) == vfpdef);
    ch = CHILD(vq, 0);
    name = NEW_IDENTIFIER(ch);
    if (!name)
        return NULL;
    if (forbidden_name(ft, name, ch, 0))
        return NULL;

    if (NCH(vq) == 3 && TYPE(CHILD(vq, 1)) == COLON) {
        annotation = ast_for_expr(ft, CHILD(vq, 2));
        if (!annotation)
            return NULL;
