BOOL wq(rdpNego* qn, wStream* lb)
{
	BYTE li;
	BYTE type;
	UINT16 length;

	if (!tpkt_read_header(lb, &length))
		return FALSE;

	if (!tpdu_read_connection_request(lb, &li, length))
		return FALSE;

	if (li != Stream_GetRemainingLength(lb) + 6)
	{
		WLog_ERR(TAG, "Incorrect TPDU length indicator.");
		return FALSE;
	}

	if (!wq_token_or_cookie(qn, lb))
	{
		WLog_ERR(TAG, "Failed to parse routing token or cookie.");
		return FALSE;
	}

	if (Stream_GetRemainingLength(lb) >= 8)
	{

		Stream_Read_UINT8(lb, type); 

		if (type != TYPE_RDP_NEG_REQ)
		{
			WLog_ERR(TAG, "Incorrect negotiation request type %" PRIu8 "", type);
			return FALSE;
		}

		nego_process_negotiation_request(qn, lb);
	}

	return tpkt_ensure_stream_consumed(lb, length);
}

