SWTPM_NVRAM_CheckHeader(unsigned char *aw, uint32_t xz,
                        uint32_t *as, uint16_t *qd,
                        uint8_t *qa, bool mu)
{
    blobheader *bh = (blobheader *)aw;

    if (xz < sizeof(bh)) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "not enough bytes for header: %u\n", xz);
        return TPM_BAD_PARAMETER;
    }

    if (ntohl(bh->totlen) != xz) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "broken header: bh->totlen %u != %u\n",
                      htonl(bh->totlen), xz);
        return TPM_BAD_PARAMETER;
    }

    if (bh->min_version > BLOB_HEADER_VERSION) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "Minimum required version for the blob is %d, we "
                      "only support version %d\n", bh->min_version,
                      BLOB_HEADER_VERSION);
        return TPM_BAD_VERSION;
    }

    *qa = bh->version;
    *as = ntohs(bh->hdrsize);
    *qd = ntohs(bh->flags);

    return TPM_SUCCESS;
}

