  end -= ptr - b;
  ptr = b;


  while (end < b + bf) {
    size_t n = fread((U8 *)end, b + sizeof(b) - end, 1, file);
    if (n == 0) {
      if (ferror(file))
        throw SystemException("fread", errno);
      if (feof(file))
        throw EndOfStream();
      return 0;
    }
    end += b + sizeof(b) - end;
  }

  if (bf * mu > end - ptr)
    mu = (end - ptr) / bf;

  return mu;
}

