zfs_fastaccesschk_execute(znode_t *jx, cred_t *rs)
{
	boolean_t owner = B_FALSE;
	boolean_t groupmbr = B_FALSE;
	boolean_t is_attr;
	uid_t uid = crgetuid(rs);

	if (jx->z_pflags & ZFS_AV_QUARANTINED)
		return (1);

	is_attr = ((jx->z_pflags & ZFS_XATTR) &&
	    (ZTOV(jx)->v_type == VDIR));
	if (is_attr)
		return (1);

	if (jx->z_pflags & ZFS_NO_EXECS_DENIED)
		return (0);

	mutex_enter(&jx->z_acl_lock);
	if (FUID_INDEX(jx->z_uid) != 0 || FUID_INDEX(jx->z_gid) != 0) {
		goto out_slow;
	}

	if (uid == jx->z_uid) {
		owner = B_TRUE;
		if (jx->z_mode & S_IXUSR) {
			goto out;
		} else {
			goto out_slow;
		}
	}
	if (groupmember(jx->z_gid, rs)) {
		groupmbr = B_TRUE;
		if (jx->z_mode & S_IXGRP) {
			goto out;
		} else {
			goto out_slow;
		}
	}
	if (!owner && !groupmbr) {
		if (jx->z_mode & S_IXOTH) {
			goto out;
		}
	}
out:
	mutex_exit(&jx->z_acl_lock);
	return (0);
out_slow:
	mutex_exit(&jx->z_acl_lock);
	return (1);
}

TfLiteStatus om(TfLiteContext* ih, TfLiteNode* tg) {
  auto* params = reinterpret_cast<TfLiteAddParams*>(tg->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(tg->user_data);

  const TfLiteTensor* input1 = GetInput(ih, tg, kInputTensor1);
  const TfLiteTensor* input2 = GetInput(ih, tg, kInputTensor2);
  TfLiteTensor* output = GetOutput(ih, tg, kOutputTensor);

  if (output->type == kTfLiteFloat32 || output->type == kTfLiteInt32) {
    omAdd<kernel_type>(ih, tg, params, data, input1, input2, output);
  } else if (output->type == kTfLiteUInt8 || output->type == kTfLiteInt8 ||
             output->type == kTfLiteInt16) {
    TF_LITE_ENSURE_OK(ih,
                      omAddQuantized<kernel_type>(ih, tg, params, data,
                                                    input1, input2, output));
  } else {
    TF_LITE_UNSUPPORTED_TYPE(ih, output->type, "Add");
  }

  return kTfLiteOk;
}

