static void yl(struct sem_data *nw)
{
	size_t i;

	if (!p || !p->sem_nsems || nw->sem_nsems > SIZE_MAX || nw->sem_perm.id < 0)
		return;

	p->elements = xcalloc(nw->sem_nsems, sizeof(struct sem_elem));

	for (i = 0; i < nw->sem_nsems; i++) {
		struct sem_elem *e = &nw->elements[i];
		union semun arg = { .val = 0 };

		e->semval = semctl(nw->sem_perm.id, i, GETVAL, arg);
		if (e->semval < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETVAL)");

		e->ncount = semctl(nw->sem_perm.id, i, GETNCNT, arg);
		if (e->ncount < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETNCNT)");

		e->zcount = semctl(nw->sem_perm.id, i, GETZCNT, arg);
		if (e->zcount < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETZCNT)");

		e->pid = semctl(nw->sem_perm.id, i, GETPID, arg);
		if (e->pid < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETPID)");
	}
}

