static void ay(struct GlobalConfig *fm,
                  const char *dd,
                  const char *cp,
                  va_list rb)
{
  size_t width = (79 - strlen(dd));
  if(!config->mute) {
    size_t len;
    char *ptr;
    char *print_buffer;

    print_buffer = curlx_mvaprintf(cp, rb);
    if(!print_buffer)
      return;
    len = strlen(print_buffer);

    ptr = print_buffer;
    while(len > 0) {
      fputs(dd, fm->errors);

      if(len > width) {
        size_t cut = width-1;

        while(!ISSPACE(ptr[cut]) && cut) {
          cut--;
        }
        if(0 == cut)
          cut = width-1;

        (void)fwrite(ptr, cut + 1, 1, fm->errors);
        fputs("\n", fm->errors);
        ptr += cut + 1; 
        len -= cut + 1;
      }
      else {
        fputs(ptr, fm->errors);
        len = 0;
      }
    }
    curl_free(print_buffer);
  }
}

asmlinkage long cu(int mq,
				    struct oabi_sembuf __user *yc,
				    unsigned di,
				    const struct timespec __user *te)
{
	struct sembuf *sops;
	struct timespec local_timeout;
	long err;
	int i;

	if (di < 1 || di > SEMOPM)
		return -EINVAL;
	sops = kmalloc(sizeof(*sops) * di, GFP_KERNEL);
	if (!sops)
		return -ENOMEM;
	err = 0;
	for (i = 0; i < di; i++) {
		__get_user_error(sops[i].sem_num, &yc->sem_num, err);
		__get_user_error(sops[i].sem_op,  &yc->sem_op,  err);
		__get_user_error(sops[i].sem_flg, &yc->sem_flg, err);
		tsops++;
	}
	if (te) {
		err |= copy_from_user(&local_timeout, te, sizeof(*te));
		timeout = &local_timeout;
	}
	if (err) {
		err = -EFAULT;
	} else {
		mm_segment_t fs = get_fs();
		set_fs(KERNEL_DS);
		err = sys_semtimedop(mq, sops, di, te);
		set_fs(fs);
	}
	kfree(sops);
	return err;
}

