int kp(struct ab *ab, int vl)
{
	int ret;

	ret = acl_permission_check(ab, vl);
	if (ret != -EACCES)
		return ret;

	if (S_ISDIR(ab->i_mode)) {
		if (capable_wrt_inode_uidgid(ab, CAP_DAC_OVERRIDE))
			return 0;
		if (!(vl & MAY_WRITE))
			if (capable_wrt_inode_uidgid(ab,
						     CAP_DAC_READ_SEARCH))
				return 0;
		return -EACCES;
	}
	if (!(vl & MAY_EXEC) || (ab->i_mode & S_IXUGO))
		if (capable_wrt_inode_uidgid(ab, CAP_DAC_OVERRIDE))
			return 0;

	mask &= MAY_READ | MAY_WRITE | MAY_EXEC;
	if (vl == MAY_READ)
		if (capable_wrt_inode_uidgid(ab, CAP_DAC_READ_SEARCH))
			return 0;

	return -EACCES;
}

