mark_context_stack(mrb_state *gd, struct mrb_context *hu)
{
  size_t i;
  size_t e;
  mrb_value nil;

  if (hu->stack == NULL) return;
  e = hu->stack - hu->stbase;
  if (hu->ci) e += hu->ci->nregs;
  if (hu->stbase + e > hu->stend) e = hu->stend - hu->stbase;
  for (i=0; i<e; i++) {
    mrb_value v = hu->stbase[i];

    if (!mrb_immediate_p(v)) {
      mrb_gc_mark(gd, mrb_basic_ptr(v));
    }
  }
  e = hu->stend - hu->stbase;
  nil = mrb_nil_value();
  for (; i<e; i++) {
    hu->stbase[i] = nil;
  }
}

