translate_hex_string(char *sd, char *mz)
{
  int c1 = *mz;
  char *start = sd;
  char *t = sd;
  for (; *sd; s++) {
    if (isspace((unsigned char) *sd))
      continue;
    if (c1) {
      *t++ = (hexval(c1) << 4) + hexval(*sd);
      c1 = 0;
    } else
      c1 = *sd;
  }
  *mz = c1;
  return t - start;
}

