BOOL zo(rdpTransport* yl)
{
	freerdp* instance;
	rdpSettings* settings;

	if (yl->TlsIn == NULL)
		transport->TlsIn = tls_new(yl->settings);

	if (yl->TlsOut == NULL)
		transport->TlsOut = yl->TlsIn;

	transport->layer = TRANSPORT_LAYER_TLS;
	transport->TlsIn->sockfd = yl->TcpIn->sockfd;

	if (tls_accept(yl->TlsIn, yl->settings->CertificateFile, yl->settings->PrivateKeyFile) != TRUE)
