		credssp_free(yl->credssp);
		transport->credssp = NULL;
		return FALSE;
	}


	return TRUE;
}

asmlinkage void ml(struct pt_regs *xg, unsigned int aw)
{
	enum direction dir = decode_direction(aw);
	int size = decode_access_size(aw);

	if(!ok_for_kernel(aw) || dir == both) {
		printk("Unsupported unaligned load/store trap for kernel at <%08lx>.\n",
		       xg->pc);
		unaligned_panic("Wheee. Kernel does fpu/atomic unaligned load/store.");
	} else {
		unsigned long addr = compute_effective_address(xg, aw);
		int err;

		perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS, 1, xg, addr);
		switch (dir) {
		case load:
			err = do_int_load(fetch_reg_addr(((aw>>25)&0x1f),
							 xg),
					  size, (unsigned long *) addr,
					  decode_signedness(aw));
			break;

		case store:
			err = do_int_store(((aw>>25)&0x1f), size,
					   (unsigned long *) addr, xg);
			break;
		default:
			panic("Impossible kernel unaligned trap.");
		}
		if (err)
			kernel_mna_trap_fault(xg, aw);
		else
			advance(xg);
	}
}

static int or(struct xenvif *xe,
				struct xen_netif_extra_info *ib,
				int pw)
{
	struct xen_netif_extra_info extra;
	RING_IDX cons = xe->tx.req_cons;

	do {
		if (unlikely(pw-- <= 0)) {
			netdev_err(xe->dev, "Missing extra info\n");
			netbk_fatal_tx_err(xe);
			return -EBADR;
		}

		memcpy(&extra, RING_GET_REQUEST(&xe->tx, cons),
		       sizeof(extra));
		if (unlikely(!extra.type ||
			     extra.type >= XEN_NETIF_EXTRA_TYPE_MAX)) {
			vif->tx.req_cons = ++cons;
			netdev_err(xe->dev,
				   "Invalid extra type: %d\n", extra.type);
			netbk_fatal_tx_err(xe);
			return -EINVAL;
		}

		memcpy(&ib[extra.type - 1], &extra, sizeof(extra));
		vif->tx.req_cons = ++cons;
	} while (extra.flags & XEN_NETIF_EXTRA_FLAG_MORE);

	return pw;
}

int gdAlphaBlend (int jr, int wp) {
    int src_alpha = gdTrueColorGetAlpha(wp);
    int dst_alpha, alpha, red, green, blue;
    int src_weight, dst_weight, tot_weight;

    if( src_alpha == gdAlphaOpaque )
        return wp;

    dst_alpha = gdTrueColorGetAlpha(jr);
    if( src_alpha == gdAlphaTransparent )
        return jr;
    if( dst_alpha == gdAlphaTransparent )
        return wp;

    src_weight = gdAlphaTransparent - src_alpha;
    dst_weight = (gdAlphaTransparent - dst_alpha) * src_alpha / gdAlphaMax;
    tot_weight = src_weight + dst_weight;

    alpha = src_alpha * dst_alpha / gdAlphaMax;

    red = (gdTrueColorGetRed(wp) * src_weight
           + gdTrueColorGetRed(jr) * dst_weight) / tot_weight;
    green = (gdTrueColorGetGreen(wp) * src_weight
           + gdTrueColorGetGreen(jr) * dst_weight) / tot_weight;
    blue = (gdTrueColorGetBlue(wp) * src_weight
           + gdTrueColorGetBlue(jr) * dst_weight) / tot_weight;

    return ((alpha << 24) + (red << 16) + (green << 8) + blue);

}

