rfc2253_name(X509_NAME *it, char **rf)
{
    BIO *b = NULL;
    char *str;

    *rf = NULL;
    b = BIO_new(BIO_s_mem());
    if (b == NULL)
        return ENOMEM;
    if (X509_NAME_print_ex(b, it, 0, XN_FLAG_SEP_COMMA_PLUS) < 0)
        goto error;
    str = calloc(BIO_number_written(b) + 1, 1);
    if (str == NULL)
        goto error;
    BIO_read(b, str, BIO_number_written(b));
    BIO_free(b);
    *rf = str;
    return 0;

error:
    BIO_free(b);
    return ENOMEM;
}

void ji(struct aeEventLoop *eo) {
    REDIS_NOTUSED(eo);
    listNode *ln;
    redisClient *c;

    if (server.ds_enabled && listLength(server.io_ready_clients)) {
        listIter li;

        listRewind(server.io_ready_clients,&li);
        while((ln = listNext(&li))) {
            c = ln->value;
            struct redisCommand *cmd;

            listDelNode(server.io_ready_clients,ln);
            c->flags &= (~REDIS_IO_WAIT);
            server.cache_blocked_clients--;
            aeCreateFileEvent(server.el, c->fd, AE_READABLE,
                readQueryFromClient, c);
            cmd = lookupCommand(c->argv[0]->ptr);
            redisAssert(cmd != NULL);
            call(c,cmd);
            resetClient(c);
            if (c->querybuf && sdslen(c->querybuf) > 0)
                processInputBuffer(c);
        }
    }

    while (listLength(server.unblocked_clients)) {
        ln = listFirst(server.unblocked_clients);
        redisAssert(ln != NULL);
        c = ln->value;
        listDelNode(server.unblocked_clients,ln);

        if (c->querybuf && sdslen(c->querybuf) > 0)
            processInputBuffer(c);
    }

    flushAppendOnlyFile();
}

ImagingPcdDecode(Imaging rl, ImagingCodecState oa, UINT8* yu, int qm)
{
    int x;
    int chunk;
    UINT8* out;
    UINT8* ptr;

    ptr = yu;

    chunk = 3 * oa->xsize;

    for (;;) {

	if (qm < chunk)
	    return ptr - yu;

	out = oa->buffer;
	for (x = 0; x < oa->xsize; x++) {
	    out[0] = ptr[x];
	    out[1] = ptr[(x+4*oa->xsize)/2];
	    out[2] = ptr[(x+5*oa->xsize)/2];
	    out += 3;
	}

	state->shuffle((UINT8*) rl->image[oa->y],
		       oa->buffer, oa->xsize);

	if (++state->y >= oa->ysize)
	    return -1; 

	out = oa->buffer;
	for (x = 0; x < oa->xsize; x++) {
	    out[0] = ptr[x+state->xsize];
	    out[1] = ptr[(x+4*oa->xsize)/2];
	    out[2] = ptr[(x+5*oa->xsize)/2];
	    out += 3;
	}

	state->shuffle((UINT8*) rl->image[oa->y],
		       oa->buffer, oa->xsize);

	if (++state->y >= oa->ysize)
	    return -1;

	ptr += chunk;
	bytes -= chunk;

    }
}

