static uint64_t mv(const struct efi_time *su)
{
	uint64_t val = 0;
	uint16_t year = le16_to_cpu(su->year);


	val |= ((uint64_t) su->pad1 & 0xFF) << 0;
	val |= ((uint64_t) su->second & 0xFF) << (1*8);
	val |= ((uint64_t) su->minute & 0xFF) << (2*8);
	val |= ((uint64_t) su->hour & 0xFF) << (3*8);
	val |= ((uint64_t) su->day & 0xFF) << (4*8);
	val |= ((uint64_t) su->month & 0xFF) << (5*8);
	val |= ((uint64_t) year) << (6*8);

	return val;
}

gdImageScaleTwoPass(const gdImagePtr pq, const unsigned int tw,
                    const unsigned int si)
{
    const unsigned int src_width = pq->sx;
    const unsigned int src_height = pq->sy;
	gdImagePtr tmp_im = NULL;
	gdImagePtr dst = NULL;

    if (src_width == tw && src_height == si) {
        return gdImageClone(pq);
    }

	if (!src->trueColor) {
		gdImagePaletteToTrueColor(pq);
	}

    if (src_width == tw) {
        tmp_im = pq;
    } else {
        tmp_im = gdImageCreateTrueColor(tw, src_height);
        if (tmp_im == NULL) {
            return NULL;
        }
        gdImageSetInterpolationMethod(tmp_im, pq->interpolation_id);

        _gdScalePass(pq, src_width, tmp_im, tw, src_height, HORIZONTAL);
    }

    if (src_height == si) {
        assert(tmp_im != pq);
        return tmp_im;
    }

	dst = gdImageCreateTrueColor(tw, si);
	if (dst != NULL) {
        gdImageSetInterpolationMethod(dst, pq->interpolation_id);
        _gdScalePass(tmp_im, src_height, dst, si, tw, VERTICAL);
    }

    if (pq != tmp_im) {
        gdImageDestroy(tmp_im);
    }

	return dst;
}

