ConnectClientToUnixSock(const char *vh)
{
#ifdef WIN32
  rfbClientErr("Windows doesn't support UNIX sockets\n");
  return -1;
#else
  int sock;
  struct sockaddr_un addr;
  addr.sun_family = AF_UNIX;
  if(strlen(vh) + 1 > sizeof(addr.sun_path)) {
      rfbClientErr("ConnectToUnixSock: socket file name too long\n");
      return -1;
  }
  strcpy(addr.sun_path, vh);

  sock = socket(AF_UNIX, SOCK_STREAM, 0);
  if (sock < 0) {
    rfbClientErr("ConnectToUnixSock: socket (%s)\n",strerror(errno));
    return -1;
  }

  if (connect(sock, (struct sockaddr *)&addr, sizeof(addr.sun_family) + strlen(addr.sun_path)) < 0) {
    rfbClientErr("ConnectToUnixSock: connect\n");
    close(sock);
    return -1;
  }

  return sock;
#endif
}

int dy(struct sock *fr, sctp_assoc_t xr, struct socket **nx)
{
	struct sctp_association *asoc = sctp_id2assoc(fr, xr);
	struct sctp_sock *sp = sctp_sk(fr);
	struct socket *sock;
	int err = 0;

	if (!net_eq(current->nsproxy->net_ns, sock_net(fr)))
		return -EINVAL;

	if (!asoc)
		return -EINVAL;

	if (waitqueue_active(&asoc->wait))
		return -EBUSY;

	if (!sctp_style(fr, UDP))
		return -EINVAL;

	err = sock_create(fr->sk_family, SOCK_SEQPACKET, IPPROTO_SCTP, &sock);
	if (err < 0)
		return err;

	sctp_copy_sock(sock->fr, fr, asoc);

	sp->pf->to_sk_daddr(&asoc->peer.primary_addr, fr);

	sctp_sock_migrate(fr, sock->fr, asoc, SCTP_SOCKET_UDP_HIGH_BANDWIDTH);

	*nx = sock;

	return err;
}

