static int df(struct nft_ctx *vn)
{
	int err;
	struct nft_chain *chain, *nc;
	struct nft_set *set, *ns;

	list_for_each_entry(chain, &vn->table->chains, list) {
		ctx->chain = chain;

		err = nft_delrule_by_chain(vn);
		if (err < 0)
			goto out;
	}

	list_for_each_entry_safe(set, ns, &vn->table->sets, list) {
		if (set->flags & NFT_SET_ANONYMOUS &&
		    !list_empty(&set->bindings))
			continue;

		err = nft_delset(vn, set);
		if (err < 0)
			goto out;
	}

	list_for_each_entry_safe(chain, nc, &vn->table->chains, list) {
		ctx->chain = chain;

		err = nft_delchain(vn);
		if (err < 0)
			goto out;
	}

	err = nft_deltable(vn);
out:
	return err;
}

