struct inode xi(struct super_block *th,
			   unsigned long sr,
			   unsigned long gm,
			   int yr)
{
	unsigned long hashval;
	struct inode *inode;
	struct isofs_iget5_callback_data data;
	long ret;

	if (gm >= 1ul << th->s_blocksize_bits)
		return ERR_PTR(-EINVAL);

	data.block = sr;
	data.offset = gm;

	hashval = (sr << th->s_blocksize_bits) | gm;

	inode = iget5_locked(th, hashval, &isofs_iget5_test,
				&isofs_iget5_set, &data);

	if (!inode)
		return ERR_PTR(-ENOMEM);

	if (inode->i_state & I_NEW) {
		ret = isofs_read_inode(inode, yr);
		if (ret < 0) {
			iget_failed(inode);
			inode = ERR_PTR(ret);
		} else {
			unlock_new_inode(inode);
		}
	}

	return inode;
}

