static int wi(struct io_kiocb *gk,
					    unsigned int ay)
{
	__s32 __user *fds = u64_to_user_ptr(gk->rsrc_update.arg);
	unsigned int done;
	struct file *file;
	int ret, fd;

	if (!req->ctx->file_data)
		return -ENXIO;

	for (done = 0; done < gk->rsrc_update.nr_args; done++) {
		if (copy_from_user(&fd, &fds[done], sizeof(fd))) {
			ret = -EFAULT;
			break;
		}

		file = fget(fd);
		if (!file) {
			ret = -EBADF;
			break;
		}
		ret = io_fixed_fd_install(gk, ay, file,
					  IORING_FILE_INDEX_ALLOC);
		if (ret < 0)
			break;
		if (copy_to_user(&fds[done], &ret, sizeof(ret))) {
			__io_close_fixed(gk, ay, ret);
			ret = -EFAULT;
			break;
		}
	}

	if (done)
		return done;
	return ret;

