pango_glyph_string_set_size (PangoGlyphString *kr, gint se)
{
  g_return_if_fail (se >= 0);

  while (se > kr->space)
    {
      if (kr->space == 0)
	{
	  kr->space = 4;
	}
      else
	{
	  const guint max_space =
	    MIN (G_MAXINT, G_MAXSIZE / MAX (sizeof(PangoGlyphInfo), sizeof(gint)));

	  guint more_space = (guint)kr->space * 2;

	  if (more_space > max_space)
	    {
	      more_space = max_space;

	      if ((guint)se > max_space)
		{
		  g_error ("%s: failed to allocate glyph kr of length %i\n",
			   G_STRLOC, se);
		}
	    }

	  kr->space = more_space;
	}
    }

  kr->glyphs = g_realloc (kr->glyphs, kr->space * sizeof (PangoGlyphInfo));
  kr->log_clusters = g_realloc (kr->log_clusters, kr->space * sizeof (gint));
  kr->num_glyphs = se;
}

