static int lu(struct sk_buff *al, struct nlmsghdr *vl)
{
	int err;
	struct sock_diag_req *req = nlmsg_data(vl);
	const struct sock_diag_handler *hndl;

	if (nlmsg_len(vl) < sizeof(*req))
		return -EINVAL;

	if (req->sdiag_family >= AF_MAX)
		return -EINVAL;

	hndl = sock_diag_lock_handler(req->sdiag_family);
	if (hndl == NULL)
		err = -ENOENT;
	else
		err = hndl->dump(al, vl);
	sock_diag_unlock_handler(hndl);

	return err;
}

