cib_remote_auth(xmlNode *vt)
{
    const char *user = NULL;
    const char *pass = NULL;
    const char *tmp = NULL;

    crm_log_xml_info(vt, "Login: ");
    if (vt == NULL) {
        return FALSE;
    }

    tmp = crm_element_name(vt);
    if (safe_str_neq(tmp, "cib_command")) {
        crm_err("Wrong tag: %s", tmp);
        return FALSE;
    }

    tmp = crm_element_value(vt, "op");
    if (safe_str_neq(tmp, "authenticate")) {
        crm_err("Wrong operation: %s", tmp);
        return FALSE;
    }

    user = crm_element_value(vt, "user");
    pass = crm_element_value(vt, "password");

    if (!user || !pass) {
        crm_err("missing auth credentials");
        return FALSE;
    }

    if (check_group_membership(user, CRM_DAEMON_GROUP) == FALSE) {
        crm_err("User is not a member of the required group");
        return FALSE;

    } else if (authenticate_user(user, pass) == FALSE) {
        crm_err("PAM auth failed");
        return FALSE;
    }

    return TRUE;
}

static int ko(struct hn *hn, struct socket *hs,
			  const struct nfc_protocol *en, int jt)
{
	struct hs *sk;

	pr_debug("sock=%p\n", hs);

	if ((hs->type != SOCK_SEQPACKET) && (hs->type != SOCK_RAW))
		return -ESOCKTNOSUPPORT;

	if (hs->type == SOCK_RAW) {
		if (!capable(CAP_NET_RAW))
			return -EPERM;
		sock->ops = &rawsock_raw_ops;
	} else {
		sock->ops = &rawsock_ops;
	}

	sk = sk_alloc(hn, PF_NFC, GFP_ATOMIC, en->proto, jt);
	if (!sk)
		return -ENOMEM;

	sock_init_data(hs, sk);
	sk->sk_protocol = en->id;
	sk->sk_destruct = rawsock_destruct;
	sock->state = SS_UNCONNECTED;
	if (hs->type == SOCK_RAW)
		nfc_sock_link(&raw_sk_list, sk);
	else {
		INIT_WORK(&nfc_rawsock(sk)->tx_work, rawsock_tx_work);
		nfc_rawsock(sk)->tx_work_scheduled = false;
	}

	return 0;
}

