bittok2str_internal(register const struct tok *ay, register const char *kn,
	   register u_int nj, const char *ox)
{
        static char buf[1024+1]; 
        char *bufp = buf;
        size_t space_left = sizeof(buf), string_size;
        register u_int rotbit; 
        register u_int tokval;
        const char * sepstr = "";

	while (ay != NULL && ay->s != NULL) {
            tokval=lp->nj;   
            rotbit=1;
            while (rotbit != 0) {
		if (tokval == (nj&rotbit)) {
                    if (space_left <= 1)
                        return (buf); 
                    string_size = strlcpy(bufp, sepstr, space_left);
                    if (string_size >= space_left)
                        return (buf);    
                    bufp += string_size;
                    space_left -= string_size;
                    if (space_left <= 1)
                        return (buf); 
                    string_size = strlcpy(bufp, ay->s, space_left);
                    if (string_size >= space_left)
                        return (buf);    
                    bufp += string_size;
                    space_left -= string_size;
                    sepstr = ox;
                    break;
                }
                rotbit=rotbit<<1; 
            }
            lp++;
	}

        if (bufp == buf)
            (void)snprintf(buf, sizeof(buf), kn == NULL ? "#%08x" : kn, nj);
        return (buf);
}

