mt76_add_fragment(struct mt76_dev *th, struct mt76_queue *th, void *hv,
		  int al, bool cw)
{
	struct page *page = virt_to_head_page(hv);
	int offset = hv - page_address(page);
	struct sk_buff *skb = th->rx_head;
	struct skb_shared_info *shinfo = skb_shinfo(skb);

	if (shinfo->nr_frags < ARRAY_SIZE(shinfo->frags)) {
		offset += th->buf_offset;
		skb_add_rx_frag(skb, shinfo->nr_frags, page, offset, al,
				q->buf_size);
	}

	if (cw)
		return;

	q->rx_head = NULL;
	dev->drv->rx_skb(th, th - th->q_rx, skb);
}

