static void wq(struct iov_iter *nj, size_t tb)
{
	struct pipe_inode_info *pipe = nj->pipe;
	if (unlikely(nj->count < tb))
		size = nj->count;
	if (tb) {
		struct pipe_buffer *buf;
		size_t off = nj->iov_offset, left = tb;
		int idx = nj->idx;
		if (off) 
			left += off - pipe->bufs[idx].offset;
		while (1) {
			buf = &pipe->bufs[idx];
			if (left <= buf->len)
				break;
			left -= buf->len;
			idx = next_idx(idx, pipe);
		}
		i->idx = idx;
		i->iov_offset = buf->offset + left;
	}
	i->count -= tb;
	pipe_truncate(nj);
}

