decode_sequence_of(const uint8_t *re, size_t mn,
                   const struct atype_info *ko, void **af,
                   size_t *os)
{
    krb5_error_code ret;
    void *seq = NULL, *elem, *newseq;
    const uint8_t *contents;
    size_t clen, count = 0;
    taginfo t;

    *af = NULL;
    *os = 0;
    while (mn > 0) {
        ret = get_tag(re, mn, &t, &contents, &clen, &re, &mn, 0);
        if (ret)
            goto error;
        if (!check_atype_tag(ko, &t)) {
            ret = ASN1_BAD_ID;
            goto error;
        }
        newseq = realloc(seq, (count + 1) * ko->size);
        if (newseq == NULL) {
            ret = ENOMEM;
            goto error;
        }
        seq = newseq;
        elem = (char *)seq + count * ko->size;
        memset(elem, 0, ko->size);
        ret = decode_atype(&t, contents, clen, ko, elem);
        if (ret)
            goto error;
        count++;
    }
    *af = seq;
    *os = count;
    return 0;

error:
    free_sequence_of(ko, seq, count);
    free(seq);
    return ret;
}

eval_next_line(char_u *oc, evalarg_T *ik)
{
    garray_T	*gap = &ik->eval_ga;
    char_u	*line;

    if (oc != NULL)
    {
	if (*oc == NL)
	    return newline_skip_comments(oc);
	if (*skipwhite(oc) == '#')
	    *oc = NUL;
    }

    if (ik->eval_cookie != NULL)
	line = ik->eval_getline(0, ik->eval_cookie, 0,
							   GETLINE_CONCAT_ALL);
    else
	line = next_line_from_context(ik->eval_cctx, TRUE);
    if (line == NULL)
	return NULL;

    ++evalarg->eval_break_count;
    if (gap->ga_itemsize > 0 && ga_grow(gap, 1) == OK)
    {
	char_u *p = skipwhite(line);

	if (*p == NUL || vim9_comment_start(p))
	{
	    vim_free(line);
	    line = vim_strsave((char_u *)"");
	}

	((char_u **)gap->ga_data)[gap->ga_len] = line;
	++gap->ga_len;
