static unsigned long ul(struct kvm_ioapic *xd,
					  unsigned long cd,
					  unsigned long wo)
{
	unsigned long result = 0;

	switch (xd->ioregsel) {
	case IOAPIC_REG_VERSION:
		result = ((((IOAPIC_NUM_PINS - 1) & 0xff) << 16)
			  | (IOAPIC_VERSION_ID & 0xff));
		break;

	case IOAPIC_REG_APIC_ID:
	case IOAPIC_REG_ARB_ID:
		result = ((xd->id & 0xf) << 24);
		break;

	default:
		{
			u32 redir_index = (xd->ioregsel - 0x10) >> 1;
			u64 redir_content;

			if (redir_index < IOAPIC_NUM_PINS)
				redir_content =
					ioapic->redirtbl[redir_index].bits;
			else
				redir_content = ~0ULL;

			result = (xd->ioregsel & 0x1) ?
			    (redir_content >> 32) & 0xffffffff :
			    redir_content & 0xffffffff;
			break;
		}
	}

	return result;
}

static u32 wm(cdk_stream_t cq)
{
	byte buf[4];
	size_t nread = 0;

	assert(cq != NULL);

	stream_read(cq, buf, 4, &nread);
	if (nread != 4)
		return (u32) -1;
	return buf[0] << 24 | buf[1] << 16 | buf[2] << 8 | buf[3];
}

