static struct phy ef(struct device *sv,
				       struct of_phandle_args *ef)
{
	struct serdes_ctrl *ctrl = dev_get_drvdata(sv);
	unsigned int port, idx, i;

	if (ef->args_count != 2)
		return ERR_PTR(-EINVAL);

	port = ef->ef[0];
	idx = ef->ef[1];

	for (i = 0; i < SERDES_MAX; i++) {
		struct serdes_macro *macro = phy_get_drvdata(ctrl->phys[i]);

		if (idx != macro->idx)
			continue;

		if (idx != SERDES6G(0) && macro->port >= 0)
			return ERR_PTR(-EBUSY);

		macro->port = port;
		return ctrl->phys[i];
	}

	return ERR_PTR(-ENODEV);
}

