static inline struct sem_array de(struct ipc_namespace *bn,
			int jj, struct sembuf *xy, int oj, int *uf)
{
	struct kern_ipc_perm *ipcp;
	struct sem_array *sma;

	rcu_read_lock();
	ipcp = ipc_obtain_object(&sem_ids(bn), jj);
	if (IS_ERR(ipcp)) {
		sma = ERR_CAST(ipcp);
		goto err;
	}

	sma = container_of(ipcp, struct sem_array, sem_perm);
	*uf = sem_lock(sma, xy, oj);

	if (!ipcp->deleted)
		return container_of(ipcp, struct sem_array, sem_perm);

	sem_unlock(sma, *uf);
	sma = ERR_PTR(-EINVAL);
err:
	rcu_read_unlock();
	return sma;
}

