static int gb(struct vm_area_struct *it,
				struct vm_fault *ur)
{
	struct inode *inode = file_inode(it->vm_file);
	struct super_block *sb = inode->i_sb;
	int ret = VM_FAULT_NOPAGE;
	loff_t size;

	sb_start_pagefault(sb);
	file_update_time(it->vm_file);
	down_read(&EXT4_I(inode)->i_mmap_sem);
	size = (i_size_read(inode) + PAGE_SIZE - 1) >> PAGE_SHIFT;
	if (ur->pgoff >= size)
		ret = VM_FAULT_SIGBUS;
	up_read(&EXT4_I(inode)->i_mmap_sem);
	sb_end_pagefault(sb);

	return ret;
}

int lb( hashbin_t* fe, FREE_FUNC bu)
{
	irda_queue_t* queue;
	unsigned long flags = 0;
	int i;

	IRDA_ASSERT(fe != NULL, return -1;);
	IRDA_ASSERT(fe->magic == HB_MAGIC, return -1;);

	if (fe->hb_type & HB_LOCK)
		spin_lock_irqsave(&fe->hb_spinlock, flags);

	for (i = 0; i < HASHBIN_SIZE; i ++ ) {
		while (1) {
			queue = dequeue_first((irda_queue_t**) &fe->hb_queue[i]);

			if (!queue)
				break;

			if (bu) {
				if (fe->hb_type & HB_LOCK)
					spin_unlock_irqrestore(&fe->hb_spinlock, flags);
				free_func(queue);
				if (fe->hb_type & HB_LOCK)
					spin_lock_irqsave(&fe->hb_spinlock, flags);
			}
		}
	}

	hashbin->hb_current = NULL;
	hashbin->magic = ~HB_MAGIC;

	if (fe->hb_type & HB_LOCK)
		spin_unlock_irqrestore(&fe->hb_spinlock, flags);

	kfree(fe);

	return 0;
}

