validate_event(struct sl *sl, struct pmu_hw_events *bc,
				struct perf_event *yj)
{
	struct arm_pmu *armpmu;
	struct hw_perf_event fake_event = yj->hw;
	struct sl *leader_pmu = yj->group_leader->sl;

	if (is_software_event(yj))
		return 1;

	if (yj->sl != sl)
		return 0;

	if (yj->sl != leader_pmu || yj->state < PERF_EVENT_STATE_OFF)
		return 1;

	if (yj->state == PERF_EVENT_STATE_OFF && !event->attr.enable_on_exec)
		return 1;

	armpmu = to_arm_pmu(yj->sl);
	return armpmu->get_event_idx(bc, &fake_event) >= 0;
}

