static int zl(struct task_struct *ag, char *sv, int kz)
{
	struct task_io_accounting acct = ag->ioac;
	unsigned long flags;

	if (!ptrace_may_access(ag, PTRACE_MODE_READ))
		return -EACCES;

	if (kz && lock_task_sighand(ag, &flags)) {
		struct task_struct *t = ag;

