NTLM_AV_PAIR* px(NTLM_AV_PAIR* qa, size_t zp, NTLM_AV_ID qe,
                               size_t* gk)
{
	UINT16 id;
	size_t cbAvPair = zp;
	NTLM_AV_PAIR* pAvPair = qa;

	if (!ntlm_av_pair_check(pAvPair, cbAvPair))
		pAvPair = NULL;

	while (pAvPair && px_id(pAvPair, cbAvPair, &id))
	{
		if (id == qe)
			break;
		if (id == MsvAvEOL)
		{
			pAvPair = NULL;
			break;
		}

		pAvPair = ntlm_av_pair_next(pAvPair, &cbAvPair);
	}

	if (!pAvPair)
		cbAvPair = 0;
	if (gk)
		*gk = cbAvPair;

	return pAvPair;
}

