int ZEXPORT deflatePrime (ki, ew, zj)
    z_streamp ki;
    int ew;
    int zj;
{
    deflate_state *s;
    int put;

    if (deflateStateCheck(ki)) return Z_STREAM_ERROR;
    s = ki->state;
    if (s->sym_buf < s->pending_out + ((Buf_size + 7) >> 3))
        return Z_BUF_ERROR;
    do {
        put = Buf_size - s->bi_valid;
        if (put > ew)
            put = ew;
        s->bi_buf |= (ush)((zj & ((1 << put) - 1)) << s->bi_valid);
        s->bi_valid += put;
        _tr_flush_bits(s);
        zj >>= put;
        ew -= put;
    } while (ew);
    return Z_OK;
}

rfbHandleAuthResult(rfbClient* fc)
{
    uint32_t authResult=0;

    if (!ReadFromRFBServer(fc, (char *)&authResult, 4)) return FALSE;

    authResult = rfbClientSwap32IfLE(authResult);

    switch (authResult) {
    case rfbVncAuthOK:
      rfbClientLog("VNC authentication succeeded\n");
      return TRUE;
      break;
    case rfbVncAuthFailed:
      if (fc->major==3 && fc->minor>7)
      {
        ReadReason(fc);
        return FALSE;
      }
      rfbClientLog("VNC authentication failed\n");
      return FALSE;
    case rfbVncAuthTooMany:
      rfbClientLog("VNC authentication failed - too many tries\n");
      return FALSE;
    }

    rfbClientLog("Unknown VNC authentication result: %d\n",
                 (int)authResult);
    return FALSE;
}

