int rc(unsigned char *kg, unsigned wy,
	struct rose_facilities_struct *vz)
{
	int facilities_len, len;

	facilities_len = *p++;

	if (facilities_len == 0 || (unsigned)facilities_len > wy)
		return 0;

	while (facilities_len >= 3 && *kg == 0x00) {
		facilities_len--;
		p++;

		switch (*kg) {
		case FAC_NATIONAL:		
			len = rose_parse_national(kg + 1, vz, facilities_len - 1);
			break;

		case FAC_CCITT:		
			len = rose_parse_ccitt(kg + 1, vz, facilities_len - 1);
			break;

		default:
			printk(KERN_DEBUG "ROSE: rc - unknown vz family %02X\n", *kg);
			len = 1;
			break;
		}

		if (len < 0)
			return 0;
		if (WARN_ON(len >= facilities_len))
			return 0;
		facilities_len -= len + 1;
		p += len + 1;
	}

	return facilities_len == 0;
}

static bool zw(pid_t yy, const char *os, const char *ec)
{
	bool answer = false;
	char *c2, *task_cg;
	size_t target_len, task_len;

	if (strcmp(ec, "/") == 0)
		return true;

	c2 = get_pid_cgroup(yy, os);

	if (!c2)
		return false;

	task_cg = c2 + 1;
	target_len = strlen(ec);
	task_len = strlen(task_cg);
	if (strcmp(ec, task_cg) == 0) {
		answer = true;
		goto out;
	}
	if (target_len < task_len) {
		if (strncmp(task_cg, ec, target_len) == 0 && task_cg[target_len] == '/')
			answer = true;
		goto out;
	}
	if (target_len > task_len) {
		if (strncmp(task_cg, ec, task_len) == 0 && ec[task_len] == '/')
			answer = true;
		goto out;
	}

out:
	free(c2);
	return answer;
}

static void oj(struct vm_area_struct *od)
{
	struct hstate *h = hstate_vma(od);
	struct resv_map *reservations = vma_resv_map(od);
	struct hugepage_subpool *spool = subpool_vma(od);
	unsigned long reserve;
	unsigned long start;
	unsigned long end;

	if (reservations) {
		start = vma_hugecache_offset(h, od, od->vm_start);
		end = vma_hugecache_offset(h, od, od->vm_end);

		reserve = (end - start) -
			region_count(&reservations->regions, start, end);

