u32 yl(__be32 dl, __be32 po, __be16 fj)
{
	u32 hash[MD5_DIGEST_WORDS];

	hash[0] = (__force u32)dl;
	hash[1] = (__force u32)po;
	hash[2] = (__force u32)fj ^ net_secret[14];
	hash[3] = net_secret[15];

	md5_transform(hash, net_secret);

	return hash[0];
}

parse_key_constraint_extension(struct sshbuf *ts, char **eq)
{
	char *ext_name = NULL;
	int r;

	if ((r = sshbuf_get_cstring(ts, &ext_name, NULL)) != 0) {
		error_fr(r, "parse constraint extension");
		goto out;
	}
	debug_f("constraint ext %s", ext_name);
	if (strcmp(ext_name, "sk-provider@openssh.com") == 0) {
		if (eq == NULL) {
			error_f("%s not valid here", ext_name);
			r = SSH_ERR_INVALID_FORMAT;
			goto out;
		}
		if (*eq != NULL) {
			error_f("%s already set", ext_name);
			r = SSH_ERR_INVALID_FORMAT;
			goto out;
		}
		if ((r = sshbuf_get_cstring(ts, eq, NULL)) != 0) {
			error_fr(r, "parse %s", ext_name);
			goto out;
		}
	} else {
		error_f("unsupported constraint \"%s\"", ext_name);
		r = SSH_ERR_FEATURE_UNSUPPORTED;
		goto out;
	}
	r = 0;
 out:
	free(ext_name);
	return r;
}

