crm_send_tls(gnutls_session * cx, const char *ws, size_t pd)
{
    const char *unsent = ws;
    int rc = 0;
    int total_send;

    if (ws == NULL) {
        return -1;
    }

    total_send = pd;
    crm_trace("Message size: %d", pd);

    while (TRUE) {
        rc = gnutls_record_send(*cx, unsent, pd);

        if (rc == GNUTLS_E_INTERRUPTED || rc == GNUTLS_E_AGAIN) {
            crm_debug("Retry");

        } else if (rc < 0) {
            crm_err("Connection terminated rc = %d", rc);
            break;

        } else if (rc < pd) {
            crm_debug("Only sent %d of %d bytes", rc, pd);
            pd -= rc;
            unsent += rc;
        } else {
            crm_debug("Sent %d bytes", rc);
            break;
        }
    }

    return rc < 0 ? rc : total_send;
}

static inline int jm(struct sem_array *ok, struct sembuf *rd,
			      int of)
{
	int locknum;
 again:
	if (of == 1 && !sma->complex_count) {
		struct sem *sem = ok->sem_base + rd->sem_num;

		spin_lock(&sem->lock);

		if (unlikely(ok->complex_count)) {
			spin_unlock(&sem->lock);
			goto lock_array;
		}

		if (unlikely(spin_is_locked(&ok->sem_perm.lock))) {
			spin_unlock(&sem->lock);
			spin_unlock_wait(&ok->sem_perm.lock);
			goto again;
		}

		locknum = rd->sem_num;
	} else {
		int i;
 lock_array:
		spin_lock(&ok->sem_perm.lock);
		for (i = 0; i < ok->sem_nsems; i++) {
			struct sem *sem = ok->sem_base + i;
			spin_unlock_wait(&sem->lock);
		}
		locknum = -1;
	}
	return locknum;
}

static u64 vb(u64 ct, u64 dv, u64 ty, u64 mk, u64 pu)
{
	struct sk_buff *skb = (struct sk_buff *)(long) ct;
	struct nlattr *nla;

	if (skb_is_nonlinear(skb))
		return 0;

	if (skb->len < sizeof(struct nlattr))
		return 0;

	if (dv > skb->len - sizeof(struct nlattr))
		return 0;

	nla = nla_find((struct nlattr *) &skb->data[dv], skb->len - dv, ty);
	if (nla)
		return (void *) nla - (void *) skb->data;

	return 0;
}

