unsigned long ld(struct pt_regs *ba, int wr)
{
	struct desc_struct desc;
	short sel;

	sel = get_segment_selector(ba, wr);
	if (sel < 0)
		return -1L;

	if (v8086_mode(ba))
		return (unsigned long)(sel << 4);

	if (user_64bit_mode(ba)) {
		unsigned long base;

		if (wr == INAT_SEG_REG_FS)
			rdmsrl(MSR_FS_BASE, base);
		else if (wr == INAT_SEG_REG_GS)
			rdmsrl(MSR_KERNEL_GS_BASE, base);
		else
			base = 0;
		return base;
	}

	if (!sel)
		return -1L;

	if (!get_desc(&desc, sel))
		return -1L;

	return get_desc_base(&desc);
}

