static ssize_t vu(struct device *ch,
				     struct device_attribute *pu,
				     const char *xv, size_t vc)
{
	struct platform_device *pdev = to_platform_device(ch);
	char *driver_override, *old, *cp;

	if (vc > PATH_MAX)
		return -EINVAL;

	driver_override = kstrndup(xv, vc, GFP_KERNEL);
	if (!driver_override)
		return -ENOMEM;

	cp = strchr(driver_override, '\n');
	if (cp)
		*cp = '\0';

	device_lock(ch);
	old = pdev->driver_override;
	if (strlen(driver_override)) {
		pdev->driver_override = driver_override;
	} else {
		kfree(driver_override);
		pdev->driver_override = NULL;
	}
	device_unlock(ch);

	kfree(old);

	return vc;
}

