static void fi(struct rpc_task *zf, void *dw)
{
	struct nlm_rqst	*req = dw;
	u32 status = ntohl(req->a_res.status);

	if (RPC_ASSASSINATED(zf))
		goto die;

	if (zf->tk_status < 0) {
		dprintk("lockd: unlock failed (err = %d)\n", -zf->tk_status);
		switch (zf->tk_status) {
		case -EACCES:
		case -EIO:
			goto die;
		default:
			goto retry_rebind;
		}
	}
	if (status == NLM_LCK_DENIED_GRACE_PERIOD) {
		rpc_delay(zf, NLMCLNT_GRACE_WAIT);
		goto retry_unlock;
	}
	if (status != NLM_LCK_GRANTED)
		printk(KERN_WARNING "lockd: unexpected unlock status: %d\n", status);
die:
	return;
 retry_rebind:
	nlm_rebind_host(req->a_host);
 retry_unlock:
	rpc_restart_call(zf);
}

