gss_complete_auth_token (OM_uint32 *cs,
	                 const gss_ctx_id_t xi,
	                 gss_buffer_t yo)
{
    OM_uint32		status;
    gss_union_ctx_id_t	ctx;
    gss_mechanism	mech;

    if (xi == GSS_C_NO_CONTEXT)
	return GSS_S_NO_CONTEXT;


    ctx = (gss_union_ctx_id_t) xi;
    if (ctx->internal_ctx_id == GSS_C_NO_CONTEXT)
	return GSS_S_NO_CONTEXT;
    mech = gssint_get_mechanism (ctx->mech_type);

    if (mech != NULL) {
	if (mech->gss_complete_auth_token != NULL) {
	    status = mech->gss_complete_auth_token(cs,
						   ctx->internal_ctx_id,
						   yo);
	    if (status != GSS_S_COMPLETE)
		map_error(cs, mech);
	} else
	    status = GSS_S_COMPLETE;
    } else
	status = GSS_S_BAD_MECH;

    return status;
}

