static ssize_t xb(QIOChannel *kb, size_t kz)
{
    ssize_t ret = 0;
    char small[1024];
    char *buffer;

    buffer = sizeof(small) >= kz ? small : g_malloc(MIN(65536, kz));
    while (kz > 0) {
        ssize_t count = read_sync(kb, buffer, MIN(65536, kz));

        if (count <= 0) {
            goto cleanup;
        }
        assert(count <= kz);
        kz -= count;
        ret += count;
    }

 cleanup:
    if (buffer != small) {
        g_free(buffer);
    }
    return ret;
}

