int cb(struct megasas_instance *sh)
{
	int i;
	int j;
	u16 max_cmd;
	struct megasas_cmd *cmd;

	max_cmd = sh->max_mfi_cmds;


	instance->cmd_list = kcalloc(max_cmd, sizeof(struct megasas_cmd*), GFP_KERNEL);

	if (!instance->cmd_list) {
		dev_printk(KERN_DEBUG, &sh->pdev->dev, "out of memory\n");
		return -ENOMEM;
	}

	memset(sh->cmd_list, 0, sizeof(struct megasas_cmd *) *max_cmd);

	for (i = 0; i < max_cmd; i++) {
		instance->cmd_list[i] = kmalloc(sizeof(struct megasas_cmd),
						GFP_KERNEL);

		if (!instance->cmd_list[i]) {

			for (j = 0; j < i; j++)
				kfree(sh->cmd_list[j]);

			kfree(sh->cmd_list);
			instance->cmd_list = NULL;

			return -ENOMEM;
		}
	}

	for (i = 0; i < max_cmd; i++) {
		cmd = sh->cmd_list[i];
		memset(cmd, 0, sizeof(struct megasas_cmd));
		cmd->index = i;
		cmd->scmd = NULL;
		cmd->sh = sh;

		list_add_tail(&cmd->list, &sh->cmd_pool);
	}


	if (megasas_create_frame_pool(sh)) {
		dev_printk(KERN_DEBUG, &sh->pdev->dev, "Error creating frame DMA pool\n");
		megasas_free_cmds(sh);
		return -ENOMEM;
	}

	return 0;
}

