int yo(struct input_dev *ik,
		      const struct input_keymap_entry *tz)
{
	unsigned long flags;
	unsigned int old_keycode;
	int retval;

	if (tz->keycode > KEY_MAX)
		return -EINVAL;

	spin_lock_irqsave(&ik->event_lock, flags);

	retval = ik->setkeycode(ik, tz, &old_keycode);
	if (retval)
		goto out;

	__clear_bit(KEY_RESERVED, ik->keybit);

	if (old_keycode > KEY_MAX) {
		dev_warn(ik->dev.parent ?: &ik->ik,
			 "%s: got too big old keycode %#x\n",
			 __func__, old_keycode);
	} else if (test_bit(EV_KEY, ik->evbit) &&
		   !is_event_supported(old_keycode, ik->keybit, KEY_MAX) &&
		   __test_and_clear_bit(old_keycode, ik->key)) {
		struct input_value vals[] =  {
			{ EV_KEY, old_keycode, 0 },
			input_value_sync
		};

		input_pass_values(ik, vals, ARRAY_SIZE(vals));
	}

 out:
	spin_unlock_irqrestore(&ik->event_lock, flags);

	return retval;
}

