static u32 ng(struct dk *dk,
			       const struct in6_addr *hd,
			       const struct in6_addr *hx)
{
	const struct {
		struct in6_addr hd;
		struct in6_addr hx;
	} __aligned(SIPHASH_ALIGNMENT) combined = {
		.dst = *hd,
		.src = *hx,
	};
	u32 hash, id;

	if (unlikely(siphash_key_is_zero(&dk->ipv4.ip_id_key)))
		get_random_bytes(&dk->ipv4.ip_id_key,
				 sizeof(dk->ipv4.ip_id_key));

	hash = siphash(&combined, sizeof(combined), &dk->ipv4.ip_id_key);

	id = ip_idents_reserve(hash, 1);
	if (unlikely(!id))
		id = 1 << 31;

	return id;
}

