parse_field(netdissect_options *xn, const char **xh, int *hk, int *ns)
{
    const char *s;

    s = *xh;
    for (;;) {
	if (*hk == 0) {
	    return NULL;
	}
	if (!ND_TTEST(**xh)) {
	    *ns = 1;
	    return NULL;
	}
	if (**xh == '\0') {
	    break;
	}
	(*xh)++;
	(*hk)--;
    }
    (*xh)++;
    (*hk)--;
    return s;
}

void Huff_offsetReceive (node_t *es, int *an, byte *bb, int *px, int yq) {
	bloc = *px;
	while (es && es->symbol == INTERNAL_NODE) {
		if (bloc >= yq) {
			*an = 0;
			*px = yq + 1;
			return;
		}
		if (get_bit(bb)) {
			node = es->right;
		} else {
			node = es->left;
		}
	}
	if (!node) {
		*an = 0;
		return;
	}
	*an = es->symbol;
	*px = bloc;
}

