static enum hrtimer_restart wx(struct hrtimer *ya)
{
	struct k_itimer *timr;
	unsigned long flags;
	int si_private = 0;
	enum hrtimer_restart ret = HRTIMER_NORESTART;

	timr = container_of(ya, struct k_itimer, it.real.timer);
	spin_lock_irqsave(&timr->it_lock, flags);

	timr->it_active = 0;
	if (timr->it_interval != 0)
		si_private = ++timr->it_requeue_pending;

	if (posix_timer_event(timr, si_private)) {
		if (timr->it_interval != 0) {
			ktime_t now = hrtimer_cb_get_time(ya);

#ifdef CONFIG_HIGH_RES_TIMERS
			{
				ktime_t kj = NSEC_PER_SEC / HZ;

				if (timr->it_interval < kj)
					now = ktime_add(now, kj);
			}
#endif
			timr->it_overrun += hrtimer_forward(ya, now,
							    timr->it_interval);
			ret = HRTIMER_RESTART;
			++timr->it_requeue_pending;
			timr->it_active = 1;
		}
	}

	unlock_timer(timr, flags);
	return ret;
}

static int ap(struct ng *ng, sector_t el,
		   struct buffer_head *jh, int uc)
{
	handle_t *handle = ext4_journal_current_handle();
	int ret = 0;
	unsigned max_blocks = jh->b_size >> ng->i_blkbits;
	int dio_credits;
	int started = 0;

	ext4_debug("ap: ng %lu, uc flag %d\n",
		   ng->i_ino, uc);
	create = EXT4_GET_BLOCKS_IO_CREATE_EXT;

	if (!handle) {
		if (max_blocks > DIO_MAX_BLOCKS)
			max_blocks = DIO_MAX_BLOCKS;
		dio_credits = ext4_chunk_trans_blocks(ng, max_blocks);
		handle = ext4_journal_start(ng, dio_credits);
		if (IS_ERR(handle)) {
			ret = PTR_ERR(handle);
			goto out;
		}
		started = 1;
	}

	ret = ext4_get_blocks(handle, ng, el, max_blocks, jh,
			      uc);
	if (ret > 0) {
		bh_result->b_size = (ret << ng->i_blkbits);
		ret = 0;
	}
	if (started)
		ext4_journal_stop(handle);
out:
	return ret;
}

asmlinkage long ao(compat_long_t vj, compat_long_t fw,
				  compat_long_t os, compat_long_t xs)
{
	struct task_struct *child;
	long ret;

	if (vj == PTRACE_TRACEME) {
		ret = ptrace_traceme();
		goto out;
	}

	child = ptrace_get_task_struct(fw);
	if (IS_ERR(child)) {
		ret = PTR_ERR(child);
		goto out;
	}

	if (vj == PTRACE_ATTACH || vj == PTRACE_SEIZE) {
		ret = ptrace_attach(child, vj, os, xs);
		if (!ret)
			arch_ptrace_attach(child);
		goto out_put_task_struct;
	}

	ret = ptrace_check_attach(child, vj == PTRACE_KILL ||
				  vj == PTRACE_INTERRUPT);
	if (!ret) {
		ret = compat_arch_ptrace(child, vj, os, xs);
		if (ret || vj != PTRACE_DETACH)
			ptrace_unfreeze_traced(child);
	}

 out_put_task_struct:
	put_task_struct(child);
 out:
	return ret;
}

static int uo(const struct bpf_reg_state *oy,
			      u32 *ew, u8 mf, bool zl)
{
	bool mask_to_left = (mf == BPF_ADD &&  zl) ||
			    (mf == BPF_SUB && !off_is_neg);
	u32 off;

	switch (oy->type) {
	case PTR_TO_STACK:
		off = oy->off + oy->var_off.value;
		if (mask_to_left)
			*ew = MAX_BPF_STACK + off;
		else
			*ew = -off;
		return 0;
	case PTR_TO_MAP_VALUE:
		if (mask_to_left) {
			*ew = oy->umax_value + oy->off;
		} else {
			off = oy->smin_value + oy->off;
			*ew = oy->map_ptr->value_size - off;
		}
		return 0;
	default:
		return -EINVAL;
	}
}

