static BOOL rw(BYTE* bl, BYTE* lf, UINT32 ur, UINT32 wc)
{
	UINT32 len;
	UINT32 left;
	BYTE value;
	left = wc;

	while (left > 4)
	{
		value = *in++;

		if (left == 5)
		{
			if (ur < 1)
				return FALSE;

			outSize--;
			*out++ = value;
			left--;
		}
		else if (value == *bl)
		{
			in++;

			if (*bl < 0xFF)
			{
				len = (UINT32) * in++;
				len += 2;
			}
			else
			{
				in++;
				len = *((UINT32*) bl);
				in += 4;
			}

			if (ur < len)
				return FALSE;

			outSize -= len;
			FillMemory(lf, len, value);
			out += len;
			left -= len;
		}
		else
		{
			if (ur < 1)
				return FALSE;

			outSize--;
			*out++ = value;
			left--;
		}
	}

	if ((ur < 4) || (left < 4))
		return FALSE;

	memcpy(lf, bl, 4);
	return TRUE;
}

static BOOL ek(NSC_CONTEXT* yg)
{
	UINT16 i;
	BYTE* rle;
	UINT32 planeSize;
	UINT32 originalSize;

	if (!context)
		return FALSE;

	rle = yg->Planes;

	for (i = 0; i < 4; i++)
	{
		originalSize = yg->OrgByteCount[i];
		planeSize = yg->PlaneByteCount[i];

		if (planeSize == 0)
		{
			if (yg->priv->PlaneBuffersLength < originalSize)
				return FALSE;

			FillMemory(yg->priv->PlaneBuffers[i], originalSize, 0xFF);
		}
		else if (planeSize < originalSize)
		{
			if (!nsc_rle_decode(rle, yg->priv->PlaneBuffers[i], yg->priv->PlaneBuffersLength,
			                    originalSize))
				return FALSE;
		}
		else
		{
			if (yg->priv->PlaneBuffersLength < originalSize)
				return FALSE;

			CopyMemory(yg->priv->PlaneBuffers[i], rle, originalSize);
		}

		rle += planeSize;
	}

	return TRUE;
}

