                            const char *yx, size_t yh)
{
    pair_t *pair;
    bucket_t *bucket;
    size_t index;

    index = yh & hashmask(wg->order);
    bucket = &wg->buckets[index];

    pair = hashtable_find_pair(wg, bucket, yx, yh);
    if(!pair)
        return -1;

    if(&pair->list == bucket->first && &pair->list == bucket->last)
        bucket->first = bucket->last = &wg->list;

    else if(&pair->list == bucket->first)
        bucket->first = pair->list.next;

    else if(&pair->list == bucket->last)
        bucket->last = pair->list.prev;

    list_remove(&pair->list);
    json_decref(pair->value);

    jsonp_free(pair);
    wg->size--;

    return 0;
}

