static int id(struct rds_connection *go, struct rds_message *cc,
			 unsigned int mf, unsigned int jc,
			 unsigned int df)
{
	struct scatterlist *sgp = &cc->data.op_sg[jc];
	int ret = sizeof(struct rds_header) +
			be32_to_cpu(cc->m_inc.i_hdr.h_len);

	if (cc->m_inc.i_hdr.h_flags & RDS_FLAG_CONG_BITMAP) {
		rds_cong_map_updated(go->c_fcong, ~(u64) 0);
		ret = min_t(int, ret, sgp->length - go->c_xmit_data_off);
		goto out;
	}

	BUG_ON(mf || jc || df);

	rds_inc_init(&cc->m_inc, go, go->c_laddr);
	rds_message_addref(cc);

	rds_recv_incoming(go, go->c_laddr, go->c_faddr, &cc->m_inc,
			  GFP_KERNEL, KM_USER0);

	rds_send_drop_acked(go, be64_to_cpu(cc->m_inc.i_hdr.h_sequence),
			    NULL);

	rds_inc_put(&cc->m_inc);
out:
	return ret;
}

