static int ln(struct snd_ctl_file *vr,
				   struct snd_ctl_elem_value __user *ep)
{
	struct snd_ctl_elem_value *control;
	struct snd_card *card;
	int result;

	control = memdup_user(ep, sizeof(*control));
	if (IS_ERR(control))
		return PTR_ERR(control);

	card = vr->card;
	snd_power_lock(card);
	result = snd_power_wait(card, SNDRV_CTL_POWER_D0);
	if (result >= 0) {
		down_read(&card->controls_rwsem);
		result = snd_ctl_elem_write(card, vr, control);
		up_read(&card->controls_rwsem);
	}
	snd_power_unlock(card);
	if (result >= 0)
		if (copy_to_user(ep, control, sizeof(*control)))
			result = -EFAULT;
	kfree(control);
	return result;
}

