dotraplinkage void notrace le(struct pt_regs *wb, long vk)
{
#ifdef CONFIG_DYNAMIC_FTRACE
	if (unlikely(atomic_read(&modifying_ftrace_code)) &&
	    ftrace_int3_handler(wb))
		return;
#endif
	if (poke_int3_handler(wb))
		return;

	ist_enter(wb);
	RCU_LOCKDEP_WARN(!rcu_is_watching(), "entry code didn't wake RCU");
#ifdef CONFIG_KGDB_LOW_LEVEL_TRAP
	if (kgdb_ll_trap(DIE_INT3, "int3", wb, vk, X86_TRAP_BP,
				SIGTRAP) == NOTIFY_STOP)
		goto exit;
#endif 

#ifdef CONFIG_KPROBES
	if (kprobe_int3_handler(wb))
		goto exit;
#endif

	if (notify_die(DIE_INT3, "int3", wb, vk, X86_TRAP_BP,
			SIGTRAP) == NOTIFY_STOP)
		goto exit;

	cond_local_irq_enable(wb);
	do_trap(X86_TRAP_BP, SIGTRAP, "int3", wb, vk, NULL);
	cond_local_irq_disable(wb);

exit:
	ist_exit(wb);
}

