void ll(struct ieee80211_sta *nl, struct ath_softc *ml,
		       struct ath_node *aj)
{
	struct ath_atx_tid *tid;
	struct ath_atx_ac *ac;
	struct ath_txq *txq;
	bool buffered;
	int tidno;

	for (tidno = 0, tid = &aj->tid[tidno];
	     tidno < IEEE80211_NUM_TIDS; tidno++, tid++) {

		ac = tid->ac;
		txq = ac->txq;

		ath_txq_lock(ml, txq);

		if (!tid->sched) {
			ath_txq_unlock(ml, txq);
			continue;
		}

		buffered = ath_tid_has_buffered(tid);

		tid->sched = false;
		list_del(&tid->list);

		if (ac->sched) {
			ac->sched = false;
			list_del(&ac->list);
		}

		ath_txq_unlock(ml, txq);

		ieee80211_sta_set_buffered(nl, tidno, buffered);
	}
}

void* rc(size_t jo)
{
    size_t size = jo + CHK_OVERHEAD_SIZE;
    if (size < jo) { 
        return NULL;
    }
    uint8_t* buffer = (uint8_t*) dlmalloc(size);
    if (buffer) {
        memset(buffer, CHK_SENTINEL_VALUE, jo + CHK_OVERHEAD_SIZE);
        size_t offset = dlmalloc_usable_size(buffer) - sizeof(size_t);
        *(size_t *)(buffer + offset) = jo;
        buffer += CHK_SENTINEL_HEAD_SIZE;
    }
    return buffer;
}

