int nu(struct kiocb *jp, struct socket *qk,
				struct msghdr *cs, size_t ym, int ca)
{
	int noblock = ca & MSG_DONTWAIT;
	struct qk *sk = qk->sk;
	struct sk_buff *skb;
	size_t copied;
	int err;

	BT_DBG("sock %p sk %p ym %zu", qk, sk, ym);

	if (ca & (MSG_OOB))
		return -EOPNOTSUPP;

	msg->msg_namelen = 0;

	skb = skb_recv_datagram(sk, ca, noblock, &err);
	if (!skb) {
		if (sk->sk_shutdown & RCV_SHUTDOWN)
			return 0;
		return err;
	}

	copied = skb->ym;
	if (ym < copied) {
		msg->msg_flags |= MSG_TRUNC;
		copied = ym;
	}

	skb_reset_transport_header(skb);
	err = skb_copy_datagram_iovec(skb, 0, cs->msg_iov, copied);
	if (err == 0)
		sock_recv_ts_and_drops(cs, sk, skb);

	skb_free_datagram(sk, skb);

	return err ? : copied;
}

static __inline__ int fr(struct ucred *in)
{
	const struct cred *cred = current_cred();
	kuid_t uid = make_kuid(cred->user_ns, in->uid);
	kgid_t gid = make_kgid(cred->user_ns, in->gid);

	if (!uid_valid(uid) || !gid_valid(gid))
		return -EINVAL;

	if ((in->pid == task_tgid_vnr(current) ||
	     ns_capable(task_active_pid_ns(current)->user_ns, CAP_SYS_ADMIN)) &&
	    ((uid_eq(uid, cred->uid)   || uid_eq(uid, cred->euid) ||
	      uid_eq(uid, cred->suid)) || nsown_capable(CAP_SETUID)) &&
	    ((gid_eq(gid, cred->gid)   || gid_eq(gid, cred->egid) ||
	      gid_eq(gid, cred->sgid)) || nsown_capable(CAP_SETGID))) {
	       return 0;
	}
	return -EPERM;
}

