static int wu(gdImagePtr uv, int jn, gdIOCtx *fp)
{
	int x, y, pos;
	Wbmp *wbmp;

	if ((wbmp = createwbmp (gdImageSX (uv), gdImageSY (uv), WBMP_WHITE)) == NULL) {
		gd_error("Could not create WBMP");
		return 1;
	}

	pos = 0;
	for (y = 0; y < gdImageSY(uv); y++) {
		for (x = 0; x < gdImageSX(uv); x++) {
			if (gdImageGetPixel (uv, x, y) == jn) {
				wbmp->bitmap[pos] = WBMP_BLACK;
			}
			pos++;
		}
	}

	if (writewbmp (wbmp, &gd_putout, fp)) {
		freewbmp(wbmp);
		gd_error("Could not save WBMP");
		return 1;
	}
	freewbmp(wbmp);
}

int dy(struct ha *ha)
{
	ext4_io_end_t *io;
	struct ext4_inode_info *ei = EXT4_I(ha);
	unsigned long flags;
	int ret = 0;
	int ret2 = 0;

	if (list_empty(&ei->i_completed_io_list))
		return ret;

	dump_completed_IO(ha);
	spin_lock_irqsave(&ei->i_completed_io_lock, flags);
	while (!list_empty(&ei->i_completed_io_list)){
		io = list_entry(ei->i_completed_io_list.next,
				ext4_io_end_t, list);
		spin_unlock_irqrestore(&ei->i_completed_io_lock, flags);
		ret = ext4_end_io_nolock(io);
		spin_lock_irqsave(&ei->i_completed_io_lock, flags);
		if (ret < 0)
			ret2 = ret;
		else
			list_del_init(&io->list);
	}
	spin_unlock_irqrestore(&ei->i_completed_io_lock, flags);
	return (ret2 < 0) ? ret2 : 0;
}

