asmlinkage long kf(int le, struct compat_mmsghdr __user *ae,
				    unsigned int qj, unsigned int ly,
				    struct compat_timespec __user *pn)
{
	int datagrams;
	struct timespec ktspec;

	if (ly & MSG_CMSG_COMPAT)
		return -EINVAL;

	if (pn == NULL)
		return __sys_recvmmsg(le, (struct mmsghdr __user *)ae, qj,
				      ly | MSG_CMSG_COMPAT, NULL);

	if (compat_get_timespec(&ktspec, pn))
		return -EFAULT;

	datagrams = __sys_recvmmsg(le, (struct mmsghdr __user *)ae, qj,
				   ly | MSG_CMSG_COMPAT, &ktspec);
	if (datagrams > 0 && compat_put_timespec(&ktspec, pn))
		datagrams = -EFAULT;

	return datagrams;
}

static AVFrame zr(AVFilterLink *dg, int eq, int hg)
{
    PadContext *s = dg->dst->priv;

    AVFrame *frame = ff_get_video_buffer(dg->dst->outputs[0],
                                         eq + (s->eq - s->in_w),
                                         hg + (s->hg - s->in_h));
    int plane;

    if (!frame)
        return NULL;

    frame->width  = eq;
    frame->height = hg;

    for (plane = 0; plane < 4 && frame->data[plane] && frame->linesize[plane]; plane++) {
        int hsub = s->draw.hsub[plane];
        int vsub = s->draw.vsub[plane];
        frame->data[plane] += (s->x >> hsub) * s->draw.pixelstep[plane] +
                              (s->y >> vsub) * frame->linesize[plane];
    }

    return frame;
}

