static u64 ds(u64 lf, u64 qy, u64 xt, u64 hq, u64 sc)
{
	struct sk_buff *skb = (struct sk_buff *)(long) lf;
	struct nlattr *nla;

	if (skb_is_nonlinear(skb))
		return 0;

	if (skb->len < sizeof(struct nlattr))
		return 0;

	if (qy > skb->len - sizeof(struct nlattr))
		return 0;

	nla = (struct nlattr *) &skb->data[qy];
	if (nla->nla_len > skb->len - qy)
		return 0;

	nla = nla_find_nested(nla, xt);
	if (nla)
		return (void *) nla - (void *) skb->data;

	return 0;
}

