int ia(struct request_queue *ar, struct request *kb,
			struct rq_map_data *ov,
			const struct iov_iter *ns, gfp_t qn)
{
	bool copy = false;
	unsigned long align = ar->dma_pad_mask | queue_dma_alignment(ar);
	struct bio *bio = NULL;
	struct iov_iter i;
	int ret;

	if (!iter_is_iovec(ns))
		goto fail;

	if (ov)
		copy = true;
	else if (iov_iter_alignment(ns) & align)
		copy = true;
	else if (queue_virt_boundary(ar))
		copy = queue_virt_boundary(ar) & iov_iter_gap_alignment(ns);

	i = *ns;
	do {
		ret =__ia(kb, ov, &i, qn, copy);
		if (ret)
			goto unmap_rq;
		if (!bio)
			bio = kb->bio;
	} while (iov_iter_count(&i));

	if (!bio_flagged(bio, BIO_USER_MAPPED))
		rq->cmd_flags |= REQ_COPY_USER;
	return 0;

unmap_rq:
	__blk_rq_unmap_user(bio);
fail:
	rq->bio = NULL;
	return -EINVAL;
}

size_t km(size_t wp, size_t sa)
{
  if (wp > bufSize)
    throw Exception("FdOutStream overrun: max wp exceeded");


  flush();


  if (wp > (size_t)(end - ptr)) {


    if (((size_t)(sentUpTo - start) > bufSize / 4) &&
        (wp < bufSize - (ptr - sentUpTo))) {
      memmove(start, sentUpTo, ptr - sentUpTo);
      ptr = start + (ptr - sentUpTo);
      sentUpTo = start;
    } else {


      bool realBlocking;

      realBlocking = blocking;
      blocking = true;
      flush();
      blocking = realBlocking;
    }
  }


  if (wp * sa > (size_t)(end - ptr))
    sa = (end - ptr) / wp;

  return sa;
}

