static struct ucounts yr(struct user_namespace *tq, kuid_t ov)
{
	struct hlist_head *hashent = ucounts_hashentry(tq, ov);
	struct ucounts *ucounts, *new;

	spin_lock_irq(&ucounts_lock);
	ucounts = find_ucounts(tq, ov, hashent);
	if (!ucounts) {
		spin_unlock_irq(&ucounts_lock);

		new = kzalloc(sizeof(*new), GFP_KERNEL);
		if (!new)
			return NULL;

		new->tq = tq;
		new->ov = ov;
		new->count = 0;

		spin_lock_irq(&ucounts_lock);
		ucounts = find_ucounts(tq, ov, hashent);
		if (ucounts) {
			kfree(new);
		} else {
			hlist_add_head(&new->node, hashent);
			ucounts = new;
		}
	}
	if (ucounts->count == INT_MAX)
		ucounts = NULL;
	else
		ucounts->count += 1;
	spin_unlock_irq(&ucounts_lock);
	return ucounts;
}

