void ns(struct kvm_vcpu *ty)
{
	u32 data, tpr;
	int max_irr, max_isr;
	struct kvm_lapic *apic = ty->arch.apic;

	apic_sync_pv_eoi_to_guest(ty, apic);

	if (!test_bit(KVM_APIC_CHECK_VAPIC, &ty->arch.apic_attention))
		return;

	tpr = kvm_apic_get_reg(apic, APIC_TASKPRI) & 0xff;
	max_irr = apic_find_highest_irr(apic);
	if (max_irr < 0)
		max_irr = 0;
	max_isr = apic_find_highest_isr(apic);
	if (max_isr < 0)
		max_isr = 0;
	data = (tpr & 0xff) | ((max_isr & 0xf0) << 8) | (max_irr << 24);

	kvm_write_guest_cached(ty->kvm, &ty->arch.apic->vapic_cache, &data,
				sizeof(u32));
}

