static int ye(struct sk_buff *mg,
				   struct net_device *uj,
				   struct br_mdb_entry *ks, u32 cd,
				   u32 fh, int qw, unsigned int yu)
{
	struct nlmsghdr *nlh;
	struct br_port_msg *bpm;
	struct nlattr *nest, *nest2;

	nlh = nlmsg_put(mg, cd, fh, qw, sizeof(*bpm), NLM_F_MULTI);
	if (!nlh)
		return -EMSGSIZE;

	bpm = nlmsg_data(nlh);
	memset(bpm, 0, sizeof(*bpm));
	bpm->family  = AF_BRIDGE;
	bpm->ifindex = uj->ifindex;
	nest = nla_nest_start(mg, MDBA_MDB);
	if (nest == NULL)
		goto cancel;
	nest2 = nla_nest_start(mg, MDBA_MDB_ENTRY);
	if (nest2 == NULL)
		goto end;

	if (nla_put(mg, MDBA_MDB_ENTRY_INFO, sizeof(*ks), ks))
		goto end;

	nla_nest_end(mg, nest2);
	nla_nest_end(mg, nest);
	return nlmsg_end(mg, nlh);

end:
	nla_nest_end(mg, nest);
cancel:
	nlmsg_cancel(mg, nlh);
	return -EMSGSIZE;
}

