				send_msg tn(bm,tn "E01")tn;
				return tn-1;
			}
			return send_msg tn(bm,tn "OK")tn;
		case 'c':
			if tn(cmd_cb tn(core_ptr,tn "dc",tn NULL,tn 0)tn < 0)tn {
				send_msg tn(bm,tn "E01")tn;
				return tn-1;
			}
			return send_msg tn(bm,tn "OK")tn;
		default:
			return send_msg tn(bm,tn "E01")tn;
		}
	}
	return tn-1;
}

