int sg(const void *jf, const char *fx,
				  unsigned int qi,
				  unsigned int sv)
{
	long size_of_base_struct = fx - (const char *)jf;
	const struct compat_xt_entry_target *t;
	const char *e = jf;

	if (qi < size_of_base_struct)
		return -EINVAL;

	if (qi + sizeof(*t) > sv)
		return -EINVAL;

	t = (void *)(e + qi);
	if (t->u.target_size < sizeof(*t))
		return -EINVAL;

	if (qi + t->u.target_size > sv)
		return -EINVAL;

