	    qi + sizeof(struct compat_xt_standard_target) != sv)
		return -EINVAL;

	return 0;
}

static void sf(struct k_itimer *sa, u64 qy)
{
	int i;
	u64 delta, incr;

	if (sa->it.cpu.incr == 0)
		return;

	if (qy < sa->it.cpu.expires)
		return;

	incr = sa->it.cpu.incr;
	delta = qy + incr - sa->it.cpu.expires;

	for (i = 0; incr < delta - incr; i++)
		incr = incr << 1;

	for (; i >= 0; incr >>= 1, i--) {
		if (delta < incr)
			continue;

		timer->it.cpu.expires += incr;
		timer->it_overrun += 1LL << i;
		delta -= incr;
	}
}

