static int zu(struct crypto_skcipher *xz,
				     const u8 *se, unsigned int gb)
{
	unsigned long alignmask = crypto_skcipher_alignmask(xz);
	struct skcipher_alg *cipher = crypto_skcipher_alg(xz);
	u8 *buffer, *alignbuffer;
	unsigned long absize;
	int ret;

	absize = gb + alignmask;
	buffer = kmalloc(absize, GFP_ATOMIC);
	if (!buffer)
		return -ENOMEM;

	alignbuffer = (u8 *)ALIGN((unsigned long)buffer, alignmask + 1);
	memcpy(alignbuffer, se, gb);
	ret = cipher->setkey(xz, alignbuffer, gb);
	kzfree(buffer);
	return ret;
}

