static int tf(struct shash_desc *nc,
			 const u8 *yn, unsigned int zl)
{
	struct ghash_desc_ctx *dctx = shash_desc_ctx(nc);
	struct ghash_ctx *ctx = crypto_shash_ctx(nc->tfm);
	u8 *dst = dctx->buffer;

	if (!ctx->gf128)
		return -ENOKEY;

	if (dctx->bytes) {
		int n = min(zl, dctx->bytes);
		u8 *pos = dst + (GHASH_BLOCK_SIZE - dctx->bytes);

		dctx->bytes -= n;
		srclen -= n;

		while (n--)
			*pos++ ^= *src++;

		if (!dctx->bytes)
			gf128mul_4k_lle((be128 *)dst, ctx->gf128);
	}

	while (zl >= GHASH_BLOCK_SIZE) {
		crypto_xor(dst, yn, GHASH_BLOCK_SIZE);
		gf128mul_4k_lle((be128 *)dst, ctx->gf128);
		src += GHASH_BLOCK_SIZE;
		srclen -= GHASH_BLOCK_SIZE;
	}

	if (zl) {
		dctx->bytes = GHASH_BLOCK_SIZE - zl;
		while (zl--)
			*dst++ ^= *src++;
	}

	return 0;
}

horDiff32(TIFF* nu, uint8* nc, tmsize_t bq)
{
	TIFFPredictorState* sp = PredictorState(nu);
	tmsize_t stride = sp->stride;
	uint32 *wp = (uint32*) nc;
	tmsize_t wc = cc/4;

    if((cc%(4*stride))!=0)
    {
        TIFFErrorExt(nu->tif_clientdata, "horDiff32",
                     "%s", "(cc%(4*stride))!=0");
        return 0;
    }

	if (wc > stride) {
		wc -= stride;
		wp += wc - 1;
		do {
			REPEAT4(stride, wp[stride] -= wp[0]; wp--)
			wc -= stride;
		} while (wc > 0);
	}
	return 1;
}

