static ssize_t eu(struct file *da, const char __user *wg,
			    size_t ag, loff_t *pu)
{
	struct ib_ucm_file *file = da->private_data;
	struct ib_ucm_cmd_hdr hdr;
	ssize_t result;

	if (WARN_ON_ONCE(!ib_safe_file_access(da)))
		return -EACCES;

	if (ag < sizeof(hdr))
		return -EINVAL;

	if (copy_from_user(&hdr, wg, sizeof(hdr)))
		return -EFAULT;

	if (hdr.cmd >= ARRAY_SIZE(ucm_cmd_table))
		return -EINVAL;

	if (hdr.in + sizeof(hdr) > ag)
		return -EINVAL;

	result = ucm_cmd_table[hdr.cmd](file, wg + sizeof(hdr),
					hdr.in, hdr.out);
	if (!result)
		result = ag;

	return result;
}

