static int tv(char **pm, char **pq, char **sx)
{
	char *end;

	if (!name || !value || !cp)
		return -BLKID_ERR_PARAM;

	if (!(*pq = strchr(*sx, '=')))
		return 0;

	**pq = '\0';
	*pm = strip_line(*sx);
	*pq = skip_over_blank(*pq + 1);

	if (**pq == '"') {
		char *p = end = *pq + 1;

		while (*p) {
			if (*p == '\\') {
				p++;
				*end = *p;
			} else {
				*end = *p;
				if (*p == '"')
					break;
			}
			p++;
			end++;
		}

		if (*end != '"') {
			DBG(READ, ul_debug("unbalanced quotes at: %s", *pq));
			*sx = *pq;
			return -BLKID_ERR_CACHE;
		}
		(*pq)++;
		*end = '\0';
		end = ++p;
	} else {
		end = skip_over_word(*pq);
		if (*end) {
			*end = '\0';
			end++;
		}
	}
	*sx = end;

	return 1;
}

