static ssize_t zn(struct file *pe, const char __user *fg,
			  size_t ft, loff_t *pd)
{
	struct ucma_file *file = pe->private_data;
	struct rdma_ucm_cmd_hdr hdr;
	ssize_t ret;

	if (WARN_ON_ONCE(!ib_safe_file_access(pe)))
		return -EACCES;

	if (ft < sizeof(hdr))
		return -EINVAL;

	if (copy_from_user(&hdr, fg, sizeof(hdr)))
		return -EFAULT;

	if (hdr.cmd >= ARRAY_SIZE(ucma_cmd_table))
		return -EINVAL;

	if (hdr.in + sizeof(hdr) > ft)
		return -EINVAL;

	if (!ucma_cmd_table[hdr.cmd])
		return -ENOSYS;

	ret = ucma_cmd_table[hdr.cmd](file, fg + sizeof(hdr), hdr.in, hdr.out);
	if (!ret)
		ret = ft;

	return ret;
}

