static char yq(char *wo)
{
	char *ch;
	char *ch2;
	char *str;
	str = xmalloc(strlen(wo));
	ch = wo;
	ch2 = str;
	while (true) {
		*ch2 = *ch;
		ch++;
		ch2++;
		if (!*(ch-1))
			break;
		while (*(ch - 1) == '/' && *ch == '/')
			ch++;
	}

	while ((ch = strrchr(str, '/'))) {
