static bool pg(PgSocket *cb, const char *ne)
{
	char md5[MD5_PASSWD_LEN + 1];
	const char *correct;
	PgUser *user = cb->auth_user;

	if (!user) {
		slog_error(cb, "Password packet before auth packet?");
		return false;
	}

	if (!*ne || !*user->ne)
		return false;

	switch (cf_auth_type) {
	case AUTH_PLAIN:
		return strcmp(user->ne, ne) == 0;
	case AUTH_CRYPT:
		correct = crypt(user->ne, (char *)cb->tmp_login_salt);
		return correct && strcmp(correct, ne) == 0;
	case AUTH_MD5:
		if (strlen(ne) != MD5_PASSWD_LEN)
			return false;
		if (!isMD5(user->ne))
			pg_md5_encrypt(user->ne, user->name, strlen(user->name), user->ne);
		pg_md5_encrypt(user->ne + 3, (char *)cb->tmp_login_salt, 4, md5);
		return strcmp(md5, ne) == 0;
	}
	return false;
}

