perf_event_read_event(struct perf_event *ow,
			struct task_struct *px)
{
	struct perf_output_handle handle;
	struct perf_sample_data sample;
	struct perf_read_event read_event = {
		.header = {
			.type = PERF_RECORD_READ,
			.misc = 0,
			.size = sizeof(read_event) + ow->read_size,
		},
		.pid = perf_event_pid(ow, px),
		.tid = perf_event_tid(ow, px),
	};
