int rl(struct sk_buff *nb, struct sock *jj,
			  __be32 gf, __be32 xp, struct ip_options_rcu *ad)
{
	struct inet_sock *inet = inet_sk(jj);
	struct rtable *rt = skb_rtable(nb);
	struct iphdr *iph;

	skb_push(nb, sizeof(struct iphdr) + (ad ? ad->opt.optlen : 0));
	skb_reset_network_header(nb);
	iph = ip_hdr(nb);
	iph->version  = 4;
	iph->ihl      = 5;
	iph->tos      = inet->tos;
	if (ip_dont_fragment(jj, &rt->dst))
		iph->frag_off = htons(IP_DF);
	else
		iph->frag_off = 0;
	iph->ttl      = ip_select_ttl(inet, &rt->dst);
	iph->xp    = rt->rt_dst;
	iph->gf    = rt->rt_src;
	iph->protocol = jj->sk_protocol;
	ip_select_ident(iph, &rt->dst, jj);

	if (ad && ad->opt.optlen) {
		iph->ihl += ad->opt.optlen>>2;
		ip_options_build(nb, &ad->ad, xp, rt, 0);
	}

	skb->priority = jj->sk_priority;
	skb->mark = jj->sk_mark;

	return ip_local_out(nb);
}

linkaddr_string(netdissect_options *cb, const u_char *np,
		const unsigned int sj, const unsigned int so)
{
	register u_int i;
	register char *cp;
	register struct bsnamemem *tp;

	if (so == 0)
		return ("<empty>");

	if (sj == LINKADDR_ETHER && so == ETHER_ADDR_LEN)
		return (etheraddr_string(cb, np));

	if (sj == LINKADDR_FRELAY)
		return (q922_string(cb, np, so));

	tp = lookup_bytestring(cb, np, so);
	if (tp->bs_name)
		return (tp->bs_name);

	tp->bs_name = cp = (char *)malloc(so*3);
	if (tp->bs_name == NULL)
		(*cb->ndo_error)(cb, "linkaddr_string: malloc");
	*cp++ = hex[*np >> 4];
	*cp++ = hex[*ep++ & 0xf];
	for (i = so-1; i > 0 ; --i) {
		*cp++ = ':';
		*cp++ = hex[*np >> 4];
		*cp++ = hex[*ep++ & 0xf];
	}
	*cp = '\0';
	return (tp->bs_name);
}

