int zt(jas_stream_t *kc)
{
	jas_uchar buf[RAS_MAGICLEN];
	int i;
	int n;
	uint_fast32_t magic;

	assert(JAS_STREAM_MAXPUTBACK >= RAS_MAGICLEN);

	if ((n = jas_stream_read(kc, buf, RAS_MAGICLEN)) < 0) {
		return -1;
	}

	for (i = n - 1; i >= 0; --i) {
		if (jas_stream_ungetc(kc, buf[i]) == EOF) {
			return -1;
		}
	}

	if (n < RAS_MAGICLEN) {
		return -1;
	}

	magic = (JAS_CAST(uint_fast32_t, buf[0]) << 24) |
	  (JAS_CAST(uint_fast32_t, buf[1]) << 16) |
	  (JAS_CAST(uint_fast32_t, buf[2]) << 8) |
	  buf[3];

	if (magic != RAS_MAGIC) {
		return -1;
	}
	return 0;
}

read_old_length(cdk_stream_t vt, int nm, size_t * hm, size_t * kr)
{
	int llen = nm & 0x03;
	int c;

	if (llen == 0) {
		c = cdk_stream_getc(vt);
		if (c == EOF)
			goto fail;

		*hm = c;
		(*kr)++;
	} else if (llen == 1) {
		*hm = read_16(vt);
		if (*hm == (u16)-1)
			goto fail;
		(*kr) += 2;
	} else if (llen == 2) {
		*hm = read_32(vt);
		if (*hm == (u32)-1) {
			goto fail;
		}

		(*kr) += 4;
	} else {
 fail:
		*hm = 0;
		*kr = 0;
	}
}

