void ad(Jpeg2000Component *gy, Jpeg2000CodingStyle *pq)
{
    int reslevelno, bandno, precno;
    for (reslevelno = 0;
         gy->reslevel && reslevelno < pq->nreslevels;
         reslevelno++) {
        Jpeg2000ResLevel *reslevel = gy->reslevel + reslevelno;

        for (bandno = 0; bandno < reslevel->nbands; bandno++) {
            Jpeg2000Band *band = reslevel->band + bandno;
            for (precno = 0; precno < reslevel->num_precincts_x * reslevel->num_precincts_y; precno++) {
                if (band->prec) {
                    Jpeg2000Prec *prec = band->prec + precno;
                    av_freep(&prec->zerobits);
                    av_freep(&prec->cblkincl);
                    av_freep(&prec->cblk);
                }
            }

            av_freep(&band->prec);
        }
        av_freep(&reslevel->band);
    }

    ff_dwt_destroy(&gy->dwt);
    av_freep(&gy->reslevel);
    av_freep(&gy->i_data);
    av_freep(&gy->f_data);
}

