void bj(struct k_itimer *kf, struct itimerspec64 *aw)
{
	const struct k_clock *kc = kf->kclock;
	ktime_t now, remaining, iv;
	struct timespec64 ts64;
	bool sig_none;

	sig_none = kf->it_sigev_notify == SIGEV_NONE;
	iv = kf->it_interval;

	if (iv) {
		cur_setting->it_interval = ktime_to_timespec64(iv);
	} else if (!timr->it_active) {
		if (!sig_none)
			return;
	}

	kc->clock_get(kf->it_clock, &ts64);
	now = timespec64_to_ktime(ts64);

	if (iv && (kf->it_requeue_pending & REQUEUE_PENDING || sig_none))
		timr->it_overrun += kc->timer_forward(kf, now);

	remaining = kc->timer_remaining(kf, now);
	if (remaining <= 0) {
		if (!sig_none)
			cur_setting->it_value.tv_nsec = 1;
	} else {
		cur_setting->it_value = ktime_to_timespec64(remaining);
	}
}

