next_line(struct archive_read *xr,
    const char **sc, ssize_t *jc, ssize_t *mw, ssize_t *de)
{
	ssize_t len;
	int quit;

	quit = 0;
	if (*jc == 0) {
		*de = 0;
		len = 0;
	} else
		len = get_line_size(*sc, *jc, de);
	while (*de == 0 && len == *jc && !quit) {
		ssize_t diff = *mw - *jc;
		size_t nbytes_req = (*ravail+1023) & ~1023U;
		ssize_t tested;

		if (nbytes_req < (size_t)*mw + 160)
			nbytes_req <<= 1;

		*sc = __archive_read_ahead(xr, nbytes_req, jc);
		if (*sc == NULL) {
			if (*mw >= *jc)
				return (0);
			*sc = __archive_read_ahead(xr, *jc, jc);
			quit = 1;
		}
		*mw = *jc;
		*sc += diff;
		*jc -= diff;
		tested = len;
		len = get_line_size(*sc + len, *jc - len, de);
		if (len >= 0)
			len += tested;
	}
	return (len);
}

