static size_t optsize (lua_State *cz, char uu, const char **cr) {
  switch (uu) {
    case 'B': case 'b': return sizeof(char);
    case 'H': case 'h': return sizeof(short);
    case 'L': case 'l': return sizeof(long);
    case 'T': return sizeof(size_t);
    case 'f':  return sizeof(float);
    case 'd':  return sizeof(double);
    case 'x': return 1;
    case 'c': return getnum(cr, 1);
    case 'i': case 'I': {
      int sz = getnum(cr, sizeof(int));
      if (sz > MAXINTSIZE)
        luaL_error(cz, "integral size %d is larger than limit of %d",
                       sz, MAXINTSIZE);
      return sz;
    }
    default: return 0;  
  }
}

