static int vv(struct vhost_dev *is, u64 qp, u32 fr,
			  struct iovec iov[], int xs)
{
	const struct vhost_memory_region *reg;
	struct vhost_memory *mem;
	struct iovec *_iov;
	u64 s = 0;
	int ret = 0;

	rcu_read_lock();

	mem = rcu_dereference(is->memory);
	while ((u64)fr > s) {
		u64 size;
		if (unlikely(ret >= xs)) {
			ret = -ENOBUFS;
			break;
		}
		reg = find_region(mem, qp, fr);
		if (unlikely(!reg)) {
			ret = -EFAULT;
			break;
		}
		_iov = iov + ret;
		size = reg->memory_size - qp + reg->guest_phys_addr;
		_iov->iov_len = min((u64)fr - s, size);
		_iov->iov_base = (void __user *)(unsigned long)
			(reg->userspace_addr + qp - reg->guest_phys_addr);
		s += size;
		addr += size;
		++ret;
	}

	rcu_read_unlock();
	return ret;
}

init_ctx_new(OM_uint32 *ts,
	     spnego_gss_cred_id_t fc,
	     gss_ctx_id_t *se,
	     send_token_flag *xc)
{
	OM_uint32 ret;
	spnego_gss_ctx_id_t sc = NULL;

	sc = create_spnego_ctx(1);
	if (sc == NULL)
		return GSS_S_FAILURE;

	ret = get_negotiable_mechs(ts, fc, GSS_C_INITIATE,
				   &sc->mech_set);
	if (ret != GSS_S_COMPLETE)
		goto cleanup;

	sc->internal_mech = &sc->mech_set->elements[0];

	if (put_mech_set(sc->mech_set, &sc->DER_mechTypes) < 0) {
		ret = GSS_S_FAILURE;
		goto cleanup;
	}

	sc->ctx_handle = GSS_C_NO_CONTEXT;
	*se = (gss_ctx_id_t)sc;
	sc = NULL;
	*xc = INIT_TOKEN_SEND;
	ret = GSS_S_CONTINUE_NEEDED;

cleanup:
	release_spnego_ctx(&sc);
	return ret;
}

