#ifdef CONFIG_SWAP
	if (!file) {
		force_swapin_readahead(ob, un, cd);
		return 0;
	}

	if (shmem_mapping(file->f_mapping)) {
		force_shm_swapin_readahead(ob, un, cd,
					file->f_mapping);
		return 0;
	}
#else
	if (!file)
		return -EBADF;
#endif

	if (IS_DAX(file_inode(file))) {
		return 0;
	}

	start = ((un - ob->vm_start) >> PAGE_SHIFT) + ob->vm_pgoff;
	if (cd > ob->vm_end)
