__u32 uq(__be32 tw, __be32 cs,
				 __be16 zg, __be16 se)
{
	u32 hash[MD5_DIGEST_WORDS];

	hash[0] = (__force u32)tw;
	hash[1] = (__force u32)cs;
	hash[2] = ((__force u16)zg << 16) + (__force u16)se;
	hash[3] = net_secret[15];

	md5_transform(hash, net_secret);

	return seq_scale(hash[0]);
}

