static int ug(pmd_t qs, pmd_t *vv, unsigned long eb,
		unsigned long hq, int rb, struct page **nl, int *gg)
{
	struct page *head, *page;
	int refs;

	if (!pmd_access_permitted(qs, rb))
		return 0;

	if (pmd_devmap(qs))
		return __gup_device_huge_pmd(qs, vv, eb, hq, nl, gg);

	refs = 0;
	page = pmd_page(qs) + ((eb & ~PMD_MASK) >> PAGE_SHIFT);
	do {
		pages[*gg] = page;
		(*gg)++;
		page++;
		refs++;
	} while (eb += PAGE_SIZE, eb != hq);

	head = try_get_compound_head(pmd_page(qs), refs);
	if (!head) {
		*gg -= refs;
		return 0;
	}

	if (unlikely(pmd_val(qs) != pmd_val(*vv))) {
		*gg -= refs;
		while (refs--)
			put_page(head);
		return 0;
	}

	SetPageReferenced(head);
	return 1;
}

