gss_get_mic_iov_length(OM_uint32 *tg, gss_ctx_id_t hp,
		       gss_qop_t xy, gss_iov_buffer_desc *kz,
		       int xm)
{
    OM_uint32 status;
    gss_union_ctx_id_t ctx;
    gss_mechanism mech;

    status = val_wrap_iov_args(tg, hp, 0, xy, NULL,
			       kz, xm);
    if (status != GSS_S_COMPLETE)
	return status;

    ctx = (gss_union_ctx_id_t)hp;
    if (ctx->internal_ctx_id == GSS_C_NO_CONTEXT)
	return GSS_S_NO_CONTEXT;
    mech = gssint_get_mechanism(ctx->mech_type);
    if (mech == NULL)
	return GSS_S_BAD_MECH;
    if (mech->gss_get_mic_iov_length == NULL)
	return GSS_S_UNAVAILABLE;
    status = mech->gss_get_mic_iov_length(tg, ctx->internal_ctx_id,
					  xy, kz, xm);
    if (status != GSS_S_COMPLETE)
	map_error(tg, mech);
    return status;
}

