asmlinkage void jo(struct pt_regs *de)
{
	unsigned int __user *pc;
	mm_segment_t seg;

	perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS,
			1, de, de->cp0_badvaddr);
	if ((de->cp0_badvaddr == de->cp0_epc) || (de->cp0_epc & 0x1))
		goto sigbus;

	pc = (unsigned int __user *) exception_epc(de);
	if (user_mode(de) && !test_thread_flag(TIF_FIXADE))
		goto sigbus;
	if (unaligned_action == UNALIGNED_ACTION_SIGNAL)
		goto sigbus;
	else if (unaligned_action == UNALIGNED_ACTION_SHOW)
		show_registers(de);

	seg = get_fs();
	if (!user_mode(de))
		set_fs(KERNEL_DS);
	emulate_load_store_insn(de, (void __user *)de->cp0_badvaddr, pc);
	set_fs(seg);

	return;

sigbus:
	die_if_kernel("Kernel unaligned instruction access", de);
	force_sig(SIGBUS, current);

}

