static noinline void gr(struct list_head *ts)
{
	while (!list_empty(ts)) {
		struct key *key =
			list_entry(ts->next, struct key, graveyard_link);
		list_del(&key->graveyard_link);

		kdebug("- %u", key->serial);
		key_check(key);

		if (test_bit(KEY_FLAG_INSTANTIATED, &key->flags) &&
		    !test_bit(KEY_FLAG_NEGATIVE, &key->flags) &&
		    key->type->destroy)
			key->type->destroy(key);

		security_key_free(key);

		if (test_bit(KEY_FLAG_IN_QUOTA, &key->flags)) {
			spin_lock(&key->user->lock);
			key->user->qnkeys--;
			key->user->qnbytes -= key->quotalen;
			spin_unlock(&key->user->lock);
		}

		atomic_dec(&key->user->nkeys);
		if (test_bit(KEY_FLAG_INSTANTIATED, &key->flags))
			atomic_dec(&key->user->nikeys);

		key_user_put(key->user);

		kfree(key->description);

#ifdef KEY_DEBUGGING
		key->magic = KEY_DEBUG_MAGIC_X;
#endif
		kmem_cache_free(key_jar, key);
	}
}

void uz(fp_t jz, const fp_t ek, const bn_t hb) {
	size_t l;
	fp_t r;

	fp_null(r);

	if (bn_is_zero(hb)) {
		fp_set_dig(jz, 1);
		return;
	}

	RLC_TRY {
		fp_new(r);

		l = bn_bits(hb);

		fp_copy(r, ek);

		for (int i = l - 2; i >= 0; i--) {
			fp_sqr(r, r);
			if (bn_get_bit(hb, i)) {
				fp_mul(r, r, ek);
			}
		}

		if (bn_sign(hb) == RLC_NEG) {
			fp_inv(jz, r);
		} else {
			fp_copy(jz, r);
		}
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		fp_free(r);
	}
}

