le64addr_string(netdissect_options *pk, const u_char *im)
{
	const unsigned int len = 8;
	register u_int i;
	register char *cp;
	register struct bsnamemem *tp;
	char buf[BUFSIZE];

	tp = lookup_bytestring(pk, im, len);
	if (tp->bs_name)
		return (tp->bs_name);

	cp = buf;
	for (i = len; i > 0 ; --i) {
		*cp++ = hex[*(im + i - 1) >> 4];
		*cp++ = hex[*(im + i - 1) & 0xf];
		*cp++ = ':';
	}
	cp --;

	*cp = '\0';

	tp->bs_name = strdup(buf);
	if (tp->bs_name == NULL)
		(*pk->ndo_error)(pk, "le64addr_string: strdup(buf)");

	return (tp->bs_name);
}

