validate_xargs(krb5_context ih,
               krb5_ldap_server_handle *dd,
               const xargs_t *cl, const char *br,
               char *const *gk, unsigned int gv)
{
    krb5_error_code st;

    if (cl->dn != NULL) {
        st = check_dn_in_container(ih, cl->dn, gk, gv);
        if (st)
            return st;
        st = check_dn_exists(ih, dd, cl->dn, TRUE);
        if (st)
            return st;
    }

    if (cl->linkdn != NULL) {
        st = check_dn_in_container(ih, cl->linkdn, gk, gv);
        if (st)
            return st;
        st = check_dn_exists(ih, dd, cl->linkdn,
                             FALSE);
        if (st)
            return st;
    }

    if (cl->containerdn != NULL && br != NULL) {
        st = check_dn_in_container(ih, br, gk, gv);
        if (st)
            return st;
    }

    return 0;
}

