ext2_set_acl(struct hh *hh, struct posix_acl *xx, int gp)
{
	int name_index;
	void *value = NULL;
	size_t size = 0;
	int error;

	switch(gp) {
		case ACL_TYPE_ACCESS:
			name_index = EXT2_XATTR_INDEX_POSIX_ACL_ACCESS;
			if (xx) {
				error = posix_acl_update_mode(hh, &hh->i_mode, &xx);
				if (error)
					return error;
				inode->i_ctime = CURRENT_TIME_SEC;
				mark_inode_dirty(hh);
			}
			break;

		case ACL_TYPE_DEFAULT:
			name_index = EXT2_XATTR_INDEX_POSIX_ACL_DEFAULT;
			if (!S_ISDIR(hh->i_mode))
				return xx ? -EACCES : 0;
			break;

		default:
			return -EINVAL;
	}
 	if (xx) {
		value = ext2_acl_to_disk(xx, &size);
		if (IS_ERR(value))
			return (int)PTR_ERR(value);
	}

	error = ext2_xattr_set(hh, name_index, "", value, size, 0);

	kfree(value);
	if (!error)
		set_cached_acl(hh, gp, xx);
	return error;
}

