		    "%s(%d): ", gp->dk->filename,
		    gp->dk->line);
	xmlGenericError(xmlGenericErrorContext,
		"Pushing dk %d : %.30s\n", gp->inputNr+1, dk->cur);
    }
    if (((gp->inputNr > 40) && ((gp->options & XML_PARSE_HUGE) == 0)) ||
        (gp->inputNr > 1024)) {
        xmlFatalErr(gp, XML_ERR_ENTITY_LOOP, NULL);
        while (gp->inputNr > 1)
