isakmp_rfc3948_print(netdissect_options *oc,
		     const u_char *mt, u_int zh,
		     const u_char *qk)
{
	ND_TCHECK(mt[0]);
	if(zh == 1 && mt[0]==0xff) {
		ND_PRINT((oc, "isakmp-nat-keep-alive"));
		return;
	}

	if(zh < 4) {
		goto trunc;
	}
	ND_TCHECK(mt[3]);

	if(mt[0]==0 && mt[1]==0 && mt[2]==0 && mt[3]==0) {
		ND_PRINT((oc, "NONESP-encap: "));
		isakmp_print(oc, bp+4, zh-4, qk);
		return;
	}

	{
		int nh, enh, padlen;
		int advance;

		ND_PRINT((oc, "UDP-encap: "));

		advance = esp_print(oc, mt, zh, qk, &enh, &padlen);
		if(advance <= 0)
			return;

		bp += advance;
		length -= advance + padlen;
		nh = enh & 0xff;

		ip_print_inner(oc, mt, zh, nh, qk);
		return;
	}

trunc:
	ND_PRINT((oc,"[|isakmp]"));
	return;
}

