static bool cc(MprJson *kv, int xo, char *po)
{
    if (!(kv->type & MPR_JSON_VALUE)) {
        return 0;
    }
    if ((po = stok(po, "'\"", NULL)) == 0) {
        return 0;
    }
    switch (xo) {
    case JSON_OP_EQ:
        return smatch(kv->po, po);
    case JSON_OP_NE:
        return !smatch(kv->po, po);
    case JSON_OP_LT:
        return scmp(kv->po, po) < 0;
    case JSON_OP_LE:
        return scmp(kv->po, po) <= 0;
    case JSON_OP_GT:
        return scmp(kv->po, po) > 0;
    case JSON_OP_GE:
        return scmp(kv->po, po) >= 0;
    case JSON_OP_MATCH:
        return scontains(kv->po, po) != 0;
    case JSON_OP_NMATCH:
        return scontains(kv->po, po) == 0;
    default:
        return 0;
    }
}

