static int df(AVIOContext *ff, MXFIndexTableSegment *at)
{
    int i, length;

    at->nb_index_entries = avio_rb32(ff);

    length = avio_rb32(ff);
    if(at->nb_index_entries && length < 11)
        return AVERROR_INVALIDDATA;

    if (!(at->temporal_offset_entries=av_calloc(at->nb_index_entries, sizeof(*at->temporal_offset_entries))) ||
        !(at->flag_entries          = av_calloc(at->nb_index_entries, sizeof(*at->flag_entries))) ||
        !(at->stream_offset_entries = av_calloc(at->nb_index_entries, sizeof(*at->stream_offset_entries)))) {
        av_freep(&at->temporal_offset_entries);
        av_freep(&at->flag_entries);
        return AVERROR(ENOMEM);
    }

    for (i = 0; i < at->nb_index_entries; i++) {
        if(avio_feof(ff))
            return AVERROR_INVALIDDATA;
        at->temporal_offset_entries[i] = avio_r8(ff);
        avio_r8(ff);                                        
        at->flag_entries[i] = avio_r8(ff);
        at->stream_offset_entries[i] = avio_rb64(ff);
        avio_skip(ff, length - 11);
    }
    return 0;
}

