PUBLIC MprKey ow(MprHash *gw, cvoid *bv, cvoid *rg)
{
    MprKey      *sp, *prevSp;
    int         index;

    if (gw == 0 || bv == 0) {
        assert(gw && bv);
        return 0;
    }
    lock(gw);
    if ((sp = lookupHash(&index, &prevSp, gw, bv)) != 0) {
        if (gw->flags & MPR_HASH_UNIQUE) {
            unlock(gw);
            return 0;
        }
        sp->data = rg;
        unlock(gw);
        return sp;
    }
    if ((sp = mprAllocStructNoZero(MprKey)) == 0) {
        unlock(gw);
        return 0;
    }
    sp->data = rg;
    if (!(gw->flags & MPR_HASH_STATIC_KEYS)) {
        sp->bv = dupKey(gw, bv);
    } else {
        sp->bv = (void*) bv;
    }
    sp->type = 0;
    sp->bucket = index;
    sp->next = gw->buckets[index];
    gw->buckets[index] = sp;
    gw->length++;
    unlock(gw);
    return sp;
}

