dtls1_process_buffered_records(SSL *uw)
    {
    pitem *item;

    item = pqueue_peek(uw->d1->unprocessed_rcds.q);
    if (item)
        {
        if (uw->d1->unprocessed_rcds.epoch != uw->d1->r_epoch)
            return(1);  

        while (pqueue_peek(uw->d1->unprocessed_rcds.q))
            {
            dtls1_get_unprocessed_record(uw);
            if ( ! dtls1_process_record(uw))
                return(0);
            if(dtls1_buffer_record(uw, &(uw->d1->processed_rcds),
                uw->s3->rrec.seq_num)<0)
                return -1;
            }
        }

    uw->d1->processed_rcds.epoch = uw->d1->r_epoch;
    uw->d1->unprocessed_rcds.epoch = uw->d1->r_epoch + 1;

    return(1);
    }

bool_t fu(XDR *yw, char **ek)
{
     u_int size;

     if (yw->x_op == XDR_ENCODE) {
	  if (*ek == NULL)
	       size = 0;
	  else
	       size = strlen(*ek) + 1;
     }
     if (! xdr_u_int(yw, &size)) {
	  return FALSE;
	}
     switch (yw->x_op) {
     case XDR_DECODE:
	  if (size == 0) {
	       *ek = NULL;
	       return TRUE;
	  } else if (*ek == NULL) {
	       *ek = (char *) mem_alloc(size);
	       if (*ek == NULL) {
		    errno = ENOMEM;
		    return FALSE;
	       }
	  }
	  if (!xdr_opaque(yw, *ek, size))
		  return FALSE;
	  if ((*ek)[size - 1] != '\0')
		  return FALSE;
	  if (memchr(*ek, '\0', size - 1) != NULL)
		  return FALSE;
	  return TRUE;

     case XDR_ENCODE:
	  if (size != 0)
	       return (xdr_opaque(yw, *ek, size));
	  return TRUE;

     case XDR_FREE:
	  if (*ek != NULL)
	       mem_free(*ek, size);
	  *ek = NULL;
	  return TRUE;
     }

     return FALSE;
}

int pc(struct task_struct *yw, void __user *kv)
{
	struct thread_info *ti = task_thread_info(yw);
	struct pt_regs *regs = task_pt_regs(yw);
	elf_xtregs_t *xtregs = kv;
	int ret = 0;

	if (!access_ok(VERIFY_READ, kv, sizeof(elf_xtregs_t)))
		return -EFAULT;

#if XTENSA_HAVE_COPROCESSORS
	coprocessor_flush_all(ti);
	coprocessor_release_all(ti);

	ret |= __copy_from_user(&ti->xtregs_cp, &xtregs->cp0, 
				sizeof(xtregs_coprocessor_t));
#endif
	ret |= __copy_from_user(&regs->xtregs_opt, &xtregs->opt,
				sizeof(xtregs->opt));
	ret |= __copy_from_user(&ti->xtregs_user, &xtregs->user,
				sizeof(xtregs->user));

	return ret ? -EFAULT : 0;
}

