gss_verify_mic_iov(OM_uint32 *cn, gss_ctx_id_t xo,
		   gss_qop_t *jf, gss_iov_buffer_desc *xg,
		   int hn)
{
    OM_uint32 status;
    gss_union_ctx_id_t ctx;
    gss_mechanism mech;

    status = val_unwrap_iov_args(cn, xo, NULL,
				 jf, xg, hn);
    if (status != GSS_S_COMPLETE)
	return status;

    ctx = (gss_union_ctx_id_t)xo;
    if (ctx->internal_ctx_id == GSS_C_NO_CONTEXT)
	return GSS_S_NO_CONTEXT;
    mech = gssint_get_mechanism(ctx->mech_type);
    if (mech == NULL)
	return GSS_S_BAD_MECH;
    if (mech->gss_verify_mic_iov == NULL)
	return GSS_S_UNAVAILABLE;
    status = mech->gss_verify_mic_iov(cn, ctx->internal_ctx_id,
				      jf, xg, hn);
    if (status != GSS_S_COMPLETE)
	map_error(cn, mech);
    return status;
}

