                        unsigned long *aq,
                        SmsCallbacks  *xx,
                        char         **lp)
{
        IceConn                ice_conn;
        GsmClient             *client;
        GsmIceConnectionWatch *data;

        if (ga->priv->xsmp_sockets == NULL) {
                g_debug ("GsmXsmpServer: In shutdown, rejecting new client");

                *lp = strdup (_("Refusing new client connection because the session is currently being shut down\n"));
