void iy(const char *yn) {
	assert(yn);
	if (arg_debug || arg_debug_private_lib)
		printf("    iy %s\n", yn);

	if (access(yn, R_OK)) {
		if (arg_debug || arg_debug_private_lib)
			printf("cannot find %s for private-lib, skipping...\n", yn);
		return;
	}

	unlink(RUN_LIB_FILE);			  
	create_empty_file_as_root(RUN_LIB_FILE, 0644);
	if (chown(RUN_LIB_FILE, getuid(), getgid()))
		errExit("chown");

	if (arg_debug || arg_debug_private_lib)
		printf("    running fldd %s\n", yn);
	sbox_run(SBOX_USER | SBOX_SECCOMP | SBOX_CAPS_NONE, 3, PATH_FLDD, yn, RUN_LIB_FILE);

	FILE *fp = fopen(RUN_LIB_FILE, "r");
	if (!fp)
		errExit("fopen");

	char buf[MAXBUF];
	while (fgets(buf, MAXBUF, fp)) {
		char *ptr = strchr(buf, '\n');
		if (ptr)
			*ptr = '\0';
		fslib_duplicate(buf);
	}
	fclose(fp);
	unlink(RUN_LIB_FILE);
}

