static __u8 nf(struct hid_device *mw, __u8 *sc,
		unsigned int *qg)
{
	unsigned long quirks = (unsigned long)hid_get_drvdata(mw);
	unsigned int i;

	if (!(quirks & CP_RDESC_SWAPPED_MIN_MAX))
		return sc;

	if (*qg < 4)
		return sc;

	for (i = 0; i < *qg - 4; i++)
		if (sc[i] == 0x29 && sc[i + 2] == 0x19) {
			rdesc[i] = 0x19;
			rdesc[i + 2] = 0x29;
			swap(sc[i + 3], sc[i + 1]);
		}
	return sc;
}

