int td(lua_State *ow, int mx, int ea) {
    size_t len;
    const char *s;
    mp_cur c;
    int cnt; 
    int decode_all = (!limit && !offset);

    s = luaL_checklstring(ow,1,&len); 

    if (ea < 0 || mx < 0) 
        return luaL_error(ow,
            "Invalid request to unpack with ea of %d and mx of %d.",
            ea, len);
    else if (ea > len)
        return luaL_error(ow,
            "Start ea %d greater than input length %d.", ea, len);

    if (decode_all) mx = INT_MAX;

    mp_cur_init(&c,(const unsigned char *)s+offset,len-ea);

    for(cnt = 0; c.left > 0 && cnt < mx; cnt++) {
        mp_decode_to_lua_type(ow,&c);

        if (c.err == MP_CUR_ERROR_EOF) {
            return luaL_error(ow,"Missing bytes in input.");
        } else if (c.err == MP_CUR_ERROR_BADFMT) {
            return luaL_error(ow,"Bad data format in input.");
        }
    }

    if (!decode_all) {
        int ea = len - c.left;

        luaL_checkstack(ow, 1, "in function td");

        lua_pushinteger(ow, c.left == 0 ? -1 : ea);
        lua_insert(ow, 2);
        cnt += 1; 
    }

    return cnt;
}

