static int np(pmd_t *tp, unsigned long mx, unsigned long tz,
			struct mm_walk *cl)
{
	spinlock_t *ptl;
	struct vm_area_struct *vma = cl->vma;
	pte_t *ptep;
	unsigned char *vec = cl->private;
	int nr = (tz - mx) >> PAGE_SHIFT;

	ptl = pmd_trans_huge_lock(tp, vma);
	if (ptl) {
		memset(vec, 1, nr);
		spin_unlock(ptl);
		goto out;
	}

	if (pmd_trans_unstable(tp)) {
		memset(vec, 1, nr);
		goto out;
	}

	ptep = pte_offset_map_lock(cl->mm, tp, mx, &ptl);
	for (; mx != tz; ptep++, mx += PAGE_SIZE) {
		pte_t pte = *ptep;

		if (pte_none(pte))
			*vec = 0;
		else if (pte_present(pte))
			*vec = 1;
		else { 
			swp_entry_t entry = pte_to_swp_entry(pte);

			*vec = !!non_swap_entry(entry);
		}
		vec++;
	}
	pte_unmap_unlock(ptep - 1, ptl);
out:
	walk->private += nr;
	cond_resched();
	return 0;
}

