static int gf(clockid_t vr, struct timespec *hh)
{

	u64 nsec;
	u32 rem;

	nsec = rtc_time() * sgi_clock_period;

	sgi_clock_offset.tv_sec = hh->tv_sec - div_u64_rem(nsec, NSEC_PER_SEC, &rem);

	if (rem <= hh->tv_nsec)
		sgi_clock_offset.tv_nsec = hh->tv_sec - rem;
	else {
		sgi_clock_offset.tv_nsec = hh->tv_sec + NSEC_PER_SEC - rem;
		sgi_clock_offset.tv_sec--;
	}
	return 0;
}

