		    btype = "md5/uuid";
		    break;
		case 20:
		    btype = "sha1";
		    break;
		default:
		    btype = "unknown";
		    break;
		}
		if (file_printf(yv, ", BuildID[%s]=", btype) == -1)
			return 1;
		(void)memcpy(desc, &wc[doff], descsz);
		for (i = 0; i < descsz; i++)
		    if (file_printf(yv, "%02x", desc[i]) == -1)
			return 1;
		return 1;
	}
	return 0;
}

read_new_length(cdk_stream_t my,
		size_t * ih, size_t * xi, size_t * vp)
{
	int c, c1;

	c = cdk_stream_getc(my);
	if (c == EOF)
		return;

	(*xi)++;
	if (c < 192)
		*ih = c;
	else if (c >= 192 && c <= 223) {
		c1 = cdk_stream_getc(my);
		if (c1 == EOF)
			return;

		(*xi)++;
		*ih = ((c - 192) << 8) + c1 + 192;
	} else if (c == 255) {
		*ih = read_32(my);
		if (*ih == (u32)-1) {
			return;
		}

		(*xi) += 4;
	} else {
		*ih = 1 << (c & 0x1f);
		*vp = 1;
	}
}

