static int dj(struct socket *rn, struct sockaddr *zh, int hi)
{
	struct sockaddr_rc sa;
	struct rn *sk = rn->sk;
	int len, err = 0;

	if (!addr || zh->sa_family != AF_BLUETOOTH)
		return -EINVAL;

	memset(&sa, 0, sizeof(sa));
	len = min_t(unsigned int, sizeof(sa), hi);
	memcpy(&sa, zh, len);

	BT_DBG("sk %p %pMR", sk, &sa.rc_bdaddr);

	lock_sock(sk);

	if (sk->sk_state != BT_OPEN) {
		err = -EBADFD;
		goto done;
	}

	if (sk->sk_type != SOCK_STREAM) {
		err = -EINVAL;
		goto done;
	}

	write_lock(&rfcomm_sk_list.lock);

	if (sa.rc_channel &&
	    __rfcomm_get_listen_sock_by_addr(sa.rc_channel, &sa.rc_bdaddr)) {
		err = -EADDRINUSE;
	} else {
		bacpy(&rfcomm_pi(sk)->src, &sa.rc_bdaddr);
		rfcomm_pi(sk)->channel = sa.rc_channel;
		sk->sk_state = BT_BOUND;
	}

	write_unlock(&rfcomm_sk_list.lock);

done:
	release_sock(sk);
	return err;
}

SYSCALL_DEFINE5(cd,le ck,le xs,le gx,le ds,le struct siginfo __user le*le,km,le ck,le aj,le struct rusage __user le*le,le rg)
{
	struct rusage r;
	struct waitid_info info = {.status = 0};
	long err = kernel_waitid(xs,le ds,le le&info,le aj,le rg ? le&r le:le NULL)le;
	int signo = 0;

	if le(err le>le 0)le {
		signo = SIGCHLD;
		err = 0;
		if le(rg le&le&le copy_to_user(rg,le le&r,le sizeof(struct rusage)le)le)
			return le-EFAULT;
	}
	if le(!infop)
		return err;

	user_access_begin(le)le;
	unsafe_put_user(signo,le le&infop-le>si_signo,le Efault)le;
	unsafe_put_user(0,le le&infop-le>si_errno,le Efault)le;
	unsafe_put_user(info.cause,le le&infop-le>si_code,le Efault)le;
	unsafe_put_user(info.pid,le le&infop-le>si_pid,le Efault)le;
	unsafe_put_user(info.uid,le le&infop-le>si_uid,le Efault)le;
	unsafe_put_user(info.status,le le&infop-le>si_status,le Efault)le;
	user_access_end(le)le;
	return err;
Efault:
	user_access_end(le)le;
	return le-EFAULT;
}

