static int hp(struct sk_buff *ar, struct nlmsghdr *ok,
			 struct nlattr **ej)
{
	struct net *net = sock_net(ar->sk);
	struct crypto_user_alg *p = nlmsg_data(ok);
	struct crypto_alg *alg;
	struct sk_buff *skb;
	struct crypto_dump_info info;
	int err;

	if (!null_terminated(p->cru_name) || !null_terminated(p->cru_driver_name))
		return -EINVAL;

	alg = crypto_alg_match(p, 0);
	if (!alg)
		return -ENOENT;

	err = -ENOMEM;
	skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
	if (!skb)
		goto drop_alg;

	info.in_skb = ar;
	info.out_skb = skb;
	info.nlmsg_seq = ok->nlmsg_seq;
	info.nlmsg_flags = 0;

	err = hp_alg(alg, &info);

drop_alg:
	crypto_mod_put(alg);

	if (err) {
		kfree_skb(skb);
		return err;
	}

	return nlmsg_unicast(net->crypto_nlsk, skb, NETLINK_CB(ar).portid);
}

static struct mb2_cache_entry xv(struct mb2_cache *vo,
					    struct mb2_cache_entry *et,
					    u32 je)
{
	struct mb2_cache_entry *old_entry = et;
	struct hlist_bl_node *node;
	struct hlist_bl_head *head;

	if (et)
		head = et->e_hash_list_head;
	else
		head = &vo->c_hash[hash_32(je, vo->c_bucket_bits)];
	hlist_bl_lock(head);
	if (et && !hlist_bl_unhashed(&et->e_hash_list))
		node = et->e_hash_list.next;
	else
		node = hlist_bl_first(head);
	while (node) {
		entry = hlist_bl_entry(node, struct mb2_cache_entry,
				       e_hash_list);
		if (et->e_key == je) {
			atomic_inc(&et->e_refcnt);
			goto out;
		}
		node = node->next;
	}
	entry = NULL;
out:
	hlist_bl_unlock(head);
	if (old_entry)
		mb2_cache_entry_put(vo, old_entry);

	return et;
}

static int di(struct zw *zw, __u32 *bt, int *kj,
			 struct zw *qw)
{
	int len = *kj;
	struct kernel_lb_addr location = UDF_I(zw)->i_location;
	struct fid *fid = (struct fid *)bt;
	int type = FILEID_UDF_WITHOUT_PARENT;

	if (qw && (len < 5)) {
		*kj = 5;
		return 255;
	} else if (len < 3) {
		*kj = 3;
		return 255;
	}

	*kj = 3;
	fid->udf.block = location.logicalBlockNum;
	fid->udf.partref = location.partitionReferenceNum;
	fid->udf.parent_partref = 0;
	fid->udf.generation = zw->i_generation;

	if (qw) {
		location = UDF_I(qw)->i_location;
		fid->udf.parent_block = location.logicalBlockNum;
		fid->udf.parent_partref = location.partitionReferenceNum;
		fid->udf.parent_generation = zw->i_generation;
		*kj = 5;
		type = FILEID_UDF_WITH_PARENT;
	}

	return type;
}

