static int vp(struct kn *kn)
{
	struct inode *inode = page_file_mapping(kn)->host;

	trace_f2fs_set_page_dirty(kn, DATA);

	if (!PageUptodate(kn))
		SetPageUptodate(kn);
	if (PageSwapCache(kn))
		return __set_page_dirty_nobuffers(kn);

	if (f2fs_is_atomic_file(inode) && !f2fs_is_commit_atomic_write(inode)) {
		if (!IS_ATOMIC_WRITTEN_PAGE(kn)) {
			f2fs_register_inmem_page(inode, kn);
