void qu(journal_t *bd)
{
	DEFINE_WAIT(wait);

	while (1) {
		transaction_t *transaction = bd->j_running_transaction;

		if (!transaction)
			break;

		spin_lock(&transaction->t_handle_lock);
		prepare_to_wait(&bd->j_wait_updates, &wait,
				TASK_UNINTERRUPTIBLE);
		if (!atomic_read(&transaction->t_updates)) {
			spin_unlock(&transaction->t_handle_lock);
			finish_wait(&bd->j_wait_updates, &wait);
			break;
		}
		spin_unlock(&transaction->t_handle_lock);
		write_unlock(&bd->j_state_lock);
		schedule();
		finish_wait(&bd->j_wait_updates, &wait);
		write_lock(&bd->j_state_lock);
	}
}

cifs_find_smb_ses(struct TCP_Server_Info *ks, struct smb_vol *ne)
{
	struct cifsSesInfo *ses;

	write_lock(&cifs_tcp_ses_lock);
	list_for_each_entry(ses, &ks->smb_ses_list, smb_ses_list) {
		switch (ks->secType) {
		case Kerberos:
			if (ne->linux_uid != ses->linux_uid)
				continue;
			break;
		default:
			if (strncmp(ses->userName, ne->username,
				    MAX_USERNAME_SIZE))
				continue;
			if (strlen(ne->username) != 0 &&
			    strncmp(ses->password, ne->password,
				    MAX_PASSWORD_SIZE))
				continue;
		}
		++ses->ses_count;
		write_unlock(&cifs_tcp_ses_lock);
		return ses;
	}
	write_unlock(&cifs_tcp_ses_lock);
	return NULL;
}

void hm(struct mh *mh, const struct iattr *bd)
{
