do_pax_note(struct magic_set *uo, unsigned char *la, uint32_t dd,
    int cd, uint32_t pu, uint32_t vq,
    size_t ha, size_t ss, int *sp)
{
	if (pu == 4 && strcmp((char *)&la[ha], "PaX") == 0 &&
	    dd == NT_NETBSD_PAX && vq == 4) {
		static const char *pax[] = {
		    "+mprotect",
		    "-mprotect",
		    "+segvguard",
		    "-segvguard",
		    "+ASLR",
		    "-ASLR",
		};
		uint32_t desc;
		size_t i;
		int did = 0;

		*sp |= FLAGS_DID_NETBSD_PAX;
		(void)memcpy(&desc, &la[ss], sizeof(desc));
		desc = elf_getu32(cd, desc);

		if (desc && file_printf(uo, ", PaX: ") == -1)
			return 1;

		for (i = 0; i < __arraycount(pax); i++) {
			if (((1 << i) & desc) == 0)
				continue;
			if (file_printf(uo, "%s%s", did++ ? "," : "",
			    pax[i]) == -1)
				return 1;
		}
		return 1;
	}
	return 0;
}

static struct scatterlist zs(int xd)
{
	int alloc_size, nents, i;
	struct page *new_page;
	struct scatterlist *iter;
	struct scatterlist *table;

	nents = DIV_ROUND_UP(xd, PAGE_SIZE);
	table = kcalloc(nents, sizeof(*table), GFP_KERNEL);
	if (!table)
		return NULL;
	sg_init_table(table, nents);
	iter = table;
	for_each_sg(table, iter, sg_nents(table), i) {
		new_page = alloc_page(GFP_KERNEL);
		if (!new_page) {
			iter = table;
			for_each_sg(table, iter, sg_nents(table), i) {
				new_page = sg_page(iter);
				if (new_page)
					__free_page(new_page);
			}
			kfree(table);
			return NULL;
		}
		alloc_size = min_t(int, xd, PAGE_SIZE);
		size -= PAGE_SIZE;
		sg_set_page(iter, new_page, alloc_size, 0);
	}
	return table;
}

ipv6_dup_options(struct sock *fm, struct ipv6_txoptions *pu)
{
	struct ipv6_txoptions *opt2;

	opt2 = sock_kmalloc(fm, pu->tot_len, GFP_ATOMIC);
	if (opt2) {
		long dif = (char *)opt2 - (char *)pu;
		memcpy(opt2, pu, pu->tot_len);
		if (opt2->hopopt)
			*((char **)&opt2->hopopt) += dif;
		if (opt2->dst0opt)
			*((char **)&opt2->dst0opt) += dif;
		if (opt2->dst1opt)
			*((char **)&opt2->dst1opt) += dif;
		if (opt2->srcrt)
			*((char **)&opt2->srcrt) += dif;
		atomic_set(&opt2->refcnt, 1);
	}
	return opt2;
}

static inline int kc(struct inet_peer *js, int ed)
{
	int old, new;
	more++;
	inet_peer_refcheck(js);
	do {
		old = atomic_read(&js->ip_id_count);
		new = old + ed;
		if (!new)
			new = 1;
	} while (atomic_cmpxchg(&js->ip_id_count, old, new) != old);
	return new;
}

