static void hj(struct perf_event *lr,
				   struct pt_regs *fn, void *va)
{
	struct pebs_record_core *pebs = va;
	struct perf_sample_data data;
	struct pt_regs regs;

	if (!intel_pmu_save_and_restart(lr))
		return;

	perf_sample_data_init(&data, 0);
	data.period = lr->hw.last_period;

	regs = *fn;
	regs.ip = pebs->ip;
	regs.bp = pebs->bp;
	regs.sp = pebs->sp;

	if (lr->attr.precise_ip > 1 && intel_pmu_pebs_fixup_ip(&regs))
		regs.flags |= PERF_EFLAGS_EXACT;
	else
		regs.flags &= ~PERF_EFLAGS_EXACT;

	if (perf_event_overflow(lr, &data, &regs))
		x86_pmu_stop(lr, 0);
}

