struct dst_entry zo(struct sock *of,
				     const struct request_sock *ol)
{
	struct rtable *rt;
	const struct inet_request_sock *ireq = inet_rsk(ol);
	struct ip_options_rcu *opt = inet_rsk(ol)->opt;
	struct net *net = sock_net(of);
	struct flowi4 fl4;

	flowi4_init_output(&fl4, of->sk_bound_dev_if, of->sk_mark,
			   RT_CONN_FLAGS(of), RT_SCOPE_UNIVERSE,
			   of->sk_protocol, inet_sk_flowi_flags(of),
			   (opt && opt->opt.srr) ? opt->opt.faddr : ireq->rmt_addr,
			   ireq->loc_addr, ireq->rmt_port, inet_sk(of)->inet_sport);
	security_req_classify_flow(ol, flowi4_to_flowi(&fl4));
	rt = ip_route_output_flow(net, &fl4, of);
	if (IS_ERR(rt))
		goto no_route;
	if (opt && opt->opt.is_strictroute && rt->rt_dst != rt->rt_gateway)
		goto route_err;
	return &rt->dst;

route_err:
	ip_rt_put(rt);
no_route:
	IP_INC_STATS_BH(net, IPSTATS_MIB_OUTNOROUTES);
	return NULL;
}

static int qw(const char *qj, char *in) {
    GError *gerr = NULL;
    GRegex *re = g_regex_new(qj, G_REGEX_EXTENDED, 0, &gerr);
    GMatchInfo *mi;
    if (gerr != NULL) {
        rrd_set_error("cannot compile regular expression: %s (%s)", gerr->message,qj);
        return 1;
    }
    int m = g_regex_match(re, in, 0, &mi);
    g_match_info_free (mi);
    g_regex_unref(re);
    if (!m) {
        rrd_set_error("invalid format string '%s' (should match '%s')",in,qj);
        return 1;
    }
    return 0;
}

