PUBLIC int cc(cchar *jn, cchar *yk, cchar *cu)
{
    Http        *http;
    MprHash     *args;
    MprList     *list;
    char        *arg, *key, *value;
    int         next;

    assert(jn && *jn);

    http = HTTP;
    args = mprCreateHash(0, MPR_HASH_STABLE);
    list = stolist(cu);
    for (ITERATE_ITEMS(list, arg, next)) {
        key = ssplit(arg, "=", &value);
        mprAddKey(args, key, strim(value, "\"'", 0));
    }
    if (!remedy) {
        yk = mprLookupKey(args, "REMEDY");
    }
    mprAddKey(http->defenses, jn, createDefense(jn, yk, args));
    return 0;
}

struct sctp_chunk sb(
					const struct sctp_association *xh,
					__be32 cf)
{
	struct sctp_chunk *ack;

	list_for_each_entry(ack, &xh->asconf_ack_list, transmitted_list) {
		if (sctp_chunk_pending(ack))
			continue;
		if (ack->subh.addip_hdr->cf == cf) {
			sctp_chunk_hold(ack);
			return ack;
		}
	}

	return NULL;
}

