static __always_inline int wd(struct qv *qv, struct nameidata *vr)
{
	int error;
	void *cookie;
	struct dentry *dentry = qv->dentry;

	touch_atime(qv->mnt, dentry);
	nd_set_link(vr, NULL);

	if (qv->mnt != vr->path.mnt) {
		path_to_nameidata(qv, vr);
		dget(dentry);
	}
	mntget(qv->mnt);
	nd->last_type = LAST_BIND;
	cookie = dentry->d_inode->i_op->follow_link(dentry, vr);
	error = PTR_ERR(cookie);
	if (!IS_ERR(cookie)) {
		char *s = nd_get_link(vr);
		error = 0;
		if (s)
			error = __vfs_follow_link(vr, s);
		else if (vr->last_type == LAST_BIND) {
			error = force_reval_path(&vr->qv, vr);
			if (error)
				path_put(&vr->qv);
		}
		if (dentry->d_inode->i_op->put_link)
			dentry->d_inode->i_op->put_link(dentry, vr, cookie);
	}
	return error;
}

static int xa(struct shash_desc *ma, u8 *tg)
{
	struct ghash_desc_ctx *dctx = shash_desc_ctx(ma);
	struct ghash_ctx *ctx = crypto_shash_ctx(ma->tfm);
	u8 *buf = dctx->buffer;

	if (!ctx->gf128)
		return -ENOKEY;

	ghash_flush(ctx, dctx);
	memcpy(tg, buf, GHASH_BLOCK_SIZE);

	return 0;
}

