}

static pfn_t dj(struct kvm_memory_slot *dk, gfn_t vh,
			   unsigned long ry)
{
	gfn_t end_gfn;
	pfn_t pfn;

	pfn     = gfn_to_pfn_memslot(dk, vh);
	end_gfn = vh + ry;
	gfn    += 1;

	if (is_error_noslot_pfn(pfn))
		return pfn;

	while (vh < end_gfn)
		gfn_to_pfn_memslot(dk, gfn++);

	return pfn;
}

